    WHERE constraintObject.parent_object_id = OBJECT_ID(N'[SMigration].[Metadata_StagedRows]', N'U')
      AND constraintObject.name = N'UQ_Metadata_StagedRows_Run_Table_Row'
)
    BEGIN
        ALTER TABLE [SMigration].[Metadata_StagedRows] DROP CONSTRAINT [UQ_Metadata_StagedRows_Run_Table_Row];
    END;

    COMMIT TRANSACTION;
