/* Deploy View SSop.Quote_JobsSummary using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Views\SSop.Quote_JobsSummary.sql */
/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : View SSop.Quote_JobsSummary
    Source schema hash : B69E44B3246E9B007FF6D0C6CAFC2E7C127D94643C2C4F7724CFCDA835F21564
    Definition SHA-256 : 2504A95BE590DFD8F7C89B8FF3AADE66026B6A93AB029DA208BC1EAB98C35A97

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER VIEW [SSop].[Quote_JobsSummary]
	      --WITH SCHEMABINDING
AS
SELECT		MIN (qi.ID)							   AS ID,
			q.RowStatus,
			q.Guid								   AS QuoteGuid,
			q.Overview,
			--p.Guid								   AS UprnGuid,
			q.IsSubjectToNDA,
			SUM (qit.LineNet)					   AS Net,
			SUM (	CASE
						WHEN rs.Number = 1 THEN qit.LineNet
						ELSE 0
					END
				)								   AS RibaStage1Fee,
			SUM (	CASE
						WHEN rs.Number = 2 THEN qit.LineNet
						ELSE 0
					END
				)								   AS RibaStage2Fee,
			SUM (	CASE
						WHEN rs.Number = 3 THEN qit.LineNet
						ELSE 0
					END
				)								   AS RibaStage3Fee,
			SUM (	CASE
						WHEN rs.Number = 4 THEN qit.LineNet
						ELSE 0
					END
				)								   AS RibaStage4Fee,
			SUM (	CASE
						WHEN rs.Number = 5 THEN qit.LineNet
						ELSE 0
					END
				)								   AS RibaStage5Fee,
			SUM (	CASE
						WHEN rs.Number = 6 THEN qit.LineNet
						ELSE 0
					END
				)								   AS RibaStage6Fee,
			SUM (	CASE
						WHEN rs.Number = 7 THEN qit.LineNet
						ELSE 0
					END
				)								   AS RibaStage7Fee,
			SUM (	CASE
						WHEN rs.Number = 99 THEN qit.LineNet
						ELSE 0
					END
				)								   AS PreConstructionStageFee,
			SUM (	CASE
						WHEN rs.Number = 999 THEN qit.LineNet
						ELSE 0
					END
				)								   AS ConstructionStageFee,
			ou.Guid								   AS OrganisationalUnitGuid,
			jt.Guid								   AS JobTypeGuid,
			--acc.Guid							   AS ClientAccountGuid,
			--ad.Guid								   AS ClientAddressGuid,
			--c.Guid								   AS ClientContactGuid,
			cr.Guid								   AS ContractGuid,
			--agent_acc.Guid						   AS AgentAccountGuid,
			--agent_ad.Guid						   AS AgentAddressGuid,
			--agent_c.Guid						   AS AgentContactGuid,
			'00000000-0000-0000-0000-000000000000' AS IdentityGuid,
			-1									   AS QuoteItemId,
			q.ExternalReference,
			SUM (qit.LineNet)					   AS AgreedFee,
			jt.Name								   AS JobType,
			(
				SELECT MAX(dot.DateTimeUTC)
				FROM SCore.DataObjectTransition AS dot
				WHERE dot.DataObjectGuid = q.Guid
				  AND dot.StatusID = 7
			) AS DateAccepted,

			--q.DateAccepted,
			q.FeeCap,
			--proj.Guid							   AS ProjectGuid,
			ISNULL (   crs.Guid,
					   '00000000-0000-0000-0000-000000000000'
				   )							   AS CurrentRibaStageGuid,
			ISNULL (   ars.Guid,
					   '00000000-0000-0000-0000-000000000000'
				   )							   AS AppointedRibaStageGuid,
			q.ValueOfWork,
			acr.Guid							   AS AgentContractGuid
FROM		SSop.QuoteItems			  AS qi
JOIN		SSop.QuoteItemTotals	  AS qit ON (qit.ID				= qi.ID)
JOIN		SJob.RibaStages			  AS rs ON (rs.ID				= CASE WHEN qi.ProvideAtStageID = -1 THEN 2 ELSE qi.ProvideAtStageID END)
JOIN		SProd.Products			  AS p2 ON (p2.ID				= qi.ProductId)
JOIN		SSop.Quotes				  AS q ON (q.ID					= qi.QuoteId)
JOIN		SSop.EnquiryServices	  AS es ON (es.ID				= q.EnquiryServiceID)
JOIN		SJob.JobTypes			  AS jt ON (jt.ID = CASE WHEN p2.CreatedJobType > 0 THEN p2.CreatedJobType ELSE es.JobTypeId END)
JOIN		SCore.OrganisationalUnits AS ou ON (ou.ID				= q.OrganisationalUnitID)
JOIN		SSop.Contracts			  AS cr ON (cr.ID				= q.ContractID)
JOIN		SSop.Contracts			  AS acr ON (acr.ID				= q.AgentContractID)
JOIN		SSop.Enquiries			  AS e ON (e.ID					= es.EnquiryId)
JOIN		SJob.RibaStages			  AS crs ON (crs.ID				= e.CurrentProjectRibaStageID)
JOIN		SJob.RibaStages			  AS ars ON (ars.ID				= q.AppointmentFromRibaStageId)
--JOIN		SCrm.Accounts			  AS acc ON (acc.ID				= e.ClientAccountId)
--JOIN		SCrm.AccountAddresses	  AS ad ON (ad.ID				= e.ClientAddressId)
--JOIN		SCrm.AccountContacts	  AS c ON (c.ID					= e.ClientAccountContactId)
--JOIN		SCrm.Accounts			  AS agent_acc ON (agent_acc.ID = e.AgentAccountId)
--JOIN		SCrm.AccountAddresses	  AS agent_ad ON (agent_ad.ID	= e.AgentAddressId)
--JOIN		SCrm.AccountContacts	  AS agent_c ON (agent_c.ID		= e.AgentAccountContactId)
--JOIN		SJob.Properties			  AS p ON (p.ID					= e.PropertyId)
--JOIN		SSop.Projects			  AS proj ON (proj.ID			= e.ProjectId)
WHERE		(qi.RowStatus NOT IN (0, 254))
		AND (qi.Quantity			> 0)
		AND (qi.CreatedJobId		< 0)
		AND (qi.DoNotConsolidateJob = 0)
		AND (NOT EXISTS
	(
		SELECT	1
		FROM	SProd.Products AS prod2
		WHERE	(prod2.NeverConsolidate = 1)
			AND (qi.ProductId			= prod2.ID)
	)
			)
GROUP BY	q.RowStatus,
			q.Guid,
			q.Overview,
			--p.Guid,
			q.IsSubjectToNDA,
			jt.Guid,
			jt.Name,
			ou.Guid,
			--acc.Guid,
			--ad.Guid,
			--c.Guid,
			cr.Guid,
			--agent_acc.Guid,
			--agent_ad.Guid,
			--agent_c.Guid,
			q.ExternalReference,
			q.DateAccepted,
			q.FeeCap,
			--proj.Guid,
			crs.Guid,
			ars.Guid,
			q.ValueOfWork,
			q.AgentContractID,
			acr.Guid
UNION ALL
SELECT		qi.ID								  AS ID,
			q.RowStatus,
			q.Guid,
			q.Overview,
			--p.Guid,
			q.IsSubjectToNDA,
			qit.LineNet,
			CASE
				WHEN rs.Number = 1 THEN qit.LineNet
				ELSE 0
			END,
			CASE
				WHEN rs.Number = 2 THEN qit.LineNet
				ELSE 0
			END,
			CASE
				WHEN rs.Number = 3 THEN qit.LineNet
				ELSE 0
			END,
			CASE
				WHEN rs.Number = 4 THEN qit.LineNet
				ELSE 0
			END,
			CASE
				WHEN rs.Number = 5 THEN qit.LineNet
				ELSE 0
			END,
			CASE
				WHEN rs.Number = 6 THEN qit.LineNet
				ELSE 0
			END,
			CASE
				WHEN rs.Number = 7 THEN qit.LineNet
				ELSE 0
			END,
			CASE
				WHEN rs.Number = 99 THEN qit.LineNet
				ELSE 0
			END,
			CASE
				WHEN rs.Number = 999 THEN qit.LineNet
				ELSE 0
			END,
			ou.Guid,
			jt.Guid,
			--acc.Guid,
			--ad.Guid,
			--c.Guid,
			cr.Guid,
			--agent_acc.Guid,
			--agent_ad.Guid,
			--agent_c.Guid,
			'00000000-0000-0000-0000-000000000000',
			qi.ID,
			q.ExternalReference,
			--vow.Guid,
			qi.Net,
			jt.Name,
			--q.DateAccepted,
			(
				SELECT MAX(dot.DateTimeUTC)
				FROM SCore.DataObjectTransition AS dot
				JOIN SCore.WorkflowTransition AS wfs ON (wfs.ID = dot.StatusID)
				WHERE 
					(dot.DataObjectGuid = q.Guid)
				    AND (wfs.Guid = '21A29AEE-2D99-4DA3-8182-F31813B0C498')
			) AS DateAccepted,

			q.FeeCap,
			--proj.Guid							  AS ProjectGuid,
			ISNULL (   crs.Guid,
					   '00000000-0000-0000-0000-000000000000'
				   ),
			ISNULL (   ars.Guid,
					   '00000000-0000-0000-0000-000000000000'
				   ),
			q.ValueOfWork,
			acr.Guid
FROM		SSop.QuoteItems			  AS qi
JOIN		SSop.QuoteItemTotals	  AS qit ON (qit.ID				= qi.ID)
JOIN		SJob.RibaStages			  AS rs ON (rs.ID				= CASE WHEN qi.ProvideAtStageID = -1 THEN 2 ELSE qi.ProvideAtStageID END)
JOIN		SSop.Quotes				  AS q ON (q.ID				= qi.QuoteId)
JOIN		SProd.Products			  AS prod ON (prod.ID			= qi.ProductId)
JOIN		SSop.EnquiryServices	  AS es ON (es.ID				= q.EnquiryServiceID)
JOIN		SJob.JobTypes			  AS jt ON (jt.ID = CASE WHEN prod.CreatedJobType > 0 THEN prod.CreatedJobType ELSE es.JobTypeId END)
JOIN		SCore.OrganisationalUnits AS ou ON (ou.ID				= q.OrganisationalUnitID)
JOIN		SSop.Contracts			  AS cr ON (cr.ID				= q.ContractID)
JOIN		SSop.Contracts			  AS acr ON (acr.ID				= q.AgentContractID)
JOIN		SSop.Enquiries			  AS e ON (e.ID					= es.EnquiryId)
JOIN		SJob.RibaStages			  AS crs ON (crs.ID				= e.CurrentProjectRibaStageID)
JOIN		SJob.RibaStages			  AS ars ON (ars.ID				= q.AppointmentFromRibaStageId)
--JOIN		SCrm.Accounts			  AS acc ON (acc.ID				= e.ClientAccountId)
--JOIN		SCrm.AccountAddresses	  AS ad ON (ad.ID				= e.ClientAddressId)
--JOIN		SCrm.AccountContacts	  AS c ON (c.ID					= e.ClientAccountContactId)
--JOIN		SCrm.Accounts			  AS agent_acc ON (agent_acc.ID = e.AgentAccountId)
--JOIN		SCrm.AccountAddresses	  AS agent_ad ON (agent_ad.ID	= e.AgentAddressId)
--JOIN		SCrm.AccountContacts	  AS agent_c ON (agent_c.ID		= e.AgentAccountContactId)
--JOIN		SJob.Properties			  AS p ON (p.ID					= e.PropertyId)
--JOIN		SSop.Projects			  AS proj ON (proj.ID			= e.ProjectId)
WHERE		(qi.RowStatus NOT IN (0, 254))
		AND (qi.Quantity			  > 0)
		AND (qi.CreatedJobId		  < 0)
		AND
		  (
			  (prod.NeverConsolidate  = 1)
		   OR (qi.DoNotConsolidateJob = 1)
		  );
GO

GO

/* Deploy Function SSop.tvf_QuotesDataPills using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Functions\SSop.tvf_QuotesDataPills.sql */
/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : Function SSop.tvf_QuotesDataPills
    Source schema hash : 9380FA8409ABD3A775CF86E6FF7A0C0AD8BC9D9F4BDB796341B0B5123643ED26
    Definition SHA-256 : 1D1C86EE3C198D970D3F8A35B8C345EAB65C05BB8C56B502024F374DF1A55FE6

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER FUNCTION [SSop].[tvf_QuotesDataPills]
(
    @Guid                UNIQUEIDENTIFIER,
    @DateAccepted        DATE,
    @DateRejected        DATE,
    @ProjectGuid         UNIQUEIDENTIFIER,
    @ContractGuid        UNIQUEIDENTIFIER,
    @AgentContractGuid   UNIQUEIDENTIFIER
)
RETURNS @DataPills TABLE
(
    [ID]        [INT]        IDENTITY (1, 1) NOT NULL,
    [Label]     NVARCHAR(50) NOT NULL,
    [Class]     NVARCHAR(50) NOT NULL,
    [SortOrder] INT          NOT NULL
)
   --WITH SCHEMABINDING
AS
BEGIN

    -------------------------------------------------------------------------
    -- NDA (existing behaviour preserved)
    -------------------------------------------------------------------------
    DECLARE @IsSubjectToNDA BIT;
    DECLARE @ProjectID INT;

    SELECT @ProjectID = p.ID
    FROM SSop.Projects AS p
    WHERE p.Guid = @ProjectGuid;

    SELECT @IsSubjectToNDA = e.IsSubjectToNDA
    FROM SSop.Enquiries AS e
    WHERE e.ProjectId = @ProjectID;

    IF (@IsSubjectToNDA = 1)
    BEGIN
        INSERT @DataPills (Label, Class, SortOrder)
        VALUES (N'NDA', N'bg-danger', 1);
    END

    -------------------------------------------------------------------------
    -- Canonical workflow status GUIDs (locked rules)
    -------------------------------------------------------------------------
    DECLARE @ReadyToSendGuid UNIQUEIDENTIFIER = CONVERT(UNIQUEIDENTIFIER, '02A2237F-2AE7-4E05-926F-38E8B7D050A0'); -- ID 14
    DECLARE @SentGuid        UNIQUEIDENTIFIER = CONVERT(UNIQUEIDENTIFIER, '25D5491C-42A8-4B04-B3AC-D648AF0F8032');
    DECLARE @AcceptedGuid    UNIQUEIDENTIFIER = CONVERT(UNIQUEIDENTIFIER, '21A29AEE-2D99-4DA3-8182-F31813B0C498');
    DECLARE @RejectedGuid    UNIQUEIDENTIFIER = CONVERT(UNIQUEIDENTIFIER, '0A6A71F7-B39F-4213-997E-2B3A13B6144C');
    DECLARE @DeclinedGuid    UNIQUEIDENTIFIER = CONVERT(UNIQUEIDENTIFIER, '708C00E6-F45F-4CB2-8E91-A80B8B8E802E');
    DECLARE @DeadGuid        UNIQUEIDENTIFIER = CONVERT(UNIQUEIDENTIFIER, '8C7F7526-559F-4CCF-8FC2-DB0DA67E793D');
	DECLARE @FirstChase      UNIQUEIDENTIFIER = CONVERT(UNIQUEIDENTIFIER, '9FF22CEA-A2A6-4907-9B2D-E62DF8150913');
	DECLARE @SecondChase     UNIQUEIDENTIFIER = CONVERT(UNIQUEIDENTIFIER, '1F01C16B-1A73-4844-A938-FE357405FD93');
    DECLARE @ExpiredGuid     UNIQUEIDENTIFIER = CONVERT(UNIQUEIDENTIFIER, 'E6FAC201-F98B-4B3A-AB55-83DC9F802D00'); -- CYB-461

    -------------------------------------------------------------------------
    -- Latest workflow status for THIS quote (single source of truth)
    -------------------------------------------------------------------------
    DECLARE @LatestStatusName NVARCHAR(250) = NULL;
    DECLARE @LatestStatusGuid UNIQUEIDENTIFIER = NULL;
    DECLARE @LatestRequiresUsersAction BIT = 0;
    DECLARE @LatestIsCustomerWaiting BIT = 0;

    SELECT TOP (1)
        @LatestStatusName           = wfs.Name,
        @LatestStatusGuid           = wfs.Guid,
        @LatestRequiresUsersAction  = ISNULL(wfs.RequiresUsersAction, 0),
        @LatestIsCustomerWaiting    = ISNULL(wfs.IsCustomerWaitingStatus, 0)
    FROM SCore.DataObjectTransition dot
    JOIN SCore.WorkflowStatus wfs ON wfs.ID = dot.StatusID
    WHERE dot.DataObjectGuid = @Guid
      AND dot.RowStatus NOT IN (0,254)
      AND wfs.RowStatus NOT IN (0,254)
    ORDER BY dot.DateTimeUTC DESC, dot.ID DESC;

    -------------------------------------------------------------------------
    -- STATUS datapill: ONLY latest status (no historical EXISTS)
    -- Prefer GUID matching; label text remains as today for UI consistency.
    -------------------------------------------------------------------------
    IF (@LatestStatusGuid IS NOT NULL)
    BEGIN
        IF (@LatestStatusGuid = @ReadyToSendGuid)
        BEGIN
            INSERT @DataPills (Label, Class, SortOrder)
            VALUES (N'Ready To Send', N'bg-warning', 1);
        END
		ELSE IF (@LatestStatusGuid = @FirstChase)
        BEGIN
            INSERT @DataPills (Label, Class, SortOrder)
            VALUES (N'1st Chase', N'bg-info', 1);
        END
		ELSE IF (@LatestStatusGuid = @SecondChase)
        BEGIN
            INSERT @DataPills (Label, Class, SortOrder)
            VALUES (N'2nd Chase', N'bg-info', 1);
        END
        ELSE IF (@LatestStatusGuid = @SentGuid)
        BEGIN
            INSERT @DataPills (Label, Class, SortOrder)
            VALUES (N'Sent', N'bg-info', 1);
        END
        ELSE IF (@LatestStatusGuid = @AcceptedGuid)
        BEGIN
            INSERT @DataPills (Label, Class, SortOrder)
            VALUES (N'Customer Accepted', N'bg-success', 1);
        END
        ELSE IF (@LatestStatusGuid IN (@RejectedGuid, @DeclinedGuid, @DeadGuid, @ExpiredGuid))
        BEGIN
            -- Keep the displayed label consistent with the actual latest name.
            -- (So if it’s “Declined”, label is “Declined”, etc.)
            INSERT @DataPills (Label, Class, SortOrder)
            VALUES (ISNULL(@LatestStatusName, N'Status'), N'bg-danger', 1);
        END
        -- else: deliberately no pill for every workflow status.
    END

    -------------------------------------------------------------------------
    -- Jobs pending creation (preserved)
    -------------------------------------------------------------------------
    IF (@DateAccepted IS NOT NULL)
    BEGIN
        DECLARE @JobCount INT;

        SELECT @JobCount = COUNT(1)
        FROM SSop.Quote_JobsSummary js
        WHERE js.QuoteGuid = @Guid;

        IF (@JobCount > 0)
        BEGIN
            INSERT @DataPills (Label, Class, SortOrder)
            VALUES (CONVERT(NVARCHAR(50), @JobCount) + N' job(s) pending creation.', N'bg-warning', 1);
        END
    END

    -------------------------------------------------------------------------
    -- Finance Account Credit Hold (preserved)
    -------------------------------------------------------------------------
    IF (EXISTS
    (
        SELECT 1
        FROM SSop.Quotes AS Q
        JOIN SSop.Quote_ExtendedInfo AS QE ON QE.ID = Q.ID
        JOIN SCrm.Accounts AC ON AC.ID = QE.FinanceAccountId
        WHERE Q.Guid = @Guid
          AND AC.AccountStatusID = 4
    ))
    BEGIN
        INSERT @DataPills (Label, Class, SortOrder)
        VALUES (N'Credit Hold', N'bg-danger', 1);
    END

    -------------------------------------------------------------------------
    -- Contract pills (preserved)
    -------------------------------------------------------------------------
    IF(@ContractGuid <> '00000000-0000-0000-0000-000000000000'
       OR @AgentContractGuid <> '00000000-0000-0000-0000-000000000000')
    BEGIN
        INSERT @DataPills (Label, Class, SortOrder)
        VALUES (N'Contract In Place', N'bg-warning', 2);

        DECLARE @EndDate DATE, @NextReviewDate DATE;

        IF(@ContractGuid <> '00000000-0000-0000-0000-000000000000')
        BEGIN
            SELECT @EndDate = EndDate, @NextReviewDate = NextReviewDate
            FROM SSop.Contracts
            WHERE Guid = @ContractGuid;
        END
        ELSE
        BEGIN
            SELECT @EndDate = EndDate, @NextReviewDate = NextReviewDate
            FROM SSop.Contracts
            WHERE Guid = @AgentContractGuid;
        END

        IF (@EndDate IS NOT NULL AND DATEDIFF(DAY, GETDATE(), @EndDate) <= 30)
        BEGIN
            INSERT @DataPills (Label, Class, SortOrder)
            VALUES (N'Contract Ending In ' + CONVERT(NVARCHAR(10), DATEDIFF(DAY, GETDATE(), @EndDate)) + N' Days', N'bg-danger', 8);
        END

        IF (@NextReviewDate IS NOT NULL AND DATEDIFF(DAY, GETDATE(), @NextReviewDate) <= 30)
        BEGIN
            INSERT @DataPills (Label, Class, SortOrder)
            VALUES (N'Contract Needs Reviewing By ' + CONVERT(NVARCHAR(10), @NextReviewDate, 23), N'bg-danger', 9);
        END
    END

    -------------------------------------------------------------------------
    -- Latest-only: User Action Required / Customer Waiting (preserved)
    -------------------------------------------------------------------------
    IF (@LatestRequiresUsersAction = 1)
    BEGIN
        INSERT @DataPills (Label, Class, SortOrder)
        VALUES (N'User Action Required', N'bg-warning', 0);
    END

    IF (@LatestIsCustomerWaiting = 1)
    BEGIN
        INSERT @DataPills (Label, Class, SortOrder)
        VALUES (N'Awaiting Customer', N'bg-warning', 0);
    END

    RETURN;
END
GO

GO

/* Deploy View SSop.Quote_CalculatedFields using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Views\SSop.Quote_CalculatedFields.sql */
/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : View SSop.Quote_CalculatedFields
    Source schema hash : DD71E2CCB11A7F77B24F57BAFF2F660832ED1D236F39947EBDD2A55F8DAEEF89
    Definition SHA-256 : D17D6097E954BDD2566945769544FCC5E947B843A8D032871DDA049C23148FA1

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER VIEW [SSop].[Quote_CalculatedFields]
AS
SELECT
    q.ID,
    QuoteStatus =
        CASE
            ----------------------------------------------------------------------
            -- 1) JOB-DRIVEN COMPLETION (highest priority)
            --    Explicit calculated override retained by design.
            ----------------------------------------------------------------------
			WHEN LatestWorkflowStatus.Guid = Statuses.Quoting AND PreviousWorkflowStatus.Guid = Statuses.Reopened
				THEN N'Reopened'
			
			WHEN LatestWorkflowStatus.Guid = Statuses.Reopened
                THEN N'Reopened'

            WHEN JobAgg.CreatedJobsCount >= 1
                 AND JobAgg.PendingJobsCount = 0
                THEN N'Complete'

            WHEN JobAgg.CreatedJobsCount >= 1
                 AND JobAgg.PendingJobsCount >= 1
                THEN N'Part Complete'

            ----------------------------------------------------------------------
            -- 1B) EXPIRY (CYB-461)
            --    A quote still in progress expires once its ExpiryDate has
            --    passed. Accepted, Rejected, Dead, Declined, Complete and
            --    Reopened quotes never expire.
            ----------------------------------------------------------------------
            WHEN LatestWorkflowStatus.Guid IN
                 (
                     Statuses.Quoting,
                     Statuses.ReadyToSend,
                     Statuses.Sent,
                     Statuses.firstChase,
                     Statuses.secondChase
                 )
                 AND q.ExpiryDate < NowUtc.TodayUtc
                THEN N'Expired'

            ----------------------------------------------------------------------
            -- 2) WORKFLOW IS SOURCE OF TRUTH
            --    If there is a latest workflow transition, show it.
            --    This prevents inferred "Ready to Send" / legacy flags from
            --    overriding a real latest workflow such as "Quoting".
            ----------------------------------------------------------------------
			

            WHEN LatestWorkflowStatus.Guid = Statuses.Declined
                THEN N'Declined'

            WHEN LatestWorkflowStatus.Guid = Statuses.Dead
                THEN N'Dead'

            WHEN LatestWorkflowStatus.Guid = Statuses.Accepted
                THEN N'Accepted'

            WHEN LatestWorkflowStatus.Guid = Statuses.Rejected
                THEN N'Rejected'

            WHEN LatestWorkflowStatus.Guid = Statuses.secondChase
                THEN N'2nd Chase'

            WHEN LatestWorkflowStatus.Guid = Statuses.firstChase
                THEN N'1st Chase'

            WHEN LatestWorkflowStatus.Guid = Statuses.Sent
                THEN N'Sent'

            WHEN LatestWorkflowStatus.Guid = Statuses.ReadyToSend
                THEN N'Ready to Send'

			

            ----------------------------------------------------------------------
            -- 3) CUSTOM / OTHER WORKFLOW NAMES
            --    Preserve non-standard workflow names once standard mappings above
            --    have been handled.
            ----------------------------------------------------------------------
            WHEN LatestWorkflowStatus.Name IS NOT NULL
                 AND LatestWorkflowStatus.Name NOT IN
                 (
                     N'N/A',
                     N'Sent',
                     N'Accepted',
                     N'Rejected',
                     N'Dead',
                     N'Ready to Send',
                     N'Declined',
                     N'Complete',
                     N'Part Complete',
                     N'1st Chase',
                     N'2nd Chase'
                 )
                THEN LatestWorkflowStatus.Name

            ----------------------------------------------------------------------
            -- 4) LEGACY FALLBACK ONLY WHEN NO WORKFLOW EXISTS
            --    Retained for backward compatibility with older rows that do not
            --    yet have transition history.
            ----------------------------------------------------------------------
            WHEN LatestWorkflowStatus.Guid IS NULL
                 AND q.DateDeclinedToQuote IS NOT NULL
                THEN N'Declined'

            WHEN LatestWorkflowStatus.Guid IS NULL
                 AND q.DeadDate IS NOT NULL
                THEN N'Dead'

            WHEN LatestWorkflowStatus.Guid IS NULL
                 AND q.DateAccepted IS NOT NULL
                THEN N'Accepted'

            WHEN LatestWorkflowStatus.Guid IS NULL
                 AND q.DateRejected IS NOT NULL
                THEN N'Rejected'

            WHEN LatestWorkflowStatus.Guid IS NULL
                 AND q.ExpiryDate < NowUtc.TodayUtc
                THEN N'Expired'

            WHEN LatestWorkflowStatus.Guid IS NULL
                 AND q.ChaseDate2 IS NOT NULL
                THEN N'2nd Chase'

            WHEN LatestWorkflowStatus.Guid IS NULL
                 AND q.ChaseDate1 IS NOT NULL
                THEN N'1st Chase'

            WHEN LatestWorkflowStatus.Guid IS NULL
                 AND q.DateSent IS NOT NULL
                THEN N'Sent'

            WHEN LatestWorkflowStatus.Guid IS NULL
                 AND q.IsFinal = 1
                THEN N'Ready to Send'

            ----------------------------------------------------------------------
            -- 5) DEFAULT
            ----------------------------------------------------------------------
            ELSE N'Quoting'
        END
FROM SSop.Quotes AS q

OUTER APPLY
(
    SELECT
        NowUtc   = CONVERT(datetime2(7), SYSUTCDATETIME()),
        TodayUtc = CONVERT(date, SYSUTCDATETIME())
) AS NowUtc

OUTER APPLY
(
    SELECT
        IsRevision =
            CASE
                WHEN ISNULL(q.RevisionNumber, 0) > 0
                     OR q.OriginalQuoteId <> -1
                    THEN 1
                ELSE 0
            END
) AS IsRevision

OUTER APPLY
(
    SELECT
        TotalItems  = COUNT(1),
        ValuedItems = SUM(CASE WHEN qi.Net > 0 THEN 1 ELSE 0 END)
    FROM SSop.QuoteItems qi
    WHERE qi.QuoteId = q.ID
      AND qi.RowStatus NOT IN (0,254)
) AS QuoteItemAgg

OUTER APPLY
(
    SELECT
        CreatedJobsCount =
        (
            SELECT COUNT(DISTINCT qi.CreatedJobId)
            FROM SSop.QuoteItems qi
            WHERE qi.QuoteId = q.ID
              AND qi.RowStatus NOT IN (0,254)
              AND qi.CreatedJobId IS NOT NULL
              AND qi.CreatedJobId > 0
        ),
        PendingJobsCount =
        (
            SELECT COUNT(1)
            FROM SSop.Quote_JobsSummary js
            WHERE js.QuoteGuid = q.Guid
              AND js.RowStatus NOT IN (0,254)
        )
) AS JobAgg

OUTER APPLY
(
    SELECT
        Declined    = CONVERT(uniqueidentifier, '708C00E6-F45F-4CB2-8E91-A80B8B8E802E'),
        Dead        = CONVERT(uniqueidentifier, '8C7F7526-559F-4CCF-8FC2-DB0DA67E793D'),
        Accepted    = CONVERT(uniqueidentifier, '21A29AEE-2D99-4DA3-8182-F31813B0C498'),
        ReadyToSend = CONVERT(uniqueidentifier, '02A2237F-2AE7-4E05-926F-38E8B7D050A0'),
        Rejected    = CONVERT(uniqueidentifier, '0A6A71F7-B39F-4213-997E-2B3A13B6144C'),
        Sent        = CONVERT(uniqueidentifier, '25D5491C-42A8-4B04-B3AC-D648AF0F8032'),
        firstChase  = CONVERT(uniqueidentifier, '9FF22CEA-A2A6-4907-9B2D-E62DF8150913'),
        secondChase = CONVERT(uniqueidentifier, '1F01C16B-1A73-4844-A938-FE357405FD93'),
		Reopened    = CONVERT(uniqueidentifier, '34EF363A-C8F7-4BA8-A2C6-067EBAEF12FD'),
		Quoting     = CONVERT(uniqueidentifier, '9A60F983-24BA-4733-907E-C5CCE0B691CB')
) AS Statuses

OUTER APPLY
(
    SELECT TOP (1)
        Name = wfs.Name,
        Guid = wfs.Guid
    FROM SCore.DataObjectTransition dot
    JOIN SCore.WorkflowStatus wfs
        ON wfs.ID = dot.StatusID
    WHERE dot.DataObjectGuid = q.Guid
      AND dot.RowStatus NOT IN (0,254)
      AND wfs.RowStatus NOT IN (0,254)
    ORDER BY dot.ID DESC
) AS LatestWorkflowStatus

OUTER APPLY
(
    SELECT TOP (1)
        Name = wfs.Name,
        Guid = wfs.Guid
    FROM SCore.DataObjectTransition dot
    JOIN SCore.WorkflowStatus wfs
        ON wfs.ID = dot.OldStatusID
    WHERE dot.DataObjectGuid = q.Guid
      AND dot.RowStatus NOT IN (0,254)
      AND wfs.RowStatus NOT IN (0,254)
    ORDER BY dot.ID DESC
) AS PreviousWorkflowStatus

OUTER APPLY
(
    SELECT
        IsPreSentQuoting =
            CASE
                WHEN ISNULL
                     (
                         LatestWorkflowStatus.Guid,
                         CONVERT(uniqueidentifier, '00000000-0000-0000-0000-000000000000')
                     ) NOT IN
                     (
                         Statuses.Sent,
                         Statuses.Accepted,
                         Statuses.Rejected,
                         Statuses.Declined,
                         Statuses.Dead,
                         Statuses.firstChase,
                         Statuses.secondChase
                     )
                     AND q.DateSent IS NULL
                     AND q.DateAccepted IS NULL
                     AND q.DateRejected IS NULL
                     AND q.DateDeclinedToQuote IS NULL
                     AND q.DeadDate IS NULL
                     AND q.ChaseDate1 IS NULL
                     AND q.ChaseDate2 IS NULL
                     AND q.IsFinal = 0
                    THEN 1
                ELSE 0
            END
) AS QuotePhase;
GO

