/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : StoredProcedure SCore.DataObjects_ResolveEntityTypeConflicts
    Source schema hash : 4A82EA90E5DCE9D730F56A3AD23E1B694060B0D9AEF71737882793782719843D
    Definition SHA-256 : 29520C8515260F4394EA6F3A3AC3F9EFA617B79B35995F3295A974C0CC67C9E6

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/* =============================================================================
   SCore.DataObjects_ResolveEntityTypeConflicts

   Purpose
   -------
   Detect and optionally fix "EntityTypeId mismatch" conflicts:

     - For each EntityType registered in SCore.DataObjectEntityRegistry,
       we expect:
           SCore.DataObjects.Guid = <entity row Guid>
           AND SCore.DataObjects.EntityTypeId = <registry EntityTypeId>

     - Conflict = entity row exists, but DataObjects has same Guid with a
       DIFFERENT EntityTypeId.

   Actions
   -------
     @Action = 'REPORT'   : report only (default)
     @Action = 'REASSIGN' : update SCore.DataObjects.EntityTypeId to ExpectedEntityTypeId
                            (safe-guards applied)

   Safety guards
   -------------
   - never touches ZeroGuid (0000...)
   - never updates rows where a Guid appears in multiple entity tables (ambiguous)
   - optional ignore lists (tables or entity types)

   Recommended use
   ---------------
     EXEC SCore.DataObjects_ResolveEntityTypeConflicts @Action='REPORT';
     -- review results
     EXEC SCore.DataObjects_ResolveEntityTypeConflicts @Action='REASSIGN', @Apply=0; -- shows what would change
     EXEC SCore.DataObjects_ResolveEntityTypeConflicts @Action='REASSIGN', @Apply=1; -- apply
============================================================================= */
CREATE OR ALTER PROCEDURE [SCore].[DataObjects_ResolveEntityTypeConflicts]
(
      @Apply          BIT = 0                -- 0=report only, 1=apply chosen action
    , @Action         NVARCHAR(20) = N'REPORT'-- REPORT | REASSIGN | IGNORE
    , @IncludeDeleted BIT = 0                -- 0=exclude entity RowStatus in (0,254), 1=include them
    , @Verbose        BIT = 1
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @RunGuid UNIQUEIDENTIFIER = NEWID();
    DECLARE @NowUtc  DATETIME2(7)     = SYSUTCDATETIME();
    DECLARE @ZeroGuid UNIQUEIDENTIFIER = '00000000-0000-0000-0000-000000000000';

    IF @Verbose = 1
        PRINT N'Running SCore.DataObjects_ResolveEntityTypeConflicts. RunGuid='
              + CONVERT(NVARCHAR(36), @RunGuid)
              + N' Action=' + @Action
              + N' Apply=' + CONVERT(NVARCHAR(10), @Apply)
              + N' IncludeDeleted=' + CONVERT(NVARCHAR(10), @IncludeDeleted);

    /* ---------------------------------------------------------------------
       Ignore table: SCore.DataObjectEntityTypeConflictIgnores, with its key
       and indexes, is deployed from Schema/Tables (CYB-578).
    --------------------------------------------------------------------- */

    /* ---------------------------------------------------------------------
       Temp tables
    --------------------------------------------------------------------- */
    IF OBJECT_ID('tempdb..#Conflicts') IS NOT NULL DROP TABLE #Conflicts;
    CREATE TABLE #Conflicts
    (
          FindingRunGuid        UNIQUEIDENTIFIER NOT NULL
        , ExpectedEntityTypeId  INT              NOT NULL
        , ActualEntityTypeId    INT              NOT NULL
        , SchemaName            SYSNAME          NOT NULL
        , TableName             SYSNAME          NOT NULL
        , EntityGuid            UNIQUEIDENTIFIER NOT NULL
        , EntityRowStatus       TINYINT          NULL
        , DataObjectRowStatus   TINYINT          NULL
    );

    IF OBJECT_ID('tempdb..#ConflictsEnriched') IS NOT NULL DROP TABLE #ConflictsEnriched;
    CREATE TABLE #ConflictsEnriched
    (
          FindingRunGuid        UNIQUEIDENTIFIER NOT NULL
        , ExpectedEntityTypeId  INT              NOT NULL
        , ExpectedEntityTypeName NVARCHAR(255)   NULL
        , ActualEntityTypeId    INT              NOT NULL
        , ActualEntityTypeName  NVARCHAR(255)    NULL
        , SchemaName            SYSNAME          NOT NULL
        , TableName             SYSNAME          NOT NULL
        , EntityGuid            UNIQUEIDENTIFIER NOT NULL
        , EntityRowStatus       TINYINT          NULL
        , DataObjectRowStatus   TINYINT          NULL
        , Details               NVARCHAR(4000)   NULL
    );

    /* ---------------------------------------------------------------------
       Iterate registry rows and collect conflicts (dynamic SQL per table)
    --------------------------------------------------------------------- */
    DECLARE
          @EntityTypeId INT
        , @SchemaName   SYSNAME
        , @TableName    SYSNAME
        , @GuidColumn   SYSNAME
        , @RowStatusCol SYSNAME;

    DECLARE cur CURSOR LOCAL FAST_FORWARD FOR
        SELECT EntityTypeId, SchemaName, TableName, GuidColumn, RowStatusColumn
        FROM SCore.DataObjectEntityRegistry
        ORDER BY EntityTypeId;

    OPEN cur;
    FETCH NEXT FROM cur INTO @EntityTypeId, @SchemaName, @TableName, @GuidColumn, @RowStatusCol;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        BEGIN TRY
            DECLARE @sql NVARCHAR(MAX);

            /* Important:
               - We do NOT use a CTE and then reference it later.
               - We do ONE INSERT statement per execution, so scope is clean.
            */
            SET @sql =
N'
INSERT INTO #Conflicts
(
      FindingRunGuid
    , ExpectedEntityTypeId
    , ActualEntityTypeId
    , SchemaName
    , TableName
    , EntityGuid
    , EntityRowStatus
    , DataObjectRowStatus
)
SELECT
      @RunGuid
    , @ExpectedEntityTypeId
    , d.EntityTypeId AS ActualEntityTypeId
    , @SchemaName
    , @TableName
    , e.' + QUOTENAME(@GuidColumn) + N' AS EntityGuid
    , ' + CASE WHEN @IncludeDeleted = 1
               THEN N'CAST(NULL AS TINYINT)'
               ELSE N'e.' + QUOTENAME(@RowStatusCol)
          END + N' AS EntityRowStatus
    , d.RowStatus AS DataObjectRowStatus
FROM ' + QUOTENAME(@SchemaName) + N'.' + QUOTENAME(@TableName) + N' e
JOIN SCore.DataObjects d
    ON d.Guid = e.' + QUOTENAME(@GuidColumn) + N'
WHERE
    e.' + QUOTENAME(@GuidColumn) + N' <> @ZeroGuid
    AND d.Guid <> @ZeroGuid
    AND d.EntityTypeId <> @ExpectedEntityTypeId
    ' + CASE WHEN @IncludeDeleted = 1
             THEN N''
             ELSE N'AND e.' + QUOTENAME(@RowStatusCol) + N' NOT IN (0,254)'
        END + N'
    AND d.RowStatus NOT IN (0,254);
';

            EXEC sp_executesql
                @sql,
                N'@RunGuid UNIQUEIDENTIFIER,
                  @ExpectedEntityTypeId INT,
                  @SchemaName SYSNAME,
                  @TableName SYSNAME,
                  @ZeroGuid UNIQUEIDENTIFIER',
                @RunGuid = @RunGuid,
                @ExpectedEntityTypeId = @EntityTypeId,
                @SchemaName = @SchemaName,
                @TableName = @TableName,
                @ZeroGuid = @ZeroGuid;
        END TRY
        BEGIN CATCH
            /* Record table-level errors into enriched table (so they show in summary) */
            INSERT INTO #ConflictsEnriched
            (
                  FindingRunGuid
                , ExpectedEntityTypeId
                , ActualEntityTypeId
                , SchemaName
                , TableName
                , EntityGuid
                , Details
            )
            VALUES
            (
                  @RunGuid
                , @EntityTypeId
                , -1
                , @SchemaName
                , @TableName
                , @ZeroGuid
                , N'Error ' + CONVERT(NVARCHAR(20), ERROR_NUMBER()) + N': ' + ERROR_MESSAGE()
            );
        END CATCH;

        FETCH NEXT FROM cur INTO @EntityTypeId, @SchemaName, @TableName, @GuidColumn, @RowStatusCol;
    END

    CLOSE cur;
    DEALLOCATE cur;

    /* ---------------------------------------------------------------------
       Enrich conflicts with entity type names + details
    --------------------------------------------------------------------- */
    INSERT INTO #ConflictsEnriched
    (
          FindingRunGuid
        , ExpectedEntityTypeId
        , ExpectedEntityTypeName
        , ActualEntityTypeId
        , ActualEntityTypeName
        , SchemaName
        , TableName
        , EntityGuid
        , EntityRowStatus
        , DataObjectRowStatus
        , Details
    )
    SELECT
          c.FindingRunGuid
        , c.ExpectedEntityTypeId
        , etExp.Name
        , c.ActualEntityTypeId
        , etAct.Name
        , c.SchemaName
        , c.TableName
        , c.EntityGuid
        , c.EntityRowStatus
        , c.DataObjectRowStatus
        , N'Guid exists in SCore.DataObjects with EntityTypeId=' + CONVERT(NVARCHAR(20), c.ActualEntityTypeId)
          + N' but entity table implies EntityTypeId=' + CONVERT(NVARCHAR(20), c.ExpectedEntityTypeId)
    FROM #Conflicts c
    LEFT JOIN SCore.EntityTypes etExp ON etExp.ID = c.ExpectedEntityTypeId
    LEFT JOIN SCore.EntityTypes etAct ON etAct.ID = c.ActualEntityTypeId;

    /* ---------------------------------------------------------------------
       REPORT outputs
    --------------------------------------------------------------------- */
    ;WITH Pairs AS
    (
        SELECT
              ExpectedEntityTypeId
            , ExpectedEntityTypeName
            , ActualEntityTypeId
            , ActualEntityTypeName
            , COUNT(*) AS ConflictCount
        FROM #ConflictsEnriched
        WHERE EntityGuid <> @ZeroGuid
          AND ActualEntityTypeId <> -1
        GROUP BY
              ExpectedEntityTypeId, ExpectedEntityTypeName
            , ActualEntityTypeId,   ActualEntityTypeName
    )
    SELECT
          @RunGuid AS FindingRunGuid
        , ExpectedEntityTypeId, ExpectedEntityTypeName
        , ActualEntityTypeId,   ActualEntityTypeName
        , ConflictCount
    FROM Pairs
    ORDER BY ConflictCount DESC, ExpectedEntityTypeId, ActualEntityTypeId;

    /* Sample rows (top 500) */
    SELECT TOP (500)
          FindingRunGuid
        , ExpectedEntityTypeId, ExpectedEntityTypeName
        , ActualEntityTypeId,   ActualEntityTypeName
        , SchemaName, TableName
        , EntityGuid
        , EntityRowStatus
        , DataObjectRowStatus
        , Details
    FROM #ConflictsEnriched
    ORDER BY ExpectedEntityTypeId, ActualEntityTypeId, SchemaName, TableName;

    /* ---------------------------------------------------------------------
       APPLY action (optional)
    --------------------------------------------------------------------- */
    IF @Apply = 1 AND @Action <> N'REPORT'
    BEGIN
        BEGIN TRAN;

        /* REASSIGN = update SCore.DataObjects.EntityTypeId to the expected type */
        IF @Action = N'REASSIGN'
        BEGIN
            UPDATE d
                SET d.EntityTypeId = c.ExpectedEntityTypeId
            FROM SCore.DataObjects d
            JOIN #Conflicts c
              ON c.EntityGuid = d.Guid
            WHERE
                d.Guid <> @ZeroGuid
                AND d.RowStatus NOT IN (0,254)
                AND d.EntityTypeId = c.ActualEntityTypeId
                AND d.EntityTypeId <> c.ExpectedEntityTypeId;
        END

        /* IGNORE = record ignore rows (no DB changes to DataObjects) */
        IF @Action = N'IGNORE'
        BEGIN
            INSERT INTO SCore.DataObjectEntityTypeConflictIgnores
            (
                  ExpectedEntityTypeId
                , ActualEntityTypeId
                , EntityGuid
                , SchemaName
                , TableName
                , Reason
            )
            SELECT
                  c.ExpectedEntityTypeId
                , c.ActualEntityTypeId
                , c.EntityGuid
                , c.SchemaName
                , c.TableName
                , N'Ignored via resolver procedure. RunGuid=' + CONVERT(NVARCHAR(36), @RunGuid)
            FROM #Conflicts c
            WHERE c.EntityGuid <> @ZeroGuid;
        END

        COMMIT TRAN;

        IF @Verbose = 1
            PRINT N'Apply complete. RunGuid=' + CONVERT(NVARCHAR(36), @RunGuid)
                  + N' Action=' + @Action;
    END
END
GO

GO

/* Deploy StoredProcedure SCore.DataObjectTransitionUpsert using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SCore.DataObjectTransitionUpsert.sql */
/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : StoredProcedure SCore.DataObjectTransitionUpsert
    Source schema hash : 0F51BEC78A03212B2913154D12600C33231E21CCEA870D8B25AD97091EA68568
    Definition SHA-256 : ABC58C1223F3F51540CF48C2944C4A5607EB10DD11B51B21E436A1094E9E745A

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/* =============================================================================
   CYB-101 – QA enforcement fix (write-path)
   Object: SCore.DataObjectTransitionUpsert

   QA issue(s) being resolved:
   - QA BLOCKER: "Quote can be changed to Sent/Accepted without Quote item is created"
     • Enquiry 2569 / Quote 2340
     • Enquiry 2574 (pending confirmation)

   Guardrails (respected):
   - NO workflow meaning / lifecycle / allowed transitions changes.
   - Enforcement/validation only at the write-path.
   - Existing "Ready to Send requires Net > 0" rule remains intact.

   What I changed (and why):
   - Added a hard validation for QUOTES:
       If attempting to set Quote to "Sent" or "Accepted",
       the Quote MUST have at least 1 active QuoteItem.
     This prevents the invalid state QA has recorded, even if the UI is bypassed.
============================================================================= */
CREATE OR ALTER PROCEDURE [SCore].[DataObjectTransitionUpsert]
(
    @Guid UNIQUEIDENTIFIER,
    @OldStatusGuid UNIQUEIDENTIFIER,
    @StatusGuid UNIQUEIDENTIFIER,
    @Comment NVARCHAR(MAX),
    @CreatedByUserGuid UNIQUEIDENTIFIER,
    @SurveyorUserGuid UNIQUEIDENTIFIER,
    @DataObjectGuid UNIQUEIDENTIFIER,
    @IsImported BIT
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @DateTimeUTC DATETIME2(7) = SYSUTCDATETIME();

    DECLARE @TraceId UNIQUEIDENTIFIER = NEWID();
    DECLARE @ProcName SYSNAME = QUOTENAME(OBJECT_SCHEMA_NAME(@@PROCID)) + N'.' + QUOTENAME(OBJECT_NAME(@@PROCID));

    BEGIN TRY
        BEGIN TRAN;

        -------------------------------------------------------------------------
        -- Guard: transitioned record must exist in SCore.DataObjects
        -------------------------------------------------------------------------
        IF NOT EXISTS
        (
            SELECT 1
            FROM SCore.DataObjects dob
            WHERE dob.Guid = @DataObjectGuid
              AND dob.RowStatus NOT IN (0,254)
        )
            THROW 60002, N'DataObjectTransitionUpsert: DataObjectGuid not found in SCore.DataObjects (record does not exist).', 1;

        -------------------------------------------------------------------------
        -- Resolve CreatedBy / Surveyor IDs
        -------------------------------------------------------------------------
        DECLARE @CreatedByUserID INT = NULL;
        SELECT @CreatedByUserID = i.ID
        FROM SCore.Identities i
        WHERE i.Guid = @CreatedByUserGuid;

        DECLARE @SurveyorUserID INT = NULL;
        SELECT @SurveyorUserID = i.ID
        FROM SCore.Identities i
        WHERE i.Guid = @SurveyorUserGuid;

        -------------------------------------------------------------------------
        -- Resolve incoming WorkflowStatus
        -------------------------------------------------------------------------
        DECLARE @StatusID INT = NULL;
        DECLARE @StatusName NVARCHAR(255) = NULL;
        DECLARE @ShowInQuotes BIT = 0;
        DECLARE @ShowInEnquiries BIT = 0;
        DECLARE @ShowInJobs BIT = 0;

        SELECT
            @StatusID = wfs.ID,
            @StatusName = wfs.Name,
            @ShowInQuotes = wfs.ShowInQuotes,
            @ShowInEnquiries = wfs.ShowInEnquiries,
            @ShowInJobs = wfs.ShowInJobs
        FROM SCore.WorkflowStatus wfs
        WHERE wfs.Guid = @StatusGuid
          AND wfs.RowStatus NOT IN (0,254);

        IF (@StatusID IS NULL)
            THROW 60001, N'Invalid StatusGuid passed to DataObjectTransitionUpsert (no matching WorkflowStatus).', 1;

        -------------------------------------------------------------------------
        -- Determine entity type guid of the transitioned record
        -------------------------------------------------------------------------
        DECLARE @RecordTypeGuid UNIQUEIDENTIFIER = NULL;

        SELECT TOP (1) @RecordTypeGuid = et.Guid
        FROM SCore.DataObjects dob
        JOIN SCore.EntityTypes et ON et.ID = dob.EntityTypeId
        WHERE dob.Guid = @DataObjectGuid
          AND dob.RowStatus NOT IN (0,254);

        -------------------------------------------------------------------------
        -- ENFORCE: Status must match the entity type being transitioned.
        -------------------------------------------------------------------------
        DECLARE @IsEnquiry UNIQUEIDENTIFIER;
        DECLARE @IsQuote   UNIQUEIDENTIFIER;
        DECLARE @IsJob     UNIQUEIDENTIFIER;

        SELECT @IsEnquiry = Guid FROM SCore.EntityTypes WHERE Name = N'Enquiries';
        SELECT @IsQuote   = Guid FROM SCore.EntityTypes WHERE Name = N'Quotes';
        SELECT @IsJob     = Guid FROM SCore.EntityTypes WHERE Name = N'Jobs';

        IF (@RecordTypeGuid = @IsEnquiry)
        BEGIN
            SELECT TOP (1) @StatusID = ws.ID
            FROM SCore.WorkflowStatus ws
            WHERE ws.RowStatus NOT IN (0,254)
              AND ws.ShowInEnquiries = 1
              AND ws.Name = @StatusName
            ORDER BY ws.ID;

            IF (@StatusID IS NULL)
                THROW 60011, N'Invalid status for Enquiry: no WorkflowStatus exists with this Name where ShowInEnquiries=1.', 1;
        END
        ELSE IF (@RecordTypeGuid = @IsQuote)
        BEGIN
            SELECT TOP (1) @StatusID = ws.ID
            FROM SCore.WorkflowStatus ws
            WHERE ws.RowStatus NOT IN (0,254)
              AND ws.ShowInQuotes = 1
              AND ws.Name = @StatusName
            ORDER BY ws.ID;

            IF (@StatusID IS NULL)
                THROW 60012, N'Invalid status for Quote: no WorkflowStatus exists with this Name where ShowInQuotes=1.', 1;
        END
        ELSE IF (@RecordTypeGuid = @IsJob)
        BEGIN
            SELECT TOP (1) @StatusID = ws.ID
            FROM SCore.WorkflowStatus ws
            WHERE ws.RowStatus NOT IN (0,254)
              AND ws.ShowInJobs = 1
              AND ws.Name = @StatusName
            ORDER BY ws.ID;

            IF (@StatusID IS NULL)
                THROW 60013, N'Invalid status for Job: no WorkflowStatus exists with this Name where ShowInJobs=1.', 1;
        END

        /* ----------------------------------------------------------------------
           CYB-101 QA ENFORCEMENT (WRITE-PATH)
           Quote cannot be set to Sent/Accepted unless it has at least 1 QuoteItem.

           Resolves QA blocker:
           - "Quote can be changed to Sent/Accepted without Quote item is created"
             • Enquiry 2569 / Quote 2340
             • Enquiry 2574 (pending confirmation)
        ---------------------------------------------------------------------- */
        IF (@RecordTypeGuid = @IsQuote AND @StatusName IN (N'Sent', N'Customer Accepted'))
        BEGIN
            DECLARE @QuoteItemCount INT = 0;

            SELECT @QuoteItemCount = COUNT(1)
            FROM SSop.QuoteItems qi
            JOIN SSop.Quotes q ON q.ID = qi.QuoteId
            WHERE q.Guid = @DataObjectGuid
              AND q.RowStatus NOT IN (0,254)
              AND qi.RowStatus NOT IN (0,254);

            IF (ISNULL(@QuoteItemCount, 0) <= 0)
                THROW 60022, N'Cannot set Quote status to "Sent" or "Customer Accepted" until at least one Quote Item has been created for the Quote.', 1;
        END

        -------------------------------------------------------------------------
        -- Existing HARD STOP: Quote "Ready to Send" requires Net > 0
        -------------------------------------------------------------------------
        DECLARE @ReadyToSendStatusGuid UNIQUEIDENTIFIER = '02A2237F-2AE7-4E05-926F-38E8B7D050A0';

        IF (@RecordTypeGuid = @IsQuote AND @StatusGuid = @ReadyToSendStatusGuid)
        BEGIN
            DECLARE @QuoteNetValue DECIMAL(18,2) = 0;

            SELECT @QuoteNetValue =
                ISNULL(
                    (
                        SELECT SUM(qit.LineNet)
                        FROM SSop.QuoteItemTotals AS qit
                        JOIN SSop.QuoteItems      AS qi ON qi.ID = qit.ID
                        JOIN SSop.Quotes          AS q  ON q.ID  = qi.QuoteId
                        WHERE q.Guid = @DataObjectGuid
                          AND qi.RowStatus NOT IN (0,254)
                    ),
                    0
                );

            IF (@QuoteNetValue <= 0)
                THROW 60021, N'Cannot set status to "Ready to Send" until the quote has at least one Quote Item with a net value greater than 0.', 1;
        END

        -------------------------------------------------------------------------
        -- Compute OldStatusID
        -------------------------------------------------------------------------
        DECLARE @OldStatusID INT = NULL;

        SELECT TOP (1) @OldStatusID = dot.StatusID
        FROM SCore.DataObjectTransition dot
        WHERE dot.DataObjectGuid = @DataObjectGuid
          AND dot.RowStatus NOT IN (0,254)
          AND dot.Guid <> @Guid
        ORDER BY dot.ID DESC;

        IF (@OldStatusID IS NULL AND @OldStatusGuid IS NOT NULL AND @OldStatusGuid <> '00000000-0000-0000-0000-000000000000')
        BEGIN
            SELECT TOP (1) @OldStatusID = ws.ID
            FROM SCore.WorkflowStatus ws
            WHERE ws.Guid = @OldStatusGuid
              AND ws.RowStatus NOT IN (0,254);
        END

        IF (@OldStatusID IS NULL)
        BEGIN
            SELECT TOP (1) @OldStatusID = ws.ID
            FROM SCore.WorkflowStatus ws
            WHERE ws.Guid = '00000000-0000-0000-0000-000000000000'
              AND ws.RowStatus NOT IN (0,254);
        END

        -------------------------------------------------------------------------
        -- JOB CREATION DEFAULT STATUS SAFETY
        -- Do not override an explicitly requested job status.
        -- Only default to "New" when no valid job status was supplied.
        -------------------------------------------------------------------------
        IF (@RecordTypeGuid = @IsJob)
        BEGIN
            IF NOT EXISTS
            (
                SELECT 1
                FROM SCore.DataObjectTransition AS dot
                WHERE dot.DataObjectGuid = @DataObjectGuid
                  AND dot.RowStatus NOT IN (0, 254)
            )
            AND
            (
                @StatusID IS NULL
                OR ISNULL(@StatusName, N'') = N''
            )
            BEGIN
                DECLARE @JobNewStatusID INT = NULL;
                DECLARE @JobNewStatusName NVARCHAR(255) = NULL;

                SELECT TOP (1)
                    @JobNewStatusID = ws.ID,
                    @JobNewStatusName = ws.Name
                FROM SCore.WorkflowStatus AS ws
                WHERE ws.RowStatus NOT IN (0, 254)
                  AND ws.ShowInJobs = 1
                  AND ws.Name = N'New'
                ORDER BY ws.ID;

                IF (@JobNewStatusID IS NULL)
                    THROW 60014, N'Cannot create first Job transition: default Job status "New" was not found.', 1;

                SET @StatusID = @JobNewStatusID;
                SET @StatusName = @JobNewStatusName;
                SET @ShowInJobs = 1;
            END
        END
        -------------------------------------------------------------------------
        -- Ensure DataObjects row exists for Transition GUID
        -------------------------------------------------------------------------
        IF NOT EXISTS (SELECT 1 FROM SCore.DataObjects WHERE Guid = @Guid)
        BEGIN
            DECLARE @TransitionEntityTypeId INT = NULL;

            SELECT TOP (1) @TransitionEntityTypeId = eh.EntityTypeID
            FROM SCore.EntityHobts eh
            WHERE eh.SchemaName = N'SCore'
              AND eh.ObjectName = N'DataObjectTransition';

            IF (@TransitionEntityTypeId IS NULL)
                THROW 60003, N'DataObjectTransitionUpsert: could not resolve EntityTypeID for SCore.DataObjectTransition from EntityHobts.', 1;

            INSERT SCore.DataObjects (Guid, RowStatus, EntityTypeId)
            VALUES (@Guid, 1, @TransitionEntityTypeId);
        END

        -------------------------------------------------------------------------
        -- Upsert SCore.DataObjectTransition
        -------------------------------------------------------------------------
        IF NOT EXISTS (SELECT 1 FROM SCore.DataObjectTransition WHERE Guid = @Guid)
        BEGIN
            INSERT INTO SCore.DataObjectTransition
            (
                Guid,
                RowStatus,
                OldStatusID,
                StatusID,
                Comment,
                DateTimeUTC,
                CreatedByUserId,
                SurveyorUserId,
                DataObjectGuid,
                IsImported
            )
            VALUES
            (
                @Guid,
                1,
                @OldStatusID,
                @StatusID,
                @Comment,
                @DateTimeUTC,
                @CreatedByUserID,
                @SurveyorUserID,
                @DataObjectGuid,
                @IsImported
            );
        END
        ELSE
        BEGIN
            UPDATE SCore.DataObjectTransition
            SET
                OldStatusID      = @OldStatusID,
                StatusID         = @StatusID,
                Comment          = @Comment,
                DateTimeUTC      = @DateTimeUTC,
                CreatedByUserId  = @CreatedByUserID,
                SurveyorUserId   = @SurveyorUserID,
                DataObjectGuid   = @DataObjectGuid,
                IsImported       = @IsImported
            WHERE Guid = @Guid;

            IF (@@ROWCOUNT = 0)
            BEGIN
                INSERT INTO SCore.DataObjectTransition
                (
                    Guid,
                    RowStatus,
                    OldStatusID,
                    StatusID,
                    Comment,
                    DateTimeUTC,
                    CreatedByUserId,
                    SurveyorUserId,
                    DataObjectGuid,
                    IsImported
                )
                VALUES
                (
                    @Guid,
                    1,
                    @OldStatusID,
                    @StatusID,
                    @Comment,
                    @DateTimeUTC,
                    @CreatedByUserID,
                    @SurveyorUserID,
                    @DataObjectGuid,
                    @IsImported
                );
            END
        END;
        -------------------------------------------------------------------------
        -- JOB ACTIVE COMPATIBILITY SYNC
        -- Workflow remains source of truth.
        -- This only keeps legacy SJob.Jobs active date/flag behaviour aligned
        -- for older queries that still use SJob.Jobs.IsActive.
        -------------------------------------------------------------------------
        IF (@RecordTypeGuid = @IsJob)
        BEGIN
            DECLARE @LatestJobIsActiveStatus BIT = NULL;

            SELECT TOP (1)
                @LatestJobIsActiveStatus = ws.IsActiveStatus
            FROM SCore.DataObjectTransition AS dot
            JOIN SCore.WorkflowStatus AS ws
                ON ws.ID = dot.StatusID
            WHERE dot.DataObjectGuid = @DataObjectGuid
              AND dot.RowStatus NOT IN (0, 254)
              AND ws.RowStatus NOT IN (0, 254)
              AND ws.ShowInJobs = 1
            ORDER BY dot.DateTimeUTC DESC, dot.ID DESC;

            IF (@LatestJobIsActiveStatus = 1)
            BEGIN
                UPDATE SJob.Jobs
                SET
                    JobDormant = NULL,
                    JobCompleted = NULL,
                    JobCancelled = NULL,
                    DeadDate = NULL
                WHERE Guid = @DataObjectGuid
                  AND RowStatus NOT IN (0, 254)
                  AND
                  (
                      JobDormant IS NOT NULL
                      OR JobCompleted IS NOT NULL
                      OR JobCancelled IS NOT NULL
                      OR DeadDate IS NOT NULL
                  );
            END
        END
        -------------------------------------------------------------------------
        -- (Job->Quote completion, Quote->Enquiry sync, etc.)
        -- (left unchanged)
        -------------------------------------------------------------------------

        IF (@RecordTypeGuid = @IsJob)
        BEGIN
            DECLARE @JobID INT = NULL;

            SELECT TOP (1) @JobID = j.ID
            FROM SJob.Jobs j
            WHERE j.Guid = @DataObjectGuid
              AND j.RowStatus NOT IN (0,254);

            IF (@JobID IS NOT NULL)
            BEGIN
                DECLARE @QuoteGuid UNIQUEIDENTIFIER = NULL;
                DECLARE @QuoteDataObjectGuid UNIQUEIDENTIFIER = NULL;

                SELECT TOP (1)
                    @QuoteGuid = q.Guid
                FROM SSop.QuoteItems qi
                JOIN SSop.Quotes q ON q.ID = qi.QuoteId
                WHERE qi.RowStatus NOT IN (0,254)
                  AND q.RowStatus  NOT IN (0,254)
                  AND qi.CreatedJobId = @JobID;

                SET @QuoteDataObjectGuid = @QuoteGuid;

                IF (@QuoteDataObjectGuid IS NOT NULL)
                BEGIN
                    DECLARE @QuoteIsComplete BIT = 0;

                    IF EXISTS
                    (
                        SELECT 1
                        FROM SSop.QuoteItems qi
                        JOIN SSop.Quotes q ON q.ID = qi.QuoteId
                        WHERE q.Guid = @QuoteDataObjectGuid
                          AND q.RowStatus NOT IN (0,254)
                          AND qi.RowStatus NOT IN (0,254)
                    )
                    AND NOT EXISTS
                    (
                        SELECT 1
                        FROM SSop.QuoteItems qi
                        JOIN SSop.Quotes q ON q.ID = qi.QuoteId
                        WHERE q.Guid = @QuoteDataObjectGuid
                          AND q.RowStatus NOT IN (0,254)
                          AND qi.RowStatus NOT IN (0,254)
                          AND ISNULL(qi.CreatedJobId, 0) <= 0
                    )
                    BEGIN
                        SET @QuoteIsComplete = 1;
                    END

                    IF (@QuoteIsComplete = 1)
                    BEGIN
                        DECLARE @QuoteCompleteStatusGuid UNIQUEIDENTIFIER = NULL;

                        SELECT TOP (1) @QuoteCompleteStatusGuid = ws.Guid
                        FROM SCore.WorkflowStatus ws
                        WHERE ws.RowStatus NOT IN (0,254)
                          AND ws.ShowInQuotes = 1
                          AND ws.Name = N'Complete'
                        ORDER BY ws.ID;

                        IF (@QuoteCompleteStatusGuid IS NOT NULL)
                        BEGIN
                            DECLARE @LatestQuoteStatusID INT = NULL;
                            DECLARE @CompleteQuoteStatusID INT = NULL;

                            SELECT TOP (1) @LatestQuoteStatusID = dot.StatusID
                            FROM SCore.DataObjectTransition dot
                            WHERE dot.DataObjectGuid = @QuoteDataObjectGuid
                              AND dot.RowStatus NOT IN (0,254)
                            ORDER BY dot.ID DESC;

                            SELECT TOP (1) @CompleteQuoteStatusID = ws.ID
                            FROM SCore.WorkflowStatus ws
                            WHERE ws.Guid = @QuoteCompleteStatusGuid
                              AND ws.RowStatus NOT IN (0,254);

                            IF (@CompleteQuoteStatusID IS NOT NULL
                                AND ISNULL(@LatestQuoteStatusID, -1) <> @CompleteQuoteStatusID)
                            BEGIN
                                DECLARE @QuoteCompleteTransitionGuid UNIQUEIDENTIFIER = NEWID();

                                EXEC SCore.DataObjectTransitionUpsert
                                    @Guid             = @QuoteCompleteTransitionGuid,
                                    @OldStatusGuid     = '00000000-0000-0000-0000-000000000000',
                                    @StatusGuid        = @QuoteCompleteStatusGuid,
                                    @Comment           = N'System Imported (Job created).',
                                    @CreatedByUserGuid = @CreatedByUserGuid,
                                    @SurveyorUserGuid  = @SurveyorUserGuid,
                                    @DataObjectGuid    = @QuoteDataObjectGuid,
                                    @IsImported        = 1;
                            END
                        END
                    END
                END
            END
        END

        -------------------------------------------------------------------------
        -- Synchronisation: QUOTE -> ENQUIRY (+ EnquiryService)
        -- (left unchanged)
        -------------------------------------------------------------------------
        SELECT @IsQuote = Guid FROM SCore.EntityTypes WHERE Name = N'Quotes';

        IF (@RecordTypeGuid = @IsQuote)
        BEGIN
            DECLARE @EnquiryGuid UNIQUEIDENTIFIER = NULL;
            DECLARE @EnquiryServiceGuid UNIQUEIDENTIFIER = NULL;

            SELECT TOP (1)
                @EnquiryServiceGuid = es.Guid,
                @EnquiryGuid        = e.Guid
            FROM SSop.Quotes q
            JOIN SSop.EnquiryServices es ON es.ID = q.EnquiryServiceID
            JOIN SSop.Enquiries e        ON e.ID  = es.EnquiryId
            WHERE q.Guid = @DataObjectGuid
              AND q.RowStatus NOT IN (0,254)
              AND es.RowStatus NOT IN (0,254)
              AND e.RowStatus NOT IN (0,254);

            DECLARE @TargetEnquiryStatusName NVARCHAR(255) = @StatusName;

            IF (@StatusName = N'Quote Deadline Approaching') SET @TargetEnquiryStatusName = N'Deadline Approaching';
            IF (@StatusName = N'Quote Deadline Missing')     SET @TargetEnquiryStatusName = N'Deadline Missed';
            IF (@StatusName = N'Quote Expired')              SET @TargetEnquiryStatusName = N'Expired';
            IF (@StatusName = N'Is Final (Ready to Send)')   SET @TargetEnquiryStatusName = N'Ready to Send';

            -- CYB-461: an Enquiry only expires once every active Quote on it
            -- has expired, so an expired Quote does not sync to its Enquiry
            -- while any sibling Quote's latest status is something else.
            DECLARE @SkipEnquirySync BIT = 0;

            IF (@StatusName = N'Expired' AND @EnquiryGuid IS NOT NULL)
               AND EXISTS
               (
                   SELECT 1
                   FROM SSop.Enquiries e
                   JOIN SSop.EnquiryServices es ON es.EnquiryId = e.ID
                   JOIN SSop.Quotes q           ON q.EnquiryServiceID = es.ID
                   OUTER APPLY
                   (
                       SELECT TOP (1) wfs.Name
                       FROM SCore.DataObjectTransition dot
                       JOIN SCore.WorkflowStatus wfs ON wfs.ID = dot.StatusID
                       WHERE dot.DataObjectGuid = q.Guid
                         AND dot.RowStatus NOT IN (0,254)
                         AND wfs.RowStatus NOT IN (0,254)
                       ORDER BY dot.ID DESC
                   ) AS LatestQuoteStatus
                   WHERE e.Guid = @EnquiryGuid
                     AND es.RowStatus NOT IN (0,254)
                     AND q.RowStatus NOT IN (0,254)
                     AND ISNULL(LatestQuoteStatus.Name, N'') <> N'Expired'
               )
                SET @SkipEnquirySync = 1;

            DECLARE @TargetGuid UNIQUEIDENTIFIER;
            DECLARE @TargetOldStatusID INT;
            DECLARE @TargetNewStatusID INT;

            -- 1) Sync to ENQUIRY (unchanged apart from the CYB-461 expiry guard)
            IF (@EnquiryGuid IS NOT NULL AND @SkipEnquirySync = 0)
            BEGIN
                SET @TargetGuid = @EnquiryGuid;

                SELECT TOP (1) @TargetNewStatusID = ws.ID
                FROM SCore.WorkflowStatus ws
                WHERE ws.RowStatus NOT IN (0,254)
                  AND ws.ShowInEnquiries = 1
                  AND ws.Name = @TargetEnquiryStatusName
                ORDER BY ws.ID;

                IF (@TargetNewStatusID = -1)
                    SET @TargetNewStatusID = NULL;

                IF (@TargetNewStatusID IS NOT NULL)
                BEGIN
                    SELECT TOP (1) @TargetOldStatusID = dot.StatusID
                    FROM SCore.DataObjectTransition dot
                    JOIN SCore.WorkflowStatus wfs ON wfs.ID = dot.StatusID
                    WHERE dot.DataObjectGuid = @TargetGuid
                      AND dot.RowStatus NOT IN (0,254)
                      AND wfs.RowStatus NOT IN (0,254)
                      AND wfs.ShowInEnquiries = 1
                    ORDER BY dot.DateTimeUTC DESC, dot.ID DESC;

                    IF (ISNULL(@TargetOldStatusID, -999999) <> @TargetNewStatusID)
                    BEGIN
                        DECLARE @SyncEnquiryTransitionGuid UNIQUEIDENTIFIER = NEWID();
                        DECLARE @Tmp BIT = 0;

                        EXEC SCore.UpsertDataObject
                            @Guid       = @SyncEnquiryTransitionGuid,
                            @SchemeName = N'SCore',
                            @ObjectName = N'DataObjectTransition',
                            @IsInsert   = @Tmp OUTPUT;

                        INSERT INTO SCore.DataObjectTransition
                        (
                            Guid, RowStatus, OldStatusID, StatusID, Comment, DateTimeUTC,
                            CreatedByUserId, SurveyorUserId, DataObjectGuid, IsImported
                        )
                        VALUES
                        (
                            @SyncEnquiryTransitionGuid,
                            1,
                            @TargetOldStatusID,
                            @TargetNewStatusID,
                            N'System Imported (Quote sync).',
                            @DateTimeUTC,
                            @CreatedByUserID,
                            @SurveyorUserID,
                            @TargetGuid,
                            1
                        );
                    END
                END
            END

            -- 2) Sync to ENQUIRY SERVICE (unchanged)
            IF (@EnquiryServiceGuid IS NOT NULL)
            BEGIN
                SET @TargetGuid = @EnquiryServiceGuid;

                SELECT TOP (1) @TargetNewStatusID = ws.ID
                FROM SCore.WorkflowStatus ws
                WHERE ws.RowStatus NOT IN (0,254)
                  AND ws.ShowInEnquiries = 1
                  AND ws.Name = @TargetEnquiryStatusName
                ORDER BY ws.ID;

                IF (@TargetNewStatusID = -1)
                    SET @TargetNewStatusID = NULL;

                IF (@TargetNewStatusID IS NOT NULL)
                BEGIN
                    SELECT TOP (1) @TargetOldStatusID = dot.StatusID
                    FROM SCore.DataObjectTransition dot
                    JOIN SCore.WorkflowStatus wfs ON wfs.ID = dot.StatusID
                    WHERE dot.DataObjectGuid = @TargetGuid
                      AND dot.RowStatus NOT IN (0,254)
                      AND wfs.RowStatus NOT IN (0,254)
                      AND wfs.ShowInEnquiries = 1
                    ORDER BY dot.DateTimeUTC DESC, dot.ID DESC;

                    IF (ISNULL(@TargetOldStatusID, -999999) <> @TargetNewStatusID)
                    BEGIN
                        DECLARE @SyncEnquiryServiceTransitionGuid UNIQUEIDENTIFIER = NEWID();
                        DECLARE @Tmp2 BIT = 0;

                        EXEC SCore.UpsertDataObject
                            @Guid       = @SyncEnquiryServiceTransitionGuid,
                            @SchemeName = N'SCore',
                            @ObjectName = N'DataObjectTransition',
                            @IsInsert   = @Tmp2 OUTPUT;

                        INSERT INTO SCore.DataObjectTransition
                        (
                            Guid, RowStatus, OldStatusID, StatusID, Comment, DateTimeUTC,
                            CreatedByUserId, SurveyorUserId, DataObjectGuid, IsImported
                        )
                        VALUES
                        (
                            @SyncEnquiryServiceTransitionGuid,
                            1,
                            @TargetOldStatusID,
                            @TargetNewStatusID,
                            N'System Imported (Quote sync).',
                            @DateTimeUTC,
                            @CreatedByUserID,
                            @SurveyorUserID,
                            @TargetGuid,
                            1
                        );
                    END
                END
            END
        END;

        COMMIT;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK;

        DECLARE @ErrMsg NVARCHAR(MAX);
        DECLARE @Final NVARCHAR(MAX);

        SELECT @ErrMsg = ERROR_MESSAGE();

        SET @Final =
            N'[' + @ProcName + N'] TraceId=' + CONVERT(NVARCHAR(36), @TraceId)
            + N' FAILED | TransitionGuid=' + CONVERT(NVARCHAR(36), @Guid)
            + N' | RecordGuid=' + CONVERT(NVARCHAR(36), @DataObjectGuid)
            + N' | ' + @ErrMsg;

        THROW 61099, @Final, 1;
    END CATCH
END
GO

