/*
    Required dependency for SFin.InvoiceRequestsDelete.

    This preserves the established entity-delete behaviour while making the
    database-project object idempotent. The DataObject is deleted through the
    platform helper before the entity row is marked inactive.
*/
CREATE OR ALTER PROCEDURE [SFin].[InvoiceRequestItemsDelete]
    @Guid UNIQUEIDENTIFIER
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @Guid IS NULL
        THROW 60000, N'Invoice request item Guid is required.', 1;

    BEGIN TRY
        BEGIN TRANSACTION;

        EXEC SCore.DeleteDataObject
            @Guid = @Guid;

        UPDATE iri
        SET iri.RowStatus = 254
        FROM SFin.InvoiceRequestItems AS iri
        WHERE iri.Guid = @Guid
          AND iri.RowStatus NOT IN (0, 254);

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;

        ;THROW;
    END CATCH;
END;
