/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : StoredProcedure SFin.InvoiceAutomation_HistoricFailureRecovery
    Source schema hash : E9A55855F462F37F44CB22382027A8F2D5E9DBE895E4D87F033F4F7F374ADC8D
    Definition SHA-256 : DD5ABA217E1B7B5DED12BD00E6E6751295382D5D961C683FC57FB3EB6AB2D748

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*
    Historic recovery for invoice automation runs that failed with
    FK_InvoiceBatches_DataObjects.

    Safety model
    ------------
    1. @Apply defaults to 0 and returns a plan only.
    2. An apply requires an explicit date, job-number, or run-guid scope.
    3. Requests linked to TransactionDetails are never changed.
    4. A request is automatically suppressed only where mode history proves
       the job was Manual or Paused when the request was created.
    5. A request is batched only when it was eligible at creation and the job is
       still Automated and unblocked at apply time.
    6. Existing failed run details are retained. Recovery adds new audit detail
       rows and leaves the original ErrorCount unchanged.
    7. Deleted parents with active child items are repaired through the normal
       soft-delete procedures; no financial transaction rows are changed.
*/
CREATE OR ALTER PROCEDURE [SFin].[InvoiceAutomation_HistoricFailureRecovery]
(
      @Apply BIT = 0
    , @FromUtc DATETIME2(7) = NULL
    , @ToUtc DATETIME2(7) = NULL
    , @JobNumber NVARCHAR(50) = NULL
    , @AutomationRunGuid UNIQUEIDENTIFIER = NULL
    , @RecoverEligible BIT = 1
    , @SuppressProvenManualOrPaused BIT = 0
    , @RepairDeletedParentItems BIT = 1
    , @ExpectedPlanRows INT = NULL
    , @MaxRows INT = 500
    , @AppLockName NVARCHAR(255) = N'SFin.InvoiceAutomation.ScheduledWorker'
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF @ToUtc IS NOT NULL
       AND @FromUtc IS NOT NULL
       AND @ToUtc <= @FromUtc
        THROW 51000, N'@ToUtc must be later than @FromUtc.', 1;

    IF ISNULL(@MaxRows, 0) < 1
        THROW 51000, N'@MaxRows must be at least 1.', 1;

    IF NULLIF(LTRIM(RTRIM(@AppLockName)), N'') IS NULL
        THROW 51000, N'@AppLockName is required.', 1;

    IF @Apply = 1
       AND @FromUtc IS NULL
       AND @ToUtc IS NULL
       AND NULLIF(LTRIM(RTRIM(@JobNumber)), N'') IS NULL
       AND @AutomationRunGuid IS NULL
        THROW 51000, N'Apply mode requires an explicit date, job-number, or run-guid scope.', 1;

    IF @Apply = 1
       AND @ExpectedPlanRows IS NULL
        THROW 51000, N'Apply mode requires @ExpectedPlanRows from the approved dry run.', 1;

    DECLARE @LockResult INT = NULL;
    DECLARE @LockAcquired BIT = 0;
    DECLARE @NowUtc DATETIME2(7) = SYSUTCDATETIME();

    BEGIN TRY
        IF @Apply = 1
        BEGIN
            EXEC @LockResult = sys.sp_getapplock
                  @Resource = @AppLockName
                , @LockMode = N'Exclusive'
                , @LockOwner = N'Session'
                , @LockTimeout = 10000;

            IF @LockResult NOT IN (0, 1)
                THROW 51000, N'Could not acquire the invoice automation application lock. Retry after the active run finishes.', 1;

            SET @LockAcquired = 1;
        END;

        CREATE TABLE #FailedRuns
        (
            AutomationRunGuid UNIQUEIDENTIFIER NOT NULL PRIMARY KEY
        );

        INSERT INTO #FailedRuns
        (
            AutomationRunGuid
        )
        SELECT DISTINCT d.AutomationRunGuid
        FROM SFin.InvoiceAutomationRunDetails AS d
        WHERE d.RowStatus NOT IN (0, 254)
          AND d.AutomationRunGuid IS NOT NULL
          AND d.InstanceType = N'RUN'
          AND d.InstanceKey = N'ERROR'
          AND d.Outcome = N'Failed'
          AND d.Message LIKE N'%FK_InvoiceBatches_DataObjects%'
          AND (@AutomationRunGuid IS NULL OR d.AutomationRunGuid = @AutomationRunGuid);

        CREATE TABLE #RequestPlan
        (
              RequestId INT NOT NULL PRIMARY KEY
            , RequestGuid UNIQUEIDENTIFIER NOT NULL
            , AutomationRunGuid UNIQUEIDENTIFIER NOT NULL
            , JobId INT NOT NULL
            , JobNumber NVARCHAR(50) NULL
            , CreatedDateTimeUTC DATETIME2(7) NOT NULL
            , ExpectedDate DATE NULL
            , SourceType NVARCHAR(50) NOT NULL
            , SourceGuid UNIQUEIDENTIFIER NULL
            , SourceIntId INT NULL
            , Net DECIMAL(19, 2) NOT NULL
            , CurrentMode TINYINT NULL
            , ModeAtCreation TINYINT NULL
            , ModeEvidence NVARCHAR(40) NOT NULL
            , CurrentAccountIsOnHold BIT NOT NULL
            , CurrentCannotBeInvoiced BIT NOT NULL
            , HasTransactionDetails BIT NOT NULL
            , RecoveryAction NVARCHAR(40) NOT NULL
            , RecoveryReason NVARCHAR(500) NOT NULL
            , Processed BIT NOT NULL DEFAULT (0)
        );

        INSERT INTO #RequestPlan
        (
              RequestId
            , RequestGuid
            , AutomationRunGuid
            , JobId
            , JobNumber
            , CreatedDateTimeUTC
            , ExpectedDate
            , SourceType
            , SourceGuid
            , SourceIntId
            , Net
            , CurrentMode
            , ModeAtCreation
            , ModeEvidence
            , CurrentAccountIsOnHold
            , CurrentCannotBeInvoiced
            , HasTransactionDetails
            , RecoveryAction
            , RecoveryReason
        )
        SELECT
              ir.ID
            , ir.Guid
            , ir.AutomationRunGuid
            , ir.JobId
            , j.Number
            , ir.CreatedDateTimeUTC
            , ir.ExpectedDate
            , ir.SourceType
            , ir.SourceGuid
            , ir.SourceIntId
            , CONVERT(DECIMAL(19, 2), ISNULL(item_totals.Net, 0))
            , j.InvoiceProcessingMode
            , mode_at_creation.ModeAtCreation
            , mode_at_creation.ModeEvidence
            , CONVERT(BIT, ISNULL(acs.IsHold, 0))
            , CONVERT(BIT, ISNULL(j.CannotBeInvoiced, 0))
            , CONVERT(BIT, ISNULL(transaction_link.HasTransactionDetails, 0))
            , CASE
                  WHEN ISNULL(transaction_link.HasTransactionDetails, 0) = 1
                      THEN N'REVIEW'
                  WHEN j.ID IS NULL OR j.RowStatus IN (0, 254)
                      THEN N'REVIEW'
                  WHEN mode_at_creation.ModeAtCreation IN (1, 2)
                       AND mode_at_creation.ModeEvidence <> N'CURRENT_FALLBACK'
                      THEN N'SUPPRESS'
                  WHEN ISNULL(j.InvoiceProcessingMode, 1) <> 0
                      THEN N'REVIEW'
                  WHEN ISNULL(j.CannotBeInvoiced, 0) = 1
                      THEN N'REVIEW'
                  WHEN ISNULL(acs.IsHold, 0) = 1
                      THEN N'REVIEW'
                  ELSE N'BATCH'
              END
            , CASE
                  WHEN ISNULL(transaction_link.HasTransactionDetails, 0) = 1
                      THEN N'Request is linked to TransactionDetails; no automatic change is permitted.'
                  WHEN j.ID IS NULL OR j.RowStatus IN (0, 254)
                      THEN N'Job is missing or inactive; manual review is required.'
                  WHEN mode_at_creation.ModeAtCreation = 1
                       AND mode_at_creation.ModeEvidence <> N'CURRENT_FALLBACK'
                      THEN N'Mode history proves the job was Manual when this request was created.'
                  WHEN mode_at_creation.ModeAtCreation = 2
                       AND mode_at_creation.ModeEvidence <> N'CURRENT_FALLBACK'
                      THEN N'Mode history proves the job was Paused when this request was created.'
                  WHEN ISNULL(j.InvoiceProcessingMode, 1) <> 0
                      THEN N'Request may have been valid at creation, but the job is not currently Automated.'
                  WHEN ISNULL(j.CannotBeInvoiced, 0) = 1
                      THEN N'Job is currently marked CannotBeInvoiced; manual review is required.'
                  WHEN ISNULL(acs.IsHold, 0) = 1
                      THEN N'Finance account is currently on hold; manual review is required.'
                  ELSE N'Eligible automated request from a failed batch run; recover it into a valid batch.'
              END
        FROM SFin.InvoiceRequests AS ir
        INNER JOIN #FailedRuns AS failed_run
            ON failed_run.AutomationRunGuid = ir.AutomationRunGuid
        LEFT JOIN SJob.Jobs AS j
            ON j.ID = ir.JobId
        LEFT JOIN SCrm.Accounts AS a
            ON a.ID = j.FinanceAccountID
           AND a.RowStatus NOT IN (0, 254)
        LEFT JOIN SCrm.AccountStatus AS acs
            ON acs.ID = a.AccountStatusID
           AND acs.RowStatus NOT IN (0, 254)
        OUTER APPLY
        (
            SELECT TOP (1)
                h.NewMode
            FROM SFin.InvoiceProcessingModeHistory AS h
            WHERE h.JobId = ir.JobId
              AND h.RowStatus NOT IN (0, 254)
              AND h.ChangedDateTimeUTC <= ir.CreatedDateTimeUTC
            ORDER BY h.ChangedDateTimeUTC DESC, h.ID DESC
        ) AS mode_before
        OUTER APPLY
        (
            SELECT TOP (1)
                h.OldMode
            FROM SFin.InvoiceProcessingModeHistory AS h
            WHERE h.JobId = ir.JobId
              AND h.RowStatus NOT IN (0, 254)
              AND h.ChangedDateTimeUTC > ir.CreatedDateTimeUTC
            ORDER BY h.ChangedDateTimeUTC ASC, h.ID ASC
        ) AS mode_after
        OUTER APPLY
        (
            SELECT
                  CONVERT(TINYINT, COALESCE(mode_before.NewMode, mode_after.OldMode, j.InvoiceProcessingMode)) AS ModeAtCreation
                , CONVERT
                  (
                      NVARCHAR(40),
                      CASE
                          WHEN mode_before.NewMode IS NOT NULL THEN N'HISTORY_AT_CREATION'
                          WHEN mode_after.OldMode IS NOT NULL THEN N'FIRST_HISTORY_OLD_MODE'
                          ELSE N'CURRENT_FALLBACK'
                      END
                  ) AS ModeEvidence
        ) AS mode_at_creation
        OUTER APPLY
        (
            SELECT TOP (1)
                CONVERT(BIT, 1) AS HasTransactionDetails
            FROM SFin.InvoiceRequestItems AS iri
            INNER JOIN SFin.TransactionDetails AS td
                ON td.InvoiceRequestItemId = iri.ID
            WHERE iri.InvoiceRequestId = ir.ID
        ) AS transaction_link
        OUTER APPLY
        (
            SELECT SUM(iri.Net) AS Net
            FROM SFin.InvoiceRequestItems AS iri
            WHERE iri.InvoiceRequestId = ir.ID
              AND iri.RowStatus NOT IN (0, 254)
        ) AS item_totals
        WHERE ir.RowStatus NOT IN (0, 254)
          AND ISNULL(ir.IsAutomated, 0) = 1
          AND ir.InvoiceBatchGuid IS NULL
          AND (@FromUtc IS NULL OR ir.CreatedDateTimeUTC >= @FromUtc)
          AND (@ToUtc IS NULL OR ir.CreatedDateTimeUTC < @ToUtc)
          AND (NULLIF(LTRIM(RTRIM(@JobNumber)), N'') IS NULL OR j.Number = @JobNumber);

        CREATE TABLE #OrphanItemPlan
        (
              ItemId BIGINT NOT NULL PRIMARY KEY
            , ItemGuid UNIQUEIDENTIFIER NOT NULL
            , RequestId INT NOT NULL
            , RequestGuid UNIQUEIDENTIFIER NOT NULL
            , AutomationRunGuid UNIQUEIDENTIFIER NOT NULL
            , JobId INT NOT NULL
            , JobNumber NVARCHAR(50) NULL
            , RequestCreatedDateTimeUTC DATETIME2(7) NOT NULL
            , Net DECIMAL(19, 2) NOT NULL
            , HasTransactionDetails BIT NOT NULL
            , RecoveryAction NVARCHAR(40) NOT NULL
            , RecoveryReason NVARCHAR(500) NOT NULL
            , Processed BIT NOT NULL DEFAULT (0)
        );

        INSERT INTO #OrphanItemPlan
        (
              ItemId
            , ItemGuid
            , RequestId
            , RequestGuid
            , AutomationRunGuid
            , JobId
            , JobNumber
            , RequestCreatedDateTimeUTC
            , Net
            , HasTransactionDetails
            , RecoveryAction
            , RecoveryReason
        )
        SELECT
              iri.ID
            , iri.Guid
            , ir.ID
            , ir.Guid
            , ir.AutomationRunGuid
            , ir.JobId
            , j.Number
            , ir.CreatedDateTimeUTC
            , iri.Net
            , CONVERT(BIT, ISNULL(parent_transaction_link.HasTransactionDetails, 0))
            , CASE
                  WHEN ISNULL(parent_transaction_link.HasTransactionDetails, 0) = 1
                      THEN N'REVIEW'
                  ELSE N'CLEAN_ORPHAN_ITEMS'
              END
            , CASE
                  WHEN ISNULL(parent_transaction_link.HasTransactionDetails, 0) = 1
                      THEN N'Deleted parent has a transaction-linked child; no automatic change is permitted.'
                  ELSE N'Parent request is already deleted but this child item is still active.'
              END
        FROM SFin.InvoiceRequestItems AS iri
        INNER JOIN SFin.InvoiceRequests AS ir
            ON ir.ID = iri.InvoiceRequestId
        INNER JOIN #FailedRuns AS failed_run
            ON failed_run.AutomationRunGuid = ir.AutomationRunGuid
        LEFT JOIN SJob.Jobs AS j
            ON j.ID = ir.JobId
        OUTER APPLY
        (
            SELECT TOP (1)
                CONVERT(BIT, 1) AS HasTransactionDetails
            FROM SFin.InvoiceRequestItems AS sibling
            INNER JOIN SFin.TransactionDetails AS td
                ON td.InvoiceRequestItemId = sibling.ID
            WHERE sibling.InvoiceRequestId = ir.ID
        ) AS parent_transaction_link
        WHERE ir.RowStatus IN (0, 254)
          AND iri.RowStatus NOT IN (0, 254)
          AND (@FromUtc IS NULL OR ir.CreatedDateTimeUTC >= @FromUtc)
          AND (@ToUtc IS NULL OR ir.CreatedDateTimeUTC < @ToUtc)
          AND (NULLIF(LTRIM(RTRIM(@JobNumber)), N'') IS NULL OR j.Number = @JobNumber);

        DECLARE @PlanRowCount INT =
        (
            SELECT COUNT(1)
            FROM #RequestPlan
        ) +
        (
            SELECT COUNT(1)
            FROM #OrphanItemPlan
        );

        /* Result set 1: action summary. */
        SELECT
              @PlanRowCount AS TotalPlanRows
            , [plan].RecoveryAction
            , [plan].RecoveryReason
            , COUNT(1) AS [RowCount]
            , SUM([plan].Net) AS Net
        FROM
        (
            SELECT
                  rp.RecoveryAction
                , rp.RecoveryReason
                , rp.Net
            FROM #RequestPlan AS rp

            UNION ALL

            SELECT
                  op.RecoveryAction
                , op.RecoveryReason
                , op.Net
            FROM #OrphanItemPlan AS op
        ) AS [plan]
        GROUP BY
              [plan].RecoveryAction
            , [plan].RecoveryReason
        ORDER BY
              [plan].RecoveryAction
            , [plan].RecoveryReason;

        /* Result set 2: active request decisions. */
        SELECT
              rp.RequestId
            , rp.RequestGuid
            , rp.AutomationRunGuid
            , rp.JobId AS InternalJobId
            , rp.JobNumber
            , rp.CreatedDateTimeUTC
            , rp.ExpectedDate
            , rp.SourceType
            , rp.SourceGuid
            , rp.SourceIntId
            , rp.Net
            , rp.CurrentMode
            , rp.ModeAtCreation
            , rp.ModeEvidence
            , rp.CurrentAccountIsOnHold
            , rp.CurrentCannotBeInvoiced
            , rp.HasTransactionDetails
            , rp.RecoveryAction
            , rp.RecoveryReason
        FROM #RequestPlan AS rp
        ORDER BY rp.CreatedDateTimeUTC, rp.RequestId;

        /* Result set 3: active items beneath already-deleted parents. */
        SELECT
              op.ItemId
            , op.ItemGuid
            , op.RequestId
            , op.RequestGuid
            , op.AutomationRunGuid
            , op.JobId AS InternalJobId
            , op.JobNumber
            , op.RequestCreatedDateTimeUTC
            , op.Net
            , op.HasTransactionDetails
            , op.RecoveryAction
            , op.RecoveryReason
        FROM #OrphanItemPlan AS op
        ORDER BY op.RequestCreatedDateTimeUTC, op.RequestId, op.ItemId;

        IF @Apply = 0
            RETURN;

        IF @PlanRowCount > @MaxRows
            THROW 51000, N'The recovery plan exceeds @MaxRows. Narrow the scope or raise the reviewed limit explicitly.', 1;

        IF @PlanRowCount <> @ExpectedPlanRows
            THROW 51000, N'The recovery plan row count changed after approval. Run the dry run again and re-review it.', 1;

        CREATE TABLE #Applied
        (
              ActionOrder BIGINT IDENTITY(1, 1) NOT NULL PRIMARY KEY
            , ActionType NVARCHAR(50) NOT NULL
            , RequestGuid UNIQUEIDENTIFIER NULL
            , AutomationRunGuid UNIQUEIDENTIFIER NULL
            , InvoiceBatchGuid UNIQUEIDENTIFIER NULL
            , AppliedDateTimeUTC DATETIME2(7) NOT NULL
            , Message NVARCHAR(1000) NOT NULL
            , AuditLogged BIT NOT NULL DEFAULT (0)
        );

        /* --------------------------------------------------------------
           A. Recover still-valid requests into a correctly registered batch.
           -------------------------------------------------------------- */
        DECLARE @RunGuid UNIQUEIDENTIFIER;

        DECLARE cur_recovery_run CURSOR LOCAL FAST_FORWARD FOR
        SELECT DISTINCT rp.AutomationRunGuid
        FROM #RequestPlan AS rp
        WHERE rp.RecoveryAction = N'BATCH'
          AND @RecoverEligible = 1
        ORDER BY rp.AutomationRunGuid;

        OPEN cur_recovery_run;
        FETCH NEXT FROM cur_recovery_run INTO @RunGuid;

        WHILE @@FETCH_STATUS = 0
        BEGIN
            BEGIN TRANSACTION;

            IF EXISTS
            (
                SELECT 1
                FROM #RequestPlan AS rp
                INNER JOIN SFin.InvoiceRequests AS ir
                    ON ir.ID = rp.RequestId
                INNER JOIN SJob.Jobs AS j
                    ON j.ID = ir.JobId
                   AND j.RowStatus NOT IN (0, 254)
                LEFT JOIN SCrm.Accounts AS a
                    ON a.ID = j.FinanceAccountID
                   AND a.RowStatus NOT IN (0, 254)
                LEFT JOIN SCrm.AccountStatus AS acs
                    ON acs.ID = a.AccountStatusID
                   AND acs.RowStatus NOT IN (0, 254)
                WHERE rp.AutomationRunGuid = @RunGuid
                  AND rp.RecoveryAction = N'BATCH'
                  AND ir.RowStatus NOT IN (0, 254)
                  AND ir.InvoiceBatchGuid IS NULL
                  AND ISNULL(ir.IsAutomated, 0) = 1
                  AND j.InvoiceProcessingMode = 0
                  AND ISNULL(j.CannotBeInvoiced, 0) = 0
                  AND ISNULL(acs.IsHold, 0) = 0
                  AND NOT EXISTS
                  (
                      SELECT 1
                      FROM SFin.InvoiceRequestItems AS iri
                      INNER JOIN SFin.TransactionDetails AS td
                          ON td.InvoiceRequestItemId = iri.ID
                      WHERE iri.InvoiceRequestId = ir.ID
                  )
            )
            BEGIN
                DECLARE @BatchGuid UNIQUEIDENTIFIER = NULL;
                DECLARE @CreatedByUserId INT = -1;
                DECLARE @BatchDataObjectWasInserted BIT = 0;

                SELECT @CreatedByUserId = ar.TriggeredByUserId
                FROM SFin.InvoiceAutomationRuns AS ar
                WHERE ar.Guid = @RunGuid;

                SELECT TOP (1)
                    @BatchGuid = b.Guid
                FROM SFin.InvoiceBatches AS b WITH (UPDLOCK, HOLDLOCK)
                WHERE b.AutomationRunGuid = @RunGuid
                  AND b.RowStatus NOT IN (0, 254)
                ORDER BY b.ID DESC;

                IF @BatchGuid IS NULL
                    SET @BatchGuid = NEWID();

                EXEC SCore.UpsertDataObject
                      @Guid = @BatchGuid
                    , @SchemeName = N'SFin'
                    , @ObjectName = N'InvoiceBatches'
                    , @IncludeDefaultSecurity = 0
                    , @IsInsert = @BatchDataObjectWasInserted OUTPUT;

                IF NOT EXISTS
                (
                    SELECT 1
                    FROM SFin.InvoiceBatches AS b
                    WHERE b.Guid = @BatchGuid
                )
                BEGIN
                    INSERT INTO SFin.InvoiceBatches
                    (
                          RowStatus
                        , Guid
                        , CreatedDateTimeUTC
                        , CreatedByUserId
                        , AutomationRunGuid
                        , CreatedCount
                        , Notes
                        , LegacyId
                        , LegacySystemID
                    )
                    VALUES
                    (
                          1
                        , @BatchGuid
                        , @NowUtc
                        , ISNULL(@CreatedByUserId, -1)
                        , @RunGuid
                        , 0
                        , N'Historic recovery of requests left unbatched by FK_InvoiceBatches_DataObjects.'
                        , NULL
                        , -1
                    );
                END;

                UPDATE ir
                SET ir.InvoiceBatchGuid = @BatchGuid
                FROM SFin.InvoiceRequests AS ir
                INNER JOIN #RequestPlan AS rp
                    ON rp.RequestId = ir.ID
                INNER JOIN SJob.Jobs AS j
                    ON j.ID = ir.JobId
                   AND j.RowStatus NOT IN (0, 254)
                LEFT JOIN SCrm.Accounts AS a
                    ON a.ID = j.FinanceAccountID
                   AND a.RowStatus NOT IN (0, 254)
                LEFT JOIN SCrm.AccountStatus AS acs
                    ON acs.ID = a.AccountStatusID
                   AND acs.RowStatus NOT IN (0, 254)
                WHERE rp.AutomationRunGuid = @RunGuid
                  AND rp.RecoveryAction = N'BATCH'
                  AND ir.RowStatus NOT IN (0, 254)
                  AND ir.InvoiceBatchGuid IS NULL
                  AND ISNULL(ir.IsAutomated, 0) = 1
                  AND j.InvoiceProcessingMode = 0
                  AND ISNULL(j.CannotBeInvoiced, 0) = 0
                  AND ISNULL(acs.IsHold, 0) = 0
                  AND NOT EXISTS
                  (
                      SELECT 1
                      FROM SFin.InvoiceRequestItems AS iri
                      INNER JOIN SFin.TransactionDetails AS td
                          ON td.InvoiceRequestItemId = iri.ID
                      WHERE iri.InvoiceRequestId = ir.ID
                  );

                DECLARE @AssignedCount INT = @@ROWCOUNT;

                UPDATE b
                SET b.CreatedCount =
                (
                    SELECT COUNT(1)
                    FROM SFin.InvoiceRequests AS ir
                    WHERE ir.RowStatus NOT IN (0, 254)
                      AND ir.InvoiceBatchGuid = @BatchGuid
                )
                FROM SFin.InvoiceBatches AS b
                WHERE b.Guid = @BatchGuid;

                IF @AssignedCount > 0
                BEGIN
                    UPDATE ar
                    SET ar.CreatedCount =
                        (
                            SELECT COUNT(1)
                            FROM SFin.InvoiceRequests AS ir
                            WHERE ir.RowStatus NOT IN (0, 254)
                              AND ir.AutomationRunGuid = @RunGuid
                              AND ISNULL(ir.IsAutomated, 0) = 1
                        )
                      , ar.InvoiceBatchGuid = @BatchGuid
                      , ar.WasBatchCreated = 1
                    FROM SFin.InvoiceAutomationRuns AS ar
                    WHERE ar.Guid = @RunGuid;

                    INSERT INTO #Applied
                    (
                          ActionType
                        , RequestGuid
                        , AutomationRunGuid
                        , InvoiceBatchGuid
                        , AppliedDateTimeUTC
                        , Message
                    )
                    SELECT
                          N'BATCHED'
                        , rp.RequestGuid
                        , rp.AutomationRunGuid
                        , @BatchGuid
                        , @NowUtc
                        , N'Request assigned to a valid historic-recovery batch; the original run error remains in the audit trail.'
                    FROM #RequestPlan AS rp
                    INNER JOIN SFin.InvoiceRequests AS ir
                        ON ir.ID = rp.RequestId
                    WHERE rp.AutomationRunGuid = @RunGuid
                      AND rp.RecoveryAction = N'BATCH'
                      AND ir.InvoiceBatchGuid = @BatchGuid
                      AND NOT EXISTS
                      (
                          SELECT 1
                          FROM #Applied AS already_applied
                          WHERE already_applied.ActionType = N'BATCHED'
                            AND already_applied.RequestGuid = rp.RequestGuid
                      );

                    DECLARE @AuditRequestGuid UNIQUEIDENTIFIER;
                    DECLARE @AuditSourceType NVARCHAR(50);
                    DECLARE @AuditSourceGuid UNIQUEIDENTIFIER;
                    DECLARE @AuditSourceIntId INT;

                    WHILE EXISTS
                    (
                        SELECT 1
                        FROM #Applied AS applied
                        WHERE applied.ActionType = N'BATCHED'
                          AND applied.AutomationRunGuid = @RunGuid
                          AND applied.AuditLogged = 0
                    )
                    BEGIN
                        SELECT TOP (1)
                              @AuditRequestGuid = applied.RequestGuid
                        FROM #Applied AS applied
                        WHERE applied.ActionType = N'BATCHED'
                          AND applied.AutomationRunGuid = @RunGuid
                          AND applied.AuditLogged = 0
                        ORDER BY applied.ActionOrder;

                        SELECT
                              @AuditSourceType = rp.SourceType
                            , @AuditSourceGuid = rp.SourceGuid
                            , @AuditSourceIntId = rp.SourceIntId
                        FROM #RequestPlan AS rp
                        WHERE rp.RequestGuid = @AuditRequestGuid;

                        IF NOT EXISTS
                        (
                            SELECT 1
                            FROM SFin.InvoiceAutomationRunDetails AS d
                            WHERE d.RowStatus NOT IN (0, 254)
                              AND d.AutomationRunGuid = @RunGuid
                              AND d.InstanceKey = CONCAT(N'HISTORIC_BATCH_RECOVERY|', CONVERT(NVARCHAR(36), @AuditRequestGuid))
                        )
                        BEGIN
                            DECLARE @DetailGuid UNIQUEIDENTIFIER = NEWID();
                            DECLARE @DetailDataObjectWasInserted BIT = 0;

                            EXEC SCore.UpsertDataObject
                                  @Guid = @DetailGuid
                                , @SchemeName = N'SFin'
                                , @ObjectName = N'InvoiceAutomationRunDetails'
                                , @IncludeDefaultSecurity = 0
                                , @IsInsert = @DetailDataObjectWasInserted OUTPUT;

                            INSERT INTO SFin.InvoiceAutomationRunDetails
                            (
                                  RowStatus
                                , Guid
                                , AutomationRunGuid
                                , InvoiceScheduleId
                                , SourceType
                                , SourceGuid
                                , SourceIntId
                                , InstanceType
                                , InstanceKey
                                , Outcome
                                , Message
                                , InvoiceRequestGuid
                                , CreatedDateTimeUTC
                                , LegacyId
                                , LegacySystemID
                            )
                            VALUES
                            (
                                  1
                                , @DetailGuid
                                , @RunGuid
                                , -1
                                , ISNULL(@AuditSourceType, N'')
                                , @AuditSourceGuid
                                , @AuditSourceIntId
                                , N'InvoiceRequest'
                                , CONCAT(N'HISTORIC_BATCH_RECOVERY|', CONVERT(NVARCHAR(36), @AuditRequestGuid))
                                , N'Recovered'
                                , CONCAT(N'Historic batch recovery assigned request to batch ', CONVERT(NVARCHAR(36), @BatchGuid), N'. Original failed-run detail retained.')
                                , @AuditRequestGuid
                                , @NowUtc
                                , NULL
                                , -1
                            );
                        END;

                        UPDATE applied
                        SET applied.AuditLogged = 1
                        FROM #Applied AS applied
                        WHERE applied.ActionType = N'BATCHED'
                          AND applied.RequestGuid = @AuditRequestGuid;
                    END;
                END;
            END;

            UPDATE rp
            SET rp.Processed = 1
            FROM #RequestPlan AS rp
            WHERE rp.AutomationRunGuid = @RunGuid
              AND rp.RecoveryAction = N'BATCH';

            COMMIT TRANSACTION;

            FETCH NEXT FROM cur_recovery_run INTO @RunGuid;
        END;

        CLOSE cur_recovery_run;
        DEALLOCATE cur_recovery_run;

        /* --------------------------------------------------------------
           B. Suppress requests proven to have been created while Manual or
              Paused. This uses the corrected soft-delete procedure.
           -------------------------------------------------------------- */
        IF @SuppressProvenManualOrPaused = 1
        BEGIN
            DECLARE @SuppressRequestId INT;
            DECLARE @SuppressRequestGuid UNIQUEIDENTIFIER;
            DECLARE @SuppressRunGuid UNIQUEIDENTIFIER;
            DECLARE @SuppressSourceType NVARCHAR(50);
            DECLARE @SuppressSourceGuid UNIQUEIDENTIFIER;
            DECLARE @SuppressSourceIntId INT;
            DECLARE @SuppressReason NVARCHAR(500);

            WHILE EXISTS
            (
                SELECT 1
                FROM #RequestPlan AS rp
                WHERE rp.RecoveryAction = N'SUPPRESS'
                  AND rp.Processed = 0
            )
            BEGIN
                SELECT TOP (1)
                      @SuppressRequestId = rp.RequestId
                    , @SuppressRequestGuid = rp.RequestGuid
                    , @SuppressRunGuid = rp.AutomationRunGuid
                    , @SuppressSourceType = rp.SourceType
                    , @SuppressSourceGuid = rp.SourceGuid
                    , @SuppressSourceIntId = rp.SourceIntId
                    , @SuppressReason = rp.RecoveryReason
                FROM #RequestPlan AS rp
                WHERE rp.RecoveryAction = N'SUPPRESS'
                  AND rp.Processed = 0
                ORDER BY rp.CreatedDateTimeUTC, rp.RequestId;

                BEGIN TRANSACTION;

                IF EXISTS
                (
                    SELECT 1
                    FROM SFin.InvoiceRequests AS ir WITH (UPDLOCK, HOLDLOCK)
                    WHERE ir.ID = @SuppressRequestId
                      AND ir.Guid = @SuppressRequestGuid
                      AND ir.RowStatus NOT IN (0, 254)
                      AND ir.InvoiceBatchGuid IS NULL
                      AND NOT EXISTS
                      (
                          SELECT 1
                          FROM SFin.InvoiceRequestItems AS iri
                          INNER JOIN SFin.TransactionDetails AS td
                              ON td.InvoiceRequestItemId = iri.ID
                          WHERE iri.InvoiceRequestId = ir.ID
                      )
                )
                BEGIN
                    EXEC SFin.InvoiceRequestsDelete
                        @Guid = @SuppressRequestGuid;

                    IF NOT EXISTS
                    (
                        SELECT 1
                        FROM SFin.InvoiceAutomationRunDetails AS d
                        WHERE d.RowStatus NOT IN (0, 254)
                          AND d.AutomationRunGuid = @SuppressRunGuid
                          AND d.InstanceKey = CONCAT(N'HISTORIC_REQUEST_SUPPRESSION|', CONVERT(NVARCHAR(36), @SuppressRequestGuid))
                    )
                    BEGIN
                        DECLARE @SuppressDetailGuid UNIQUEIDENTIFIER = NEWID();
                        DECLARE @SuppressDetailWasInserted BIT = 0;

                        EXEC SCore.UpsertDataObject
                              @Guid = @SuppressDetailGuid
                            , @SchemeName = N'SFin'
                            , @ObjectName = N'InvoiceAutomationRunDetails'
                            , @IncludeDefaultSecurity = 0
                            , @IsInsert = @SuppressDetailWasInserted OUTPUT;

                        INSERT INTO SFin.InvoiceAutomationRunDetails
                        (
                              RowStatus
                            , Guid
                            , AutomationRunGuid
                            , InvoiceScheduleId
                            , SourceType
                            , SourceGuid
                            , SourceIntId
                            , InstanceType
                            , InstanceKey
                            , Outcome
                            , Message
                            , InvoiceRequestGuid
                            , CreatedDateTimeUTC
                            , LegacyId
                            , LegacySystemID
                        )
                        VALUES
                        (
                              1
                            , @SuppressDetailGuid
                            , @SuppressRunGuid
                            , -1
                            , ISNULL(@SuppressSourceType, N'')
                            , @SuppressSourceGuid
                            , @SuppressSourceIntId
                            , N'InvoiceRequest'
                            , CONCAT(N'HISTORIC_REQUEST_SUPPRESSION|', CONVERT(NVARCHAR(36), @SuppressRequestGuid))
                            , N'Suppressed'
                            , CONCAT(N'Historic invalid request soft-deleted. ', @SuppressReason)
                            , @SuppressRequestGuid
                            , @NowUtc
                            , NULL
                            , -1
                        );
                    END;

                    UPDATE ar
                    SET ar.CreatedCount =
                        (
                            SELECT COUNT(1)
                            FROM SFin.InvoiceRequests AS ir
                            WHERE ir.RowStatus NOT IN (0, 254)
                              AND ir.AutomationRunGuid = @SuppressRunGuid
                              AND ISNULL(ir.IsAutomated, 0) = 1
                        )
                    FROM SFin.InvoiceAutomationRuns AS ar
                    WHERE ar.Guid = @SuppressRunGuid;

                    INSERT INTO #Applied
                    (
                          ActionType
                        , RequestGuid
                        , AutomationRunGuid
                        , InvoiceBatchGuid
                        , AppliedDateTimeUTC
                        , Message
                        , AuditLogged
                    )
                    VALUES
                    (
                          N'SUPPRESSED'
                        , @SuppressRequestGuid
                        , @SuppressRunGuid
                        , NULL
                        , @NowUtc
                        , @SuppressReason
                        , 1
                    );
                END
                ELSE
                BEGIN
                    INSERT INTO #Applied
                    (
                          ActionType
                        , RequestGuid
                        , AutomationRunGuid
                        , InvoiceBatchGuid
                        , AppliedDateTimeUTC
                        , Message
                        , AuditLogged
                    )
                    VALUES
                    (
                          N'SKIPPED_STATE_CHANGED'
                        , @SuppressRequestGuid
                        , @SuppressRunGuid
                        , NULL
                        , @NowUtc
                        , N'Request was not suppressed because its state changed or it became transaction-linked after planning.'
                        , 1
                    );
                END;

                UPDATE rp
                SET rp.Processed = 1
                FROM #RequestPlan AS rp
                WHERE rp.RequestId = @SuppressRequestId;

                COMMIT TRANSACTION;
            END;
        END;

        /* --------------------------------------------------------------
           C. Repair active child items beneath already-deleted parents.
           -------------------------------------------------------------- */
        IF @RepairDeletedParentItems = 1
        BEGIN
            DECLARE @OrphanRequestId INT;
            DECLARE @OrphanRequestGuid UNIQUEIDENTIFIER;
            DECLARE @OrphanRunGuid UNIQUEIDENTIFIER;
            DECLARE @OrphanItemCount INT;

            WHILE EXISTS
            (
                SELECT 1
                FROM #OrphanItemPlan AS op
                WHERE op.RecoveryAction = N'CLEAN_ORPHAN_ITEMS'
                  AND op.Processed = 0
            )
            BEGIN
                SELECT TOP (1)
                      @OrphanRequestId = op.RequestId
                    , @OrphanRequestGuid = op.RequestGuid
                    , @OrphanRunGuid = op.AutomationRunGuid
                FROM #OrphanItemPlan AS op
                WHERE op.RecoveryAction = N'CLEAN_ORPHAN_ITEMS'
                  AND op.Processed = 0
                ORDER BY op.RequestCreatedDateTimeUTC, op.RequestId;

                SELECT @OrphanItemCount = COUNT(1)
                FROM #OrphanItemPlan AS op
                WHERE op.RequestId = @OrphanRequestId
                  AND op.RecoveryAction = N'CLEAN_ORPHAN_ITEMS';

                BEGIN TRANSACTION;

                IF EXISTS
                (
                    SELECT 1
                    FROM SFin.InvoiceRequests AS ir WITH (UPDLOCK, HOLDLOCK)
                    WHERE ir.ID = @OrphanRequestId
                      AND ir.Guid = @OrphanRequestGuid
                      AND ir.RowStatus IN (0, 254)
                      AND NOT EXISTS
                      (
                          SELECT 1
                          FROM SFin.InvoiceRequestItems AS iri
                          INNER JOIN SFin.TransactionDetails AS td
                              ON td.InvoiceRequestItemId = iri.ID
                          WHERE iri.InvoiceRequestId = ir.ID
                      )
                )
                BEGIN
                    EXEC SFin.InvoiceRequestsDelete
                        @Guid = @OrphanRequestGuid;

                    IF NOT EXISTS
                    (
                        SELECT 1
                        FROM SFin.InvoiceAutomationRunDetails AS d
                        WHERE d.RowStatus NOT IN (0, 254)
                          AND d.AutomationRunGuid = @OrphanRunGuid
                          AND d.InstanceKey = CONCAT(N'HISTORIC_ORPHAN_CLEANUP|', CONVERT(NVARCHAR(36), @OrphanRequestGuid))
                    )
                    BEGIN
                        DECLARE @OrphanDetailGuid UNIQUEIDENTIFIER = NEWID();
                        DECLARE @OrphanDetailWasInserted BIT = 0;

                        EXEC SCore.UpsertDataObject
                              @Guid = @OrphanDetailGuid
                            , @SchemeName = N'SFin'
                            , @ObjectName = N'InvoiceAutomationRunDetails'
                            , @IncludeDefaultSecurity = 0
                            , @IsInsert = @OrphanDetailWasInserted OUTPUT;

                        INSERT INTO SFin.InvoiceAutomationRunDetails
                        (
                              RowStatus
                            , Guid
                            , AutomationRunGuid
                            , InvoiceScheduleId
                            , SourceType
                            , SourceGuid
                            , SourceIntId
                            , InstanceType
                            , InstanceKey
                            , Outcome
                            , Message
                            , InvoiceRequestGuid
                            , CreatedDateTimeUTC
                            , LegacyId
                            , LegacySystemID
                        )
                        VALUES
                        (
                              1
                            , @OrphanDetailGuid
                            , @OrphanRunGuid
                            , -1
                            , N''
                            , NULL
                            , NULL
                            , N'InvoiceRequest'
                            , CONCAT(N'HISTORIC_ORPHAN_CLEANUP|', CONVERT(NVARCHAR(36), @OrphanRequestGuid))
                            , N'Cleaned'
                            , CONCAT(N'Soft-deleted ', CONVERT(NVARCHAR(20), @OrphanItemCount), N' active child item(s) beneath an already-deleted invoice request.')
                            , @OrphanRequestGuid
                            , @NowUtc
                            , NULL
                            , -1
                        );
                    END;

                    INSERT INTO #Applied
                    (
                          ActionType
                        , RequestGuid
                        , AutomationRunGuid
                        , InvoiceBatchGuid
                        , AppliedDateTimeUTC
                        , Message
                        , AuditLogged
                    )
                    VALUES
                    (
                          N'ORPHAN_ITEMS_CLEANED'
                        , @OrphanRequestGuid
                        , @OrphanRunGuid
                        , NULL
                        , @NowUtc
                        , CONCAT(N'Soft-deleted ', CONVERT(NVARCHAR(20), @OrphanItemCount), N' orphan child item(s).')
                        , 1
                    );
                END
                ELSE
                BEGIN
                    INSERT INTO #Applied
                    (
                          ActionType
                        , RequestGuid
                        , AutomationRunGuid
                        , InvoiceBatchGuid
                        , AppliedDateTimeUTC
                        , Message
                        , AuditLogged
                    )
                    VALUES
                    (
                          N'SKIPPED_STATE_CHANGED'
                        , @OrphanRequestGuid
                        , @OrphanRunGuid
                        , NULL
                        , @NowUtc
                        , N'Orphan cleanup was skipped because the parent state changed or became transaction-linked after planning.'
                        , 1
                    );
                END;

                UPDATE op
                SET op.Processed = 1
                FROM #OrphanItemPlan AS op
                WHERE op.RequestId = @OrphanRequestId;

                COMMIT TRANSACTION;
            END;
        END;

        IF @LockAcquired = 1
        BEGIN
            EXEC sys.sp_releaseapplock
                  @Resource = @AppLockName
                , @LockOwner = N'Session';

            SET @LockAcquired = 0;
        END;

        /* Final apply result. */
        SELECT
              applied.ActionOrder
            , applied.ActionType
            , applied.RequestGuid
            , applied.AutomationRunGuid
            , applied.InvoiceBatchGuid
            , applied.AppliedDateTimeUTC
            , applied.Message
        FROM #Applied AS applied
        ORDER BY applied.ActionOrder;
    END TRY
    BEGIN CATCH
        IF CURSOR_STATUS('local', 'cur_recovery_run') >= 0
            CLOSE cur_recovery_run;

        IF CURSOR_STATUS('local', 'cur_recovery_run') > -3
            DEALLOCATE cur_recovery_run;

        IF XACT_STATE() <> 0
            ROLLBACK TRANSACTION;

        IF @LockAcquired = 1
        BEGIN
            EXEC sys.sp_releaseapplock
                  @Resource = @AppLockName
                , @LockOwner = N'Session';
        END;

        ;THROW;
    END CATCH;
END;
GO

