CREATE OR ALTER PROCEDURE [SFin].[InvoiceRequestWIPNotesUpsert]
(
    @InvoiceRequestGuid UNIQUEIDENTIFIER,
    @Note NVARCHAR(MAX),
    @CreatedByUserGuid UNIQUEIDENTIFIER,
    @Guid UNIQUEIDENTIFIER
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @InvoiceRequestId INT,
            @CreatedByUserId INT,
            @DataObjectWasInserted BIT;

    -- Null-safety for NOT NULL column
    SET @Note = ISNULL(@Note, N'');

    -- Resolve Invoice Request
    SELECT @InvoiceRequestId = ir.ID
    FROM SFin.InvoiceRequests AS ir
    WHERE ir.[Guid] = @InvoiceRequestGuid
      AND ir.RowStatus NOT IN (0, 254);

    IF (@InvoiceRequestId IS NULL)
        THROW 60000, N'InvoiceRequestWIPNotesUpsert: InvoiceRequestGuid not found.', 1;

    -- Resolve author; fall back to the calling user when the client does not supply one.
    SELECT @CreatedByUserId = i.ID
    FROM SCore.Identities AS i
    WHERE i.[Guid] = @CreatedByUserGuid;

    SET @CreatedByUserId = ISNULL(@CreatedByUserId, SCore.GetCurrentUserId());

    EXEC SCore.UpsertDataObject
        @Guid = @Guid,
        @SchemeName = N'SFin',
        @ObjectName = N'InvoiceRequestWIPNotes',
        @IsInsert = @DataObjectWasInserted OUTPUT;

    IF NOT EXISTS (SELECT 1 FROM SFin.InvoiceRequestWIPNotes WITH (UPDLOCK, HOLDLOCK) WHERE [Guid] = @Guid)
    BEGIN
        INSERT SFin.InvoiceRequestWIPNotes
        (
            RowStatus,
            Guid,
            InvoiceRequestId,
            Note,
            CreatedByUserId,
            CreatedDateTimeUTC
        )
        VALUES
        (
            1,
            @Guid,
            @InvoiceRequestId,
            @Note,
            @CreatedByUserId,
            GETUTCDATE()
        );
    END
    ELSE
    BEGIN
        UPDATE n
        SET
            n.InvoiceRequestId = @InvoiceRequestId,
            n.Note = @Note
        FROM SFin.InvoiceRequestWIPNotes AS n
        WHERE n.[Guid] = @Guid;
    END
END
