CREATE OR ALTER PROCEDURE [SFin].[SageInboundDiagnostics_Get]
(
    @StatusCode NVARCHAR(30) = NULL,
    @SageAccountReference NVARCHAR(100) = NULL,
    @SageDocumentNo NVARCHAR(100) = NULL,
    @TransactionNumber NVARCHAR(50) = NULL,
    @OnlyRetryableFailures BIT = NULL,
    @InvoiceRequestID INT = NULL,
    @TransactionID BIGINT = NULL,
    @JobID INT = NULL,
    @PaymentFilter NVARCHAR(20) = NULL,  -- NULL/'' = none, 'Paid', 'Open' (not terminal), 'Receipts' (has a materialised receipt)
    @PageNumber INT = 1,
    @PageSize INT = 50
)
AS
BEGIN
    SET NOCOUNT ON;

    IF (@PageNumber IS NULL OR @PageNumber < 1)
        SET @PageNumber = 1;

    IF (@PageSize IS NULL OR @PageSize < 1)
        SET @PageSize = 50;

    IF (@PageSize > 500)
        SET @PageSize = 500;

    -- Materialize the filtered set once, so the filter predicate exists in
    -- exactly one place and the total count can never drift from what the
    -- page is drawn from. A stale/out-of-range @PageNumber (e.g. requested
    -- just before a row action removed the last row on that page) is
    -- clamped below rather than silently returning zero rows with no total.
    SELECT
        d.ID,
        d.Guid,
        d.CymBuildEntityTypeID,
        d.CymBuildDocumentGuid,
        d.CymBuildDocumentID,
        d.InvoiceRequestID,
        d.TransactionID,
        d.JobID,
        d.JobNumber,
        d.SageDataset,
        d.SageAccountReference,
        d.SageDocumentNo,
        d.LastOperationName,
        d.StatusCode,
        d.IsInProgress,
        d.InProgressClaimedOnUtc,
        d.LastSucceededOnUtc,
        d.LastFailedOnUtc,
        d.LastError,
        d.LastErrorIsRetryable,
        d.LastSourceWatermarkUtc,
        d.LastGrossAmount,
        d.LastAllocatedValue,
        d.LastOutstandingAmount,
        d.LastDocumentDiscountedValue,
        d.LastIsPaid,
        d.LastIsFullyPaid,
        d.LastPaymentStateCode,
        d.LastTransactionDate,
        d.LastSageTransactionReference,
        d.LastSecondReference,
        d.LastSageTransactionTypeCode,
        d.NextPollDueOnUtc,
        d.PollAttemptCount,
        d.IsTerminalState,
        d.CreatedByUserID,
        d.CreatedDateTimeUTC,
        d.UpdatedByUserID,
        d.UpdatedDateTimeUTC,
        d.LastAttemptedOnUtc,
        d.LastCompletedOnUtc,
        d.LastAttemptIsSuccess,
        d.LastAttemptErrorMessage,
        d.LastAttemptIsRetryableFailure,
        d.LastAttemptResponseStatus,
        d.LastAttemptResponseDetail,
        d.CanRequeue,
        d.CanForceRequeue,
        d.TransactionGuid,
        d.TransactionNumber,
        d.TransactionIsBatched,
        d.MatchedTransactionGuid,
        d.MatchedTransactionNumber,
        d.MaterialisedReceiptTransactionGuid,
        d.MaterialisedReceiptTransactionNumber,
        d.MaterialisedAllocationGuid,
        d.MaterialisedAllocationID,
        d.TransactionSageTransactionReference,
        d.MatchedTransactionSageTransactionReference,
        d.LastMatchedExternalTransactionID,
        d.LastMatchedExternalTransactionTypeCode,
        d.LastMatchedExternalTransactionAllocatedValue
    INTO #Filtered
    FROM SFin.tvf_SageInboundDiagnostics
    (
        @StatusCode,
        @SageAccountReference,
        @SageDocumentNo,
        @OnlyRetryableFailures,
        @InvoiceRequestID,
        @TransactionID,
        @JobID,
        @TransactionNumber
    ) AS d
    WHERE
        (
            @PaymentFilter IS NULL OR @PaymentFilter = N''
            OR (@PaymentFilter = N'Paid' AND d.LastPaymentStateCode = N'Paid')
            OR (@PaymentFilter = N'Open' AND d.IsTerminalState = 0)
            OR (@PaymentFilter = N'Receipts' AND d.MaterialisedReceiptTransactionGuid IS NOT NULL)
        );

    DECLARE @TotalCount BIGINT = (SELECT COUNT(1) FROM #Filtered);

    IF (@TotalCount > 0 AND (CAST(@PageNumber AS BIGINT) - 1) * @PageSize >= @TotalCount)
        SET @PageNumber = (((@TotalCount - 1) / @PageSize) + 1);

    SELECT
        TotalCount = @TotalCount,
        d.ID,
        d.Guid,
        d.CymBuildEntityTypeID,
        d.CymBuildDocumentGuid,
        d.CymBuildDocumentID,
        d.InvoiceRequestID,
        d.TransactionID,
        d.JobID,
        d.JobNumber,
        d.SageDataset,
        d.SageAccountReference,
        d.SageDocumentNo,
        d.LastOperationName,
        d.StatusCode,
        d.IsInProgress,
        d.InProgressClaimedOnUtc,
        d.LastSucceededOnUtc,
        d.LastFailedOnUtc,
        d.LastError,
        d.LastErrorIsRetryable,
        d.LastSourceWatermarkUtc,
        d.LastGrossAmount,
        d.LastAllocatedValue,
        d.LastOutstandingAmount,
        d.LastDocumentDiscountedValue,
        d.LastIsPaid,
        d.LastIsFullyPaid,
        d.LastPaymentStateCode,
        d.LastTransactionDate,
        d.LastSageTransactionReference,
        d.LastSecondReference,
        d.LastSageTransactionTypeCode,
        d.NextPollDueOnUtc,
        d.PollAttemptCount,
        d.IsTerminalState,
        d.CreatedByUserID,
        d.CreatedDateTimeUTC,
        d.UpdatedByUserID,
        d.UpdatedDateTimeUTC,
        d.LastAttemptedOnUtc,
        d.LastCompletedOnUtc,
        d.LastAttemptIsSuccess,
        d.LastAttemptErrorMessage,
        d.LastAttemptIsRetryableFailure,
        d.LastAttemptResponseStatus,
        d.LastAttemptResponseDetail,
        d.CanRequeue,
        d.CanForceRequeue,

        d.TransactionGuid,
        d.TransactionNumber,
        d.TransactionIsBatched,
        d.MatchedTransactionGuid,
        d.MatchedTransactionNumber,
        d.MaterialisedReceiptTransactionGuid,
        d.MaterialisedReceiptTransactionNumber,
        d.MaterialisedAllocationGuid,
        d.MaterialisedAllocationID,
        d.TransactionSageTransactionReference,
        d.MatchedTransactionSageTransactionReference,
        d.LastMatchedExternalTransactionID,
        d.LastMatchedExternalTransactionTypeCode,
        d.LastMatchedExternalTransactionAllocatedValue
    FROM #Filtered AS d
    ORDER BY d.UpdatedDateTimeUTC DESC, d.ID DESC
    OFFSET (CAST(@PageNumber AS BIGINT) - 1) * @PageSize ROWS FETCH NEXT @PageSize ROWS ONLY;

    DROP TABLE #Filtered;
END
GO

