CREATE OR ALTER PROCEDURE [SJob].[FeeAmendmentChaseUpsert]
(
   @Guid				UNIQUEIDENTIFIER,
   @ChasedByUserGuid	UNIQUEIDENTIFIER,
   @DateChased			DATE,
   @FeeAmendmentGuid    UNIQUEIDENTIFIER
)
AS 
BEGIN 
    DECLARE @UserID INT,
            @JobID INT

	IF (@UserID IS NULL)
	BEGIN 
		SELECT @UserID = CONVERT(INT, SESSION_CONTEXT(N'user_id'))
	END

    

    DECLARE @IsInsert BIT
    EXEC SCore.UpsertDataObject @Guid = @Guid,					-- uniqueidentifier
							@SchemeName = N'SJob',				-- nvarchar(255)
							@ObjectName = N'FeeAmendmentChase',				-- nvarchar(255)
							@IsInsert = @IsInsert OUTPUT	-- bit


	DECLARE 
			@ChasedByUserId	INT,
			@FeeAmendmentId INT;

			
	SELECT @ChasedByUserId = ID 
	FROM SCore.Identities
	WHERE Guid = @ChasedByUserGuid;

	SELECT @FeeAmendmentId = ID
	FROM SJob.FeeAmendment
	WHERE Guid = @FeeAmendmentGuid;

	

    IF (@IsInsert = 1)
    BEGIN
        INSERT  SJob.FeeAmendmentChase 
        (
            RowStatus,
            [Guid],
			ChasedByUserID,
			DateChased,
			FeeAmendmentID
        )
        VALUES
        (
            1,
            @Guid,
			@ChasedByUserId,
			@DateChased,
			@FeeAmendmentId
        )
    END
    ELSE
    BEGIN 
        UPDATE  SJob.FeeAmendmentChase 
        SET     RowStatus					= 1,
				ChasedByUserID				= @ChasedByUserId,
				@DateChased					= @DateChased,
				FeeAmendmentID				= @FeeAmendmentId
        WHERE   ([Guid] = @Guid)
    END
END
