/* Deploy StoredProcedure SJob.JobRibaStageFees_UpsertFromCreatedQuoteItems using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SJob.JobRibaStageFees_UpsertFromCreatedQuoteItems.sql */
/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : StoredProcedure SJob.JobRibaStageFees_UpsertFromCreatedQuoteItems
    Source schema hash : F27722DE25A17BE028923A312717FEA5F1BF4552426438C2B479B856A29FC5E4
    Definition SHA-256 : A122FD7905BC6D15B60537ABDFC02F70D4A8D983F5D4EEE114A573F7F1A18486

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER PROCEDURE [SJob].[JobRibaStageFees_UpsertFromCreatedQuoteItems]
(
    @JobID INT
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    IF NOT EXISTS
    (
        SELECT 1
        FROM SJob.Jobs AS j
        WHERE j.ID = @JobID
          AND j.RowStatus NOT IN (0, 254)
    )
    BEGIN
        ;THROW 60000, N'Cannot upsert dynamic job RIBA stage fees because the supplied JobID is not active.', 1;
    END;

    IF NOT EXISTS
    (
        SELECT 1
        FROM SCore.EntityHobts AS eh
        JOIN SCore.EntityTypes AS et
            ON et.ID = eh.EntityTypeID
        WHERE eh.SchemaName = N'SJob'
          AND eh.ObjectName = N'JobRibaStageFees'
          AND eh.RowStatus NOT IN (0, 254)
          AND et.RowStatus NOT IN (0, 254)
    )
    BEGIN
        ;THROW 60000, N'SJob.JobRibaStageFees metadata is missing. Deploy the source-controlled HoBT/EntityType metadata before recalculating Job RIBA stage fees.', 1;
    END;

    IF COL_LENGTH(N'SFin.InvoiceScheduleMonthConfiguration', N'RIBAStageId') IS NULL
    BEGIN
        ;THROW 60000, N'SFin.InvoiceScheduleMonthConfiguration.RIBAStageId is missing. Deploy the source-controlled schema before recalculating Job RIBA stage fees.', 1;
    END;

    IF COL_LENGTH(N'SFin.InvoiceSchedulePercentageConfiguration', N'RIBAStageId') IS NULL
    BEGIN
        ;THROW 60000, N'SFin.InvoiceSchedulePercentageConfiguration.RIBAStageId is missing. Deploy the source-controlled schema before recalculating Job RIBA stage fees.', 1;
    END;

    IF COL_LENGTH(N'SFin.InvoiceSchedulePercentageConfiguration', N'Percentage') IS NULL
    BEGIN
        ;THROW 60000, N'SFin.InvoiceSchedulePercentageConfiguration.Percentage is missing. Deploy the source-controlled schema before recalculating Job RIBA stage fees.', 1;
    END;

    DECLARE @CurrentUserID INT = ISNULL(CONVERT(INT, SESSION_CONTEXT(N'user_id')), -1);
    DECLARE @GuidList SCore.GuidUniqueList;
    DECLARE @IsInsert BIT = 0;
    DECLARE @StartedTransaction BIT = 0;

    DECLARE @SelectedQuoteItems TABLE
    (
        QuoteItemID INT NOT NULL PRIMARY KEY,
        QuoteId INT NOT NULL,
        InvoiceScheduleID INT NOT NULL,
        RibaStageID INT NOT NULL,
        LineNet DECIMAL(19, 2) NOT NULL,
        SortOrder INT NOT NULL
    );

    DECLARE @InvoiceScheduleStages TABLE
    (
        InvoiceScheduleID INT NOT NULL,
        RibaStageID INT NOT NULL,
        StageScheduleTotal DECIMAL(19, 2) NOT NULL,
        PRIMARY KEY (InvoiceScheduleID, RibaStageID)
    );

    DECLARE @StageFees TABLE
    (
        Guid UNIQUEIDENTIFIER NOT NULL,
        JobID INT NOT NULL,
        RibaStageID INT NOT NULL PRIMARY KEY,
        CreatedFromQuoteItemID INT NOT NULL,
        AgreedFee DECIMAL(19, 2) NOT NULL
    );

    INSERT INTO @SelectedQuoteItems
    (
        QuoteItemID,
        QuoteId,
        InvoiceScheduleID,
        RibaStageID,
        LineNet,
        SortOrder
    )
    SELECT
        CONVERT(INT, qi.ID) AS QuoteItemID,
        qi.QuoteId,
        qi.InvoicingSchedule AS InvoiceScheduleID,
        CASE
            WHEN qi.ProvideAtStageID = -1 THEN 2
            ELSE qi.ProvideAtStageID
        END AS RibaStageID,
        CONVERT(DECIMAL(19, 2), qit.LineNet) AS LineNet,
        qi.SortOrder
    FROM SSop.QuoteItems AS qi
    JOIN SSop.QuoteItemTotals AS qit
        ON qit.ID = qi.ID
    WHERE qi.CreatedJobId = @JobID
      AND qi.RowStatus NOT IN (0, 254)
      AND qi.Quantity > 0
      AND CASE
              WHEN qi.ProvideAtStageID = -1 THEN 2
              ELSE qi.ProvideAtStageID
          END > 0;

    IF NOT EXISTS
    (
        SELECT 1
        FROM @SelectedQuoteItems
    )
    BEGIN
        RETURN;
    END;

    ;WITH SelectedSchedules AS
    (
        SELECT DISTINCT
            sqi.QuoteId,
            sqi.InvoiceScheduleID
        FROM @SelectedQuoteItems AS sqi
        WHERE sqi.InvoiceScheduleID > 0
    ),
    ScheduleStageTotals AS
    (
        SELECT
            sch.ID AS InvoiceScheduleID,
            monthconf.RIBAStageId AS RibaStageID,
            SUM(CONVERT(DECIMAL(19, 2), monthconf.Amount)) AS StageScheduleTotal
        FROM SelectedSchedules AS ss
        JOIN SFin.InvoiceSchedules AS sch
            ON sch.ID = ss.InvoiceScheduleID
           AND sch.QuoteId = ss.QuoteId
        JOIN SFin.InvoiceScheduleMonthConfiguration AS monthconf
            ON monthconf.InvoiceScheduleId = sch.ID
        WHERE sch.RowStatus NOT IN (0, 254)
          AND monthconf.RowStatus NOT IN (0, 254)
          AND monthconf.RIBAStageId > 0
        GROUP BY
            sch.ID,
            monthconf.RIBAStageId

        UNION ALL

        SELECT
            sch.ID AS InvoiceScheduleID,
            percentconf.RIBAStageId AS RibaStageID,
            SUM
            (
                CONVERT
                (
                    DECIMAL(19, 2),
                    ROUND
                    (
                        sch.Amount * (percentconf.Percentage / CONVERT(DECIMAL(19, 2), 100.00)),
                        2
                    )
                )
            ) AS StageScheduleTotal
        FROM SelectedSchedules AS ss
        JOIN SFin.InvoiceSchedules AS sch
            ON sch.ID = ss.InvoiceScheduleID
           AND sch.QuoteId = ss.QuoteId
        JOIN SFin.InvoiceSchedulePercentageConfiguration AS percentconf
            ON percentconf.InvoiceScheduleId = sch.ID
        WHERE sch.RowStatus NOT IN (0, 254)
          AND percentconf.RowStatus NOT IN (0, 254)
          AND percentconf.RIBAStageId > 0
        GROUP BY
            sch.ID,
            percentconf.RIBAStageId
    )
    INSERT INTO @InvoiceScheduleStages
    (
        InvoiceScheduleID,
        RibaStageID,
        StageScheduleTotal
    )
    SELECT
        sst.InvoiceScheduleID,
        sst.RibaStageID,
        SUM(sst.StageScheduleTotal) AS StageScheduleTotal
    FROM ScheduleStageTotals AS sst
    GROUP BY
        sst.InvoiceScheduleID,
        sst.RibaStageID;

    ---------------------------------------------------------------------
    -- CYB-573: a schedule's staged amounts stand in only for the items on
    -- that same schedule at those stages. Every other item (no schedule, a
    -- schedule with no stage amounts, or a stage its schedule does not
    -- configure) keeps its own LineNet. Previously any schedule's stage total
    -- replaced every item on that stage, so an item on a different schedule
    -- was dropped from the Job fee.
    ---------------------------------------------------------------------
    ;WITH StageContributions AS
    (
        SELECT
            sqi.RibaStageID,
            sqi.LineNet AS Amount
        FROM @SelectedQuoteItems AS sqi
        WHERE NOT EXISTS
        (
            SELECT 1
            FROM @InvoiceScheduleStages AS iss
            WHERE iss.InvoiceScheduleID = sqi.InvoiceScheduleID
              AND iss.RibaStageID = sqi.RibaStageID
        )

        UNION ALL

        SELECT
            iss.RibaStageID,
            iss.StageScheduleTotal AS Amount
        FROM @InvoiceScheduleStages AS iss
    ),
    StageTotals AS
    (
        SELECT
            sc.RibaStageID,
            SUM(sc.Amount) AS AgreedFee
        FROM StageContributions AS sc
        GROUP BY
            sc.RibaStageID
    ),
    RequiredStages AS
    (
        -- Link each stage to the first item on that stage or, for a stage
        -- that only a schedule configures, the first item on that schedule.
        SELECT
            st.RibaStageID,
            stageAnchor.QuoteItemID AS CreatedFromQuoteItemID,
            st.AgreedFee
        FROM StageTotals AS st
        CROSS APPLY
        (
            SELECT TOP (1)
                sqi.QuoteItemID
            FROM @SelectedQuoteItems AS sqi
            WHERE sqi.RibaStageID = st.RibaStageID
               OR EXISTS
               (
                   SELECT 1
                   FROM @InvoiceScheduleStages AS iss
                   WHERE iss.InvoiceScheduleID = sqi.InvoiceScheduleID
                     AND iss.RibaStageID = st.RibaStageID
               )
            ORDER BY
                CASE
                    WHEN sqi.RibaStageID = st.RibaStageID THEN 0
                    ELSE 1
                END,
                sqi.SortOrder,
                sqi.QuoteItemID
        ) AS stageAnchor
    )
    INSERT INTO @StageFees
    (
        Guid,
        JobID,
        RibaStageID,
        CreatedFromQuoteItemID,
        AgreedFee
    )
    SELECT
        ISNULL(existing.Guid, NEWID()) AS Guid,
        @JobID AS JobID,
        rs.RibaStageID,
        rs.CreatedFromQuoteItemID,
        CONVERT(DECIMAL(19, 2), rs.AgreedFee) AS AgreedFee
    FROM RequiredStages AS rs
    OUTER APPLY
    (
        SELECT TOP (1)
            jrsf.Guid
        FROM SJob.JobRibaStageFees AS jrsf
        WHERE jrsf.JobID = @JobID
          AND jrsf.RibaStageID = rs.RibaStageID
          AND jrsf.RowStatus NOT IN (0, 254)
        ORDER BY
            jrsf.ID
    ) AS existing;

    IF NOT EXISTS
    (
        SELECT 1
        FROM @StageFees
    )
    BEGIN
        RETURN;
    END;

    BEGIN TRY
        IF @@TRANCOUNT = 0
        BEGIN
            BEGIN TRANSACTION;
            SET @StartedTransaction = 1;
        END;

        INSERT INTO @GuidList
        (
            GuidValue
        )
        SELECT
            sf.Guid
        FROM @StageFees AS sf
        WHERE NOT EXISTS
        (
            SELECT 1
            FROM SCore.DataObjects AS d
            WHERE d.Guid = sf.Guid
        );

        IF EXISTS
        (
            SELECT 1
            FROM @GuidList
        )
        BEGIN
            EXEC SCore.DataObjectBulkUpsert
                 @GuidList   = @GuidList,
                 @SchemeName = N'SJob',
                 @ObjectName = N'JobRibaStageFees',
                 @IsInsert   = @IsInsert OUTPUT;
        END;

        ---------------------------------------------------------------------
        -- Previous versions could create more than one active row for the same
        -- Job/RIBA stage when multiple QuoteItems shared a stage. The new
        -- business rule produces one Job fee row per stage, so keep the first
        -- active row and retire any additional active rows before applying the
        -- recalculated value.
        ---------------------------------------------------------------------
        ;WITH ActiveRowsForRecalculatedStages AS
        (
            SELECT
                target.ID,
                ROW_NUMBER() OVER
                (
                    PARTITION BY
                        target.JobID,
                        target.RibaStageID
                    ORDER BY
                        CASE
                            WHEN target.Guid = sf.Guid THEN 0
                            ELSE 1
                        END,
                        target.ID
                ) AS RowNumber
            FROM SJob.JobRibaStageFees AS target
            JOIN @StageFees AS sf
                ON sf.JobID = target.JobID
               AND sf.RibaStageID = target.RibaStageID
            WHERE target.RowStatus NOT IN (0, 254)
        )
        UPDATE target
        SET
            target.RowStatus = 254,
            target.LastUpdatedDateTimeUTC = SYSUTCDATETIME(),
            target.LastUpdatedByUserID = @CurrentUserID
        FROM SJob.JobRibaStageFees AS target
        JOIN ActiveRowsForRecalculatedStages AS activeRows
            ON activeRows.ID = target.ID
        WHERE activeRows.RowNumber > 1;

        UPDATE target
        SET
            target.RowStatus = 1,
            target.JobID = sf.JobID,
            target.RibaStageID = sf.RibaStageID,
            target.CreatedFromQuoteItemID = sf.CreatedFromQuoteItemID,
            target.AgreedFee = sf.AgreedFee,
            target.LastUpdatedDateTimeUTC = SYSUTCDATETIME(),
            target.LastUpdatedByUserID = @CurrentUserID
        FROM SJob.JobRibaStageFees AS target
        JOIN @StageFees AS sf
            ON sf.JobID = target.JobID
           AND sf.RibaStageID = target.RibaStageID
        WHERE target.RowStatus NOT IN (0, 254)
          AND
          (
                 target.CreatedFromQuoteItemID <> sf.CreatedFromQuoteItemID
              OR target.AgreedFee <> sf.AgreedFee
              OR target.RowStatus <> 1
          );

        INSERT INTO SJob.JobRibaStageFees
        (
            RowStatus,
            Guid,
            JobID,
            RibaStageID,
            CreatedFromQuoteItemID,
            AgreedFee,
            CreatedDateTimeUTC,
            CreatedByUserID,
            LastUpdatedDateTimeUTC,
            LastUpdatedByUserID
        )
        SELECT
            1 AS RowStatus,
            sf.Guid,
            sf.JobID,
            sf.RibaStageID,
            sf.CreatedFromQuoteItemID,
            sf.AgreedFee,
            SYSUTCDATETIME() AS CreatedDateTimeUTC,
            @CurrentUserID AS CreatedByUserID,
            NULL AS LastUpdatedDateTimeUTC,
            NULL AS LastUpdatedByUserID
        FROM @StageFees AS sf
        WHERE NOT EXISTS
        (
            SELECT 1
            FROM SJob.JobRibaStageFees AS existing
            WHERE existing.JobID = sf.JobID
              AND existing.RibaStageID = sf.RibaStageID
              AND existing.RowStatus NOT IN (0, 254)
        );

        IF @StartedTransaction = 1
        BEGIN
            COMMIT TRANSACTION;
        END;
    END TRY
    BEGIN CATCH
        IF @StartedTransaction = 1
           AND XACT_STATE() <> 0
        BEGIN
            ROLLBACK TRANSACTION;
        END;

        THROW;
    END CATCH;
END;
GO

GO

/* Deploy StoredProcedure SJob.Jobs_BackfillMissingQuoteStageFees_CYB553 using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SJob.Jobs_BackfillMissingQuoteStageFees_CYB553.sql */
/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : StoredProcedure SJob.Jobs_BackfillMissingQuoteStageFees_CYB553
    Source schema hash : B07DBACF096AA9D19948E39BBB4EF678CEB6223F5340D59E7671FA4F7B35D0A9
    Definition SHA-256 : CB4DA93E9160ED5CDF347AA1E82C0292D5FB76748E9B6668264C778D25BF8C73

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/*
    CYB-553: SSop.Quote_JobsSummary's RibaStages join previously had no fallback for
    QuoteItems.ProvideAtStageID = -1 ("no stage set"), so those quote items were
    silently excluded from the fixed fee columns SSop.QuoteCreateJobs writes onto a
    new Job at creation time. This leaves the affected Job's own fee data at zero
    even though the originating quote item carries a real value (e.g. Job 9433).

    This procedure finds Jobs safely eligible for correction - Jobs whose fixed fee
    columns AND SJob.JobRibaStageFees are both entirely empty/zero, created from a
    Quote with at least one QuoteItem where ProvideAtStageID = -1 and a non-zero
    LineNet - and, when @PreviewOnly = 0, corrects them by calling the existing,
    already-correct SJob.JobRibaStageFees_UpsertFromCreatedQuoteItems for each one
    (the same procedure that already applies the -1 -> 2 sentinel remap).

    Jobs whose fixed fee columns are only PARTIALLY populated are deliberately
    excluded and reported separately, never auto-corrected: forcing dynamic-stage
    mode (SJob.JobRibaStageFees having any row) on a Job that already has legitimate
    legacy per-stage fee data makes SJob.Job_FeeDrawdown ignore those other legacy
    stage columns entirely, which would blank out real fee data instead of fixing it.
    Those require manual review.

    Run with @PreviewOnly = 1 (default) first and review the report before running
    with @PreviewOnly = 0 to apply the fix.
*/
CREATE OR ALTER PROCEDURE [SJob].[Jobs_BackfillMissingQuoteStageFees_CYB553]
(
    @PreviewOnly BIT = 1
)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @Candidates TABLE
    (
        JobID INT NOT NULL PRIMARY KEY,
        HasPartialLegacyFees BIT NOT NULL
    );

    INSERT INTO @Candidates
    (
        JobID,
        HasPartialLegacyFees
    )
    SELECT
        j.ID,
        CASE
            WHEN
                  ISNULL(j.AgreedFee, 0) + ISNULL(j.RibaStage1Fee, 0) + ISNULL(j.RibaStage2Fee, 0)
                + ISNULL(j.RibaStage3Fee, 0) + ISNULL(j.RibaStage4Fee, 0) + ISNULL(j.RibaStage5Fee, 0)
                + ISNULL(j.RibaStage6Fee, 0) + ISNULL(j.RibaStage7Fee, 0)
                + ISNULL(j.PreConstructionStageFee, 0) + ISNULL(j.ConstructionStageFee, 0) <> 0
                THEN 1
            ELSE 0
        END AS HasPartialLegacyFees
    FROM SJob.Jobs AS j
    WHERE j.RowStatus NOT IN (0, 254)
      AND NOT EXISTS
      (
          SELECT 1
          FROM SJob.JobRibaStageFees AS jrsf
          WHERE jrsf.JobID = j.ID
            AND jrsf.RowStatus NOT IN (0, 254)
      )
      AND EXISTS
      (
          SELECT 1
          FROM SSop.QuoteItems AS qi
          JOIN SSop.QuoteItemTotals AS qit
              ON qit.ID = qi.ID
          WHERE qi.CreatedJobId = j.ID
            AND qi.RowStatus NOT IN (0, 254)
            AND qi.ProvideAtStageID = -1
            AND ISNULL(qit.LineNet, 0) <> 0
      );

    IF @PreviewOnly = 1
    BEGIN
        SELECT
            c.JobID,
            j.Number AS JobNumber,
            c.HasPartialLegacyFees,
            CASE
                WHEN c.HasPartialLegacyFees = 1 THEN N'SKIP - manual review required'
                ELSE N'FIX - safe to backfill'
            END AS ProposedAction
        FROM @Candidates AS c
        JOIN SJob.Jobs AS j
            ON j.ID = c.JobID
        ORDER BY
            c.HasPartialLegacyFees,
            c.JobID;

        RETURN;
    END;

    DECLARE @JobID INT;

    DECLARE candidate_cursor CURSOR LOCAL FAST_FORWARD FOR
        SELECT JobID
        FROM @Candidates
        WHERE HasPartialLegacyFees = 0;

    OPEN candidate_cursor;
    FETCH NEXT FROM candidate_cursor INTO @JobID;

    WHILE @@FETCH_STATUS = 0
    BEGIN
        EXEC SJob.JobRibaStageFees_UpsertFromCreatedQuoteItems @JobID = @JobID;
        FETCH NEXT FROM candidate_cursor INTO @JobID;
    END;

    CLOSE candidate_cursor;
    DEALLOCATE candidate_cursor;

    SELECT
        c.JobID,
        j.Number AS JobNumber,
        N'FIXED' AS Action
    FROM @Candidates AS c
    JOIN SJob.Jobs AS j
        ON j.ID = c.JobID
    WHERE c.HasPartialLegacyFees = 0
    ORDER BY
        c.JobID;

    SELECT
        c.JobID,
        j.Number AS JobNumber,
        N'SKIPPED - manual review required' AS Action
    FROM @Candidates AS c
    JOIN SJob.Jobs AS j
        ON j.ID = c.JobID
    WHERE c.HasPartialLegacyFees = 1
    ORDER BY
        c.JobID;
END;
GO

GO

