/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : StoredProcedure SJob.JobTypesDuplicate
    Source schema hash : D36C51631C3F6E28D726C4CE2687EA3130F058B1F39B20347AEB2EBC8D952CF9
    Definition SHA-256 : 412D194CD9CA07B62A3694ECE2B0AC9651691E51FD5636675A29EB37FED80B12

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER PROCEDURE [SJob].[JobTypesDuplicate] 
								@SourceGuid UNIQUEIDENTIFIER,
								@TargetGuid UNIQUEIDENTIFIER
AS
BEGIN

	DECLARE @Name NVARCHAR(100),
			@SourceID INT,
			@ID INT,
			@UseTimeSheets BIT,
			@OrganisationalUnitGuid UNIQUEIDENTIFIER


	-- CYB-572 follow-up: the copy keeps the source's timesheet and org unit settings.
	SELECT	@Name = jt.Name + N' - Copy',
			@SourceID = jt.ID,
			@UseTimeSheets = jt.UseTimeSheets,
			@OrganisationalUnitGuid = ou.Guid
	FROM	SJob.JobTypes jt
	JOIN	SCore.OrganisationalUnits ou ON (ou.ID = jt.OrganisationalUnitID)
	WHERE	(jt.Guid = @SourceGuid)

	EXEC SJob.JobTypesUpsert @Name = @Name,			-- nvarchar(100)
							 @IsActive = 0,		-- bit
							 @UseTimeSheets = @UseTimeSheets,
							 @OrganisationalUnitGuid = @OrganisationalUnitGuid,
							 @Guid = @TargetGuid OUTPUT	-- uniqueidentifier
	
	SELECT	@ID = id 
	FROM	SJob.JobTypes
	WHERE	(Guid = @TargetGuid)

	INSERT	SJob.JobTypeMilestoneTemplates
		 (RowStatus, Guid, JobTypeID, MilestoneTypeID, Description, SortOrder)
	SELECT	1, NEWID(), @ID, MilestoneTypeID, Description, SortOrder 
	FROM	SJob.JobTypeMilestoneTemplates 
	WHERE	(JobTypeID = @SourceID)
		AND	(RowStatus NOT IN (0, 254))

	INSERT	SJob.JobTypeProjectDirectoryRoles
		 (RowStatus, Guid, JobTypeID, ProjectDirectoryRoleID, SortOrder)
	SELECT	1, NEWID(), @ID, ProjectDirectoryRoleID, SortOrder
	FROM	SJob.JobTypeProjectDirectoryRoles
	WHERE	(JobTypeID = @SourceID)
		AND	(RowStatus NOT IN (0, 254))

	INSERT	SJob.JobTypeActivityTypes
		 (RowStatus, Guid, JobTypeID, ActivityTypeID)
	SELECT	1, NEWID(), @ID, ActivityTypeID
	FROM	SJob.JobTypeActivityTypes 
	WHERE	(JobTypeID = @SourceID)
		AND	(RowStatus NOT IN (0, 254))
END;
GO

GO

