/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : StoredProcedure SJob.PurchaseOrdersUpsert
    Source schema hash : 2E7C5124E13E527DCC68889AAC5B6437978274856903F501CDD80E608A00CE8C
    Definition SHA-256 : CE540FA49C8D8FA3DCD062B0F5884D9EAB12E97F922E6F7554A573989D83C217

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER PROCEDURE [SJob].[PurchaseOrdersUpsert]
	(
		@Guid			UNIQUEIDENTIFIER,
		@Number			NVARCHAR(15),
		@Description	NVARCHAR(MAX),
		@Value			DECIMAL(19,2),
		@DateReceived	DATE,
		@ValidUntilDate DATE,
		@ActivityGuid	UNIQUEIDENTIFIER,
		@JobGuid		UNIQUEIDENTIFIER,
		@InvoiceRequestGuid UNIQUEIDENTIFIER

	)
AS
	BEGIN

		DECLARE 
				@ActivityId			INT = -1,
				@StageId			INT = -1,
				@AssetId			INT = -1,
				@JobId				INT = -1,
				@InvoiceRequestId	INT = -1;

				

		SELECT @ActivityId = ID
		FROM SJob.Activities
		WHERE (Guid = @ActivityGuid);

		--SELECT @StageId = ID 
		--FROM SJob.RibaStages
		--WHERE (Guid = @StageGuid);

		--SELECT @AssetId = ID
		--FROM SJob.Assets
		--WHERE (Guid = @StageGuid);

		SELECT @JobId = ID
		FROM SJob.Jobs
		WHERE (Guid = @JobGuid);


		SELECT @InvoiceRequestId = ID 
		FROM SFin.InvoiceRequests
		WHERE Guid = @InvoiceRequestGuid;




		DECLARE @IsInsert BIT
		EXEC SCore.UpsertDataObject
			@Guid		= @Guid,					-- uniqueidentifier
			@SchemeName = N'SJob',				-- nvarchar(255)
			@ObjectName = N'PurchaseOrders',				-- nvarchar(255)
			@IsInsert   = @IsInsert OUTPUT	-- bit

		IF (@IsInsert = 1)
			BEGIN
				INSERT SJob.PurchaseOrders
						(
							RowStatus,
							Guid,
							Number,
							Description,
							StageId,
							SiteId,
							Value,
							DateReceived,
							ValidUntilDate,
							ActivityId,
							JobId,
							InvoiceRequestId
						)
				VALUES
						(
							1,	-- RowStatus - tinyint
							@Guid,	-- Guid - uniqueidentifier
							@Number,
							@Description,
							@StageId,
							@AssetId,
							@Value,
							@DateReceived,
							@ValidUntilDate,
							@ActivityId,
							@JobId,
							@InvoiceRequestId
						)
			END
		ELSE
			BEGIN
				UPDATE  SJob.PurchaseOrders
				SET		
					Number				= @Number,
					Description			= @Description,
					StageId				= @StageId,
					SiteId				= @AssetId,
					Value				= @Value,
					DateReceived		= @DateReceived,
					ValidUntilDate		= @ValidUntilDate,
					ActivityId			= @ActivityId,
					JobId				= @JobId,
					InvoiceRequestId	= @InvoiceRequestId
				WHERE
					([Guid] = @Guid)
			END
	END
GO

