/* Deploy StoredProcedure SJob.SubContractorInvoicesUpsert using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SJob.SubContractorInvoicesUpsert.sql */
/*
    CymBuild generated canonical schema source.
    Generated by       : CYB-361 R7C4 selected DEV schema source sync
    Object             : StoredProcedure SJob.SubContractorInvoicesUpsert
    Source schema hash : 9C168117D2DE9DB6A352350B692FA0A115C4017D8A06FFCFF51197A816A49F4D
    Definition SHA-256 : E57A4DBA28ED99DE6987C4E3D82F8665A05524BC5A7373821F19ED7AB9EA59E9

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
CREATE OR ALTER PROCEDURE [SJob].[SubContractorInvoicesUpsert]
	(	
		@Guid UNIQUEIDENTIFIER,
		@InvoiceNumber NVARCHAR(100),
		@InvoiceDate DATE,
		@DescriptionOfWork NVARCHAR(MAX),
		@SupportingComments NVARCHAR(MAX),
		@ActivityGuid UNIQUEIDENTIFIER,
		@MilestoneGuid UNIQUEIDENTIFIER,
		@ValueWithVAT DECIMAL(19,2),
		@ValueWithoutVAT DECIMAL(19,2),
		@SubContractorName NVARCHAR(100),
		@JobGuid UNIQUEIDENTIFIER,
		@SubContractorGuid UNIQUEIDENTIFIER
		
	)
AS
BEGIN
	DECLARE 
			@ActivityId		BIGINT,
			@MilestoneId	BIGINT,
			@JobId			INT,
			@IsInsert		BIT,
			@SubContractorId INT,
			@IsPurchaseLedger BIT;


	SELECT @MilestoneId = ID
	FROM SJob.Milestones
	WHERE ([Guid] = @MilestoneGuid);

	SELECT @ActivityId = ID
	FROM SJob.Activities 
	WHERE ([Guid] = @ActivityGuid);

	SELECT @JobId = ID
	FROM SJob.Jobs
	WHERE ([Guid] = @JobGuid);

	SELECT 
			@SubContractorId = ID,
			@IsPurchaseLedger = IsPurchaseLedger
	FROM SCrm.Accounts
	WHERE ([Guid] = @SubContractorGuid)


	IF(@IsPurchaseLedger = 0)
		THROW 60361, N'Account must be set to a purchase ledger. ', 1;

	

	EXEC SCore.UpsertDataObject @Guid = @Guid,					-- uniqueidentifier
							@SchemeName = N'SJob',				-- nvarchar(255)
							@ObjectName = N'SubContractorInvoices',				-- nvarchar(255)
							@IncludeDefaultSecurity = 0,
							@IsInsert = @IsInsert OUTPUT	-- bit

    IF (@IsInsert = 1)
	BEGIN
		INSERT	SJob.SubContractorInvoices
			 (
				RowStatus,
				Guid,
				InvoiceNumber,
				InvoiceDate,
				DescriptionOfWork,
				SupportingComments,
				ActivityId,
				MilestoneId,
				ValueWithVAT,
				ValueWithoutVAT,
				SubContractorName,
				JobId,
				SubContractorId
			) 
		VALUES
			 (
				 1,								-- RowStatus - tinyint
				 @Guid,							-- Guid - uniqueidentifier
				 @InvoiceNumber,
				 @InvoiceDate,
				 @DescriptionOfWork,
				 @SupportingComments,
				 @ActivityId,
				 @MilestoneId,
				 @ValueWithVAT,
				 @ValueWithoutVAT,
				 @SubContractorName,
				 @JobId,
				 @SubContractorId
			 );
	END;
	ELSE
	BEGIN
		UPDATE	SJob.SubContractorInvoices
		SET		
				InvoiceNumber = @InvoiceNumber,
				InvoiceDate = @InvoiceDate,
				DescriptionOfWork = @DescriptionOfWork,
				SupportingComments = @SupportingComments,
				ActivityId = @ActivityId,
				MilestoneId = @MilestoneId,
				ValueWithVAT = @ValueWithVAT,
				ValueWithoutVAT = @ValueWithoutVAT,
				SubContractorName = @SubContractorName,
				SubContractorId = @SubContractorId
		WHERE	(Guid = @Guid);
	END;


END;
