/* Deploy StoredProcedure SMigration.MetadataValidate_Run using CanonicalAlter from C:\Users\stephen.brett\source\CymBuild.Monorepo\Database\CymBuild_DB\Schema\Programmability\Procedures\SMigration.MetadataValidate_Run.sql */
SET QUOTED_IDENTIFIER, ANSI_NULLS ON
GO

PRINT (N'Create procedure [SMigration].[MetadataValidate_Run]')
GO

CREATE OR ALTER PROCEDURE [SMigration].[MetadataValidate_Run]
(
    @RunGuid UNIQUEIDENTIFIER
)
AS
BEGIN
    SET NOCOUNT ON;
    SET XACT_ABORT ON;

    DECLARE @FailCount INT = 0;
    DECLARE @WarnCount INT = 0;
    DECLARE @InfoCount INT = 0;
    DECLARE @TargetDatabaseName SYSNAME;

    SELECT
        @TargetDatabaseName = run.TargetDatabaseName
    FROM SMigration.Metadata_Run AS run
    WHERE run.Guid = @RunGuid
      AND run.RowStatus NOT IN (0,254);

    BEGIN TRANSACTION;

    CREATE TABLE #MetadataSelectedValidationRows
    (
        RegistryGuid UNIQUEIDENTIFIER NOT NULL,
        SourceRowGuid UNIQUEIDENTIFIER NOT NULL,
        CONSTRAINT PK_MetadataSelectedValidationRows PRIMARY KEY CLUSTERED
        (
            RegistryGuid,
            SourceRowGuid
        )
    );

    INSERT INTO #MetadataSelectedValidationRows
    (
        RegistryGuid,
        SourceRowGuid
    )
    SELECT DISTINCT
        sr.RegistryGuid,
        sr.SourceRowGuid
    FROM SMigration.Metadata_StagedRows AS sr
    INNER JOIN SMigration.Metadata_RunSelections AS selection
        ON selection.RunGuid = sr.RunGuid
       AND selection.RegistryGuid = sr.RegistryGuid
       AND selection.SourceRowGuid = sr.SourceRowGuid
       AND selection.RowStatus NOT IN (0,254)
    INNER JOIN SMigration.Metadata_Run AS run
        ON run.Guid = sr.RunGuid
       AND run.RowStatus NOT IN (0,254)
    WHERE sr.RunGuid = @RunGuid
      AND sr.RowStatus NOT IN (0,254)
      AND sr.DifferenceType IN (N'Insert', N'Update')
      AND NOT EXISTS
      (
          SELECT 1
          FROM SMigration.Metadata_IgnoredRecords AS ignored
          WHERE ignored.DatabaseName = run.TargetDatabaseName
            AND ignored.RegistryGuid = sr.RegistryGuid
            AND ignored.SourceRowGuid = sr.SourceRowGuid
            AND ignored.RowStatus NOT IN (0,254)
      )
      AND NOT EXISTS
      (
          SELECT 1
          FROM SMigration.Metadata_IdentityMapOverrides AS identityOverride
          WHERE identityOverride.DatabaseName = run.TargetDatabaseName
            AND identityOverride.RegistryGuid = sr.RegistryGuid
            AND identityOverride.SourceRowGuid = sr.SourceRowGuid
            AND identityOverride.RowStatus NOT IN (0,254)
      );

    -- Only clear validation issues owned by this validation proc.
    -- Do NOT delete staging-discovered blockers such as
    -- DuplicateSourceGuid/DuplicateTargetGuid/DuplicateTargetKey/UnresolvedReference.
    DELETE FROM SMigration.Metadata_ValidationIssues
    WHERE RunGuid = @RunGuid
      AND IssueCode IN
      (
          N'RunNotFound',
          N'NoSelectedRows',
          N'DuplicateStagedRow',
          N'UnsupportedApplyHandler',
          N'GridViewColumnMissingFromQuery',
          N'SelectedRowParentNotSelected',
          N'UnselectedActionableRows',
          N'DuplicateQueryParameterName',
          N'QueryParameterMappingMismatch',
          N'QueryObjectMissingInTarget',
          N'HobtObjectMissingInTarget',
          N'PropertyColumnMissingInTarget'
      );

    IF NOT EXISTS
    (
        SELECT 1
        FROM SMigration.Metadata_Run AS r
        WHERE r.Guid = @RunGuid
          AND r.RowStatus NOT IN (0,254)
    )
    BEGIN
        INSERT INTO SMigration.Metadata_ValidationIssues
        (
            Guid,
            RowStatus,
            RunGuid,
            RegistryGuid,
            SourceRowGuid,
            Severity,
            IssueCode,
            IssueMessage,
            DetailsJson,
            CreatedOnUtc
        )
        SELECT
            NEWID(),
            1,
            @RunGuid,
            NULL,
            NULL,
            N'Fail',
            N'RunNotFound',
            N'Metadata migration run does not exist or is inactive.',
            N'{}',
            SYSUTCDATETIME();
    END;

    IF EXISTS
    (
        SELECT 1
        FROM SMigration.Metadata_Run AS r
        WHERE r.Guid = @RunGuid
          AND r.RowStatus NOT IN (0,254)
    )
       AND NOT EXISTS (SELECT 1 FROM #MetadataSelectedValidationRows)
    BEGIN
        INSERT INTO SMigration.Metadata_ValidationIssues
        (
            Guid,
            RowStatus,
            RunGuid,
            RegistryGuid,
            SourceRowGuid,
            Severity,
            IssueCode,
            IssueMessage,
            DetailsJson,
            CreatedOnUtc
        )
        SELECT
            NEWID(),
            1,
            @RunGuid,
            NULL,
            NULL,
            N'Fail',
            N'NoSelectedRows',
            N'No metadata rows are selected. Select at least one non-ignored Insert or Update row before validation.',
            N'{}',
            SYSUTCDATETIME();
    END;

    INSERT INTO SMigration.Metadata_ValidationIssues
    (
        Guid,
        RowStatus,
        RunGuid,
        RegistryGuid,
        SourceRowGuid,
        Severity,
        IssueCode,
        IssueMessage,
        DetailsJson,
        CreatedOnUtc
    )
    SELECT
        NEWID(),
        1,
        @RunGuid,
        sr.RegistryGuid,
        sr.SourceRowGuid,
        N'Fail',
        N'DuplicateStagedRow',
        N'The staged run contains duplicate rows for the same table and source row Guid.',
        CONCAT(N'{"SourceRowGuid":"', CONVERT(NVARCHAR(36), sr.SourceRowGuid), N'"}'),
        SYSUTCDATETIME()
    FROM SMigration.Metadata_StagedRows AS sr
    INNER JOIN #MetadataSelectedValidationRows AS selected
        ON selected.RegistryGuid = sr.RegistryGuid
       AND selected.SourceRowGuid = sr.SourceRowGuid
    WHERE sr.RunGuid = @RunGuid
      AND sr.RowStatus NOT IN (0,254)
    GROUP BY
        sr.RegistryGuid,
        sr.SourceRowGuid
    HAVING COUNT_BIG(1) > 1;

    /*
        Staging can discover metadata tables dynamically from EntityTypes, while
        MetadataApply_Run intentionally uses explicit, reviewed handlers. Fail
        closed when an actionable staged table has no apply handler so a run
        cannot report success while silently leaving metadata unapplied.
    */
    INSERT INTO SMigration.Metadata_ValidationIssues
    (
        Guid,
        RowStatus,
        RunGuid,
        RegistryGuid,
        SourceRowGuid,
        Severity,
        IssueCode,
        IssueMessage,
        DetailsJson,
        CreatedOnUtc
    )
    SELECT
        NEWID(),
        1,
        @RunGuid,
        sr.RegistryGuid,
        NULL,
        N'Fail',
        N'UnsupportedApplyHandler',
        CONCAT
        (
            N'No controlled metadata apply handler exists for ',
            tr.SchemaName,
            N'.',
            tr.TableName,
            N'.'
        ),
        CONCAT
        (
            N'{"SchemaName":"',
            STRING_ESCAPE(tr.SchemaName, 'json'),
            N'","TableName":"',
            STRING_ESCAPE(tr.TableName, 'json'),
            N'"}'
        ),
        SYSUTCDATETIME()
    FROM SMigration.Metadata_StagedRows AS sr
    INNER JOIN SMigration.Metadata_TableRegistry AS tr
        ON tr.Guid = sr.RegistryGuid
       AND tr.RowStatus NOT IN (0,254)
    INNER JOIN SMigration.Metadata_Run AS run
        ON run.Guid = sr.RunGuid
       AND run.RowStatus NOT IN (0,254)
    INNER JOIN #MetadataSelectedValidationRows AS selected
        ON selected.RegistryGuid = sr.RegistryGuid
       AND selected.SourceRowGuid = sr.SourceRowGuid
    WHERE sr.RunGuid = @RunGuid
      AND sr.RowStatus NOT IN (0,254)
      AND sr.DifferenceType IN (N'Insert', N'Update')
      AND NOT EXISTS
      (
          SELECT 1
          FROM SMigration.Metadata_IgnoredRecords AS ignored
          WHERE ignored.DatabaseName = run.TargetDatabaseName
            AND ignored.RegistryGuid = sr.RegistryGuid
            AND ignored.SourceRowGuid = sr.SourceRowGuid
            AND ignored.RowStatus NOT IN (0,254)
      )
      AND NOT EXISTS
      (
          SELECT 1
          FROM SMigration.Metadata_IdentityMapOverrides AS identityOverride
          WHERE identityOverride.DatabaseName = run.TargetDatabaseName
            AND identityOverride.RegistryGuid = sr.RegistryGuid
            AND identityOverride.SourceRowGuid = sr.SourceRowGuid
            AND identityOverride.RowStatus NOT IN (0,254)
      )
      AND NOT
      (
          (tr.SchemaName = N'SCore' AND tr.TableName IN
          (
              N'LanguageLabels',
              N'LanguageLabelTranslations',
              N'EntityDataTypes',
              N'EntityTypes',
              N'EntityHobts',
              N'EntityPropertyGroups',
              N'EntityQueries',
              N'EntityProperties',
              N'EntityQueryParameters',
              N'EntityPropertyDependants'
          ))
          OR
          (tr.SchemaName = N'SUserInterface' AND tr.TableName IN
          (
              N'Icons',
              N'DropDownListDefinitions',
              N'GridDefinitions',
              N'GridViewDefinitions',
              N'GridViewColumnDefinitions'
          ))
          OR
          (tr.SchemaName = N'SJob' AND tr.TableName IN
          (
              N'MilestoneTypes'
          ))
      )
    GROUP BY
        sr.RegistryGuid,
        tr.SchemaName,
        tr.TableName;

    /*
        CYB-564: Apply only processes selected rows, but resolves a child's foreign key through
        every staged row. A selected child whose parent is a new (Insert) row that will not be
        applied - not selected, or ignored - resolves to the parent's source Guid, which does not
        exist in the target, and fails at Apply with a raw NOT NULL error (seen live: HoBT
        SJob.FeeAmendmentChase selected without its new EntityType 'Fee Amendment Chase').
        Fail here instead, naming both rows. Declared single-column foreign keys between
        registered tables are followed, the same set MetadataStage_NormaliseDifferences uses.
        A parent with an Identity Map override, or staged as Update/NoChange, already exists in
        the target and is fine. MetadataApply_Run repeats this check before writing anything.
    */
    ;WITH RegisteredForeignKeys AS
    (
        SELECT
            childTr.Guid AS ChildRegistryGuid,
            childTr.SchemaName AS ChildSchemaName,
            childTr.TableName AS ChildTableName,
            pc.name AS ColumnName,
            refTr.Guid AS RefRegistryGuid,
            refTr.SchemaName AS RefSchemaName,
            refTr.TableName AS RefTableName
        FROM SMigration.Metadata_TableRegistry AS childTr
        INNER JOIN sys.foreign_key_columns AS fkc
            ON fkc.parent_object_id = OBJECT_ID(QUOTENAME(childTr.SchemaName) + N'.' + QUOTENAME(childTr.TableName))
        INNER JOIN sys.columns AS pc
            ON pc.object_id = fkc.parent_object_id
           AND pc.column_id = fkc.parent_column_id
        INNER JOIN sys.tables AS rt
            ON rt.object_id = fkc.referenced_object_id
        INNER JOIN sys.schemas AS rs
            ON rs.schema_id = rt.schema_id
        INNER JOIN sys.columns AS rc
            ON rc.object_id = fkc.referenced_object_id
           AND rc.column_id = fkc.referenced_column_id
        INNER JOIN SMigration.Metadata_TableRegistry AS refTr
            ON refTr.SchemaName = rs.name
           AND refTr.TableName = rt.name
           AND refTr.RowStatus NOT IN (0,254)
           AND refTr.IsEnabled = 1
        WHERE childTr.RowStatus NOT IN (0,254)
          AND childTr.IsEnabled = 1
          AND pc.name <> N'RowStatus'
          AND rc.name = refTr.PrimaryKeyColumnName
          AND NOT EXISTS
          (
              SELECT 1
              FROM sys.foreign_key_columns AS otherColumn
              WHERE otherColumn.constraint_object_id = fkc.constraint_object_id
                AND otherColumn.constraint_column_id <> fkc.constraint_column_id
          )
    )
    SELECT
        fk.ChildRegistryGuid,
        fk.ChildSchemaName,
        fk.ChildTableName,
        fk.ColumnName,
        fk.RefRegistryGuid,
        fk.RefSchemaName,
        fk.RefTableName,
        child.SourceRowGuid AS ChildRowGuid,
        JSON_VALUE(child.SourcePayloadJson, N'$.Name') AS ChildName,
        -- JSON_VALUE returns at most 4000 characters, so this cannot raise 8152.
        TRY_CONVERT(BIGINT, JSON_VALUE(child.SourcePayloadJson, N'$."' + fk.ColumnName + N'"')) AS ParentSourceRowId
    INTO #SelectedParentReferences
    FROM SMigration.Metadata_StagedRows AS child
    INNER JOIN SMigration.Metadata_RunSelections AS childSelection
        ON childSelection.RunGuid = child.RunGuid
       AND childSelection.RegistryGuid = child.RegistryGuid
       AND childSelection.SourceRowGuid = child.SourceRowGuid
       AND childSelection.RowStatus NOT IN (0,254)
    INNER JOIN RegisteredForeignKeys AS fk
        ON fk.ChildRegistryGuid = child.RegistryGuid
    WHERE child.RunGuid = @RunGuid
      AND child.RowStatus NOT IN (0,254)
      AND child.DifferenceType IN (N'Insert', N'Update')
      AND NOT EXISTS
      (
          SELECT 1
          FROM SMigration.Metadata_IgnoredRecords AS childIgnored
          WHERE childIgnored.DatabaseName = @TargetDatabaseName
            AND childIgnored.RegistryGuid = child.RegistryGuid
            AND childIgnored.SourceRowGuid = child.SourceRowGuid
            AND childIgnored.RowStatus NOT IN (0,254)
      );

    -- Materialised above rather than joined on JSON_VALUE directly: a join on a payload
    -- expression lets the optimiser re-parse payloads for every candidate parent row.
    INSERT INTO SMigration.Metadata_ValidationIssues
    (
        Guid,
        RowStatus,
        RunGuid,
        RegistryGuid,
        SourceRowGuid,
        Severity,
        IssueCode,
        IssueMessage,
        DetailsJson,
        CreatedOnUtc
    )
    SELECT
        NEWID(),
        1,
        @RunGuid,
        missing.ChildRegistryGuid,
        missing.ChildRowGuid,
        N'Fail',
        N'SelectedRowParentNotSelected',
        LEFT(CONCAT
        (
            N'Selected ', missing.ChildSchemaName, N'.', missing.ChildTableName, N' row ',
            COALESCE(N'''' + missing.ChildName + N''' ', N''), CONVERT(NVARCHAR(36), missing.ChildRowGuid),
            N' references new ', missing.RefSchemaName, N'.', missing.RefTableName, N' row ',
            COALESCE(N'''' + missing.ParentName + N''' ', N''), CONVERT(NVARCHAR(36), missing.ParentRowGuid),
            N' (', missing.ColumnName, N'), which is ',
            CASE WHEN missing.ParentIsIgnored = 1 THEN N'ignored' ELSE N'not selected' END,
            N' and does not exist in the target. Select the parent row too, or deselect this row.'
        ), 2000),
        CONCAT
        (
            N'{"ForeignKeyColumn":"', STRING_ESCAPE(missing.ColumnName, 'json'),
            N'","ReferencedSchemaName":"', STRING_ESCAPE(missing.RefSchemaName, 'json'),
            N'","ReferencedTableName":"', STRING_ESCAPE(missing.RefTableName, 'json'),
            N'","ReferencedGuid":"', CONVERT(NVARCHAR(36), missing.ParentRowGuid), N'"}'
        ),
        SYSUTCDATETIME()
    FROM
    (
        SELECT DISTINCT
            spr.ChildRegistryGuid,
            spr.ChildSchemaName,
            spr.ChildTableName,
            spr.ColumnName,
            spr.RefSchemaName,
            spr.RefTableName,
            spr.ChildRowGuid,
            spr.ChildName,
            parent.SourceRowGuid AS ParentRowGuid,
            JSON_VALUE(parent.SourcePayloadJson, N'$.Name') AS ParentName,
            CASE WHEN parentIgnored.SourceRowGuid IS NOT NULL THEN 1 ELSE 0 END AS ParentIsIgnored
        FROM #SelectedParentReferences AS spr
        INNER JOIN SMigration.Metadata_StagedRows AS parent
            ON parent.RunGuid = @RunGuid
           AND parent.RegistryGuid = spr.RefRegistryGuid
           AND parent.SourceRowId = spr.ParentSourceRowId
           AND parent.RowStatus NOT IN (0,254)
        LEFT JOIN SMigration.Metadata_IgnoredRecords AS parentIgnored
            ON parentIgnored.DatabaseName = @TargetDatabaseName
           AND parentIgnored.RegistryGuid = parent.RegistryGuid
           AND parentIgnored.SourceRowGuid = parent.SourceRowGuid
           AND parentIgnored.RowStatus NOT IN (0,254)
        WHERE spr.ParentSourceRowId IS NOT NULL
          AND parent.SourceRowGuid <> spr.ChildRowGuid
          AND parent.DifferenceType = N'Insert'
          AND NOT EXISTS
          (
              SELECT 1
              FROM SMigration.Metadata_IdentityMapOverrides AS parentOverride
              WHERE parentOverride.DatabaseName = @TargetDatabaseName
                AND parentOverride.RegistryGuid = parent.RegistryGuid
                AND parentOverride.SourceRowGuid = parent.SourceRowGuid
                AND parentOverride.RowStatus NOT IN (0,254)
          )
          AND
          (
              parentIgnored.SourceRowGuid IS NOT NULL
              OR NOT EXISTS
              (
                  SELECT 1
                  FROM SMigration.Metadata_RunSelections AS parentSelection
                  WHERE parentSelection.RunGuid = parent.RunGuid
                    AND parentSelection.RegistryGuid = parent.RegistryGuid
                    AND parentSelection.SourceRowGuid = parent.SourceRowGuid
                    AND parentSelection.RowStatus NOT IN (0,254)
              )
          )
    ) AS missing;

    /*
        A GridViewDefinitions row's SqlQuery is free text, hand-maintained independently of its
        child GridViewColumnDefinitions rows - nothing enforces that every active column Name is
        actually projected by the query. The mismatch is invisible until a user opens the grid:
        CoreService's GridDataList reads each column purely by name
        (reader.GetOrdinal(column.Name) in libs/Concursus.EF/UserInterface.cs), so a column
        definition with no matching column in the query throws at render time instead of here.

        Compare, for every (GridViewDefinitions, GridViewColumnDefinitions) pair where at least one
        side is part of this run's selection, the grid's current source SqlQuery text against each
        active source column's Name. This is a text-presence heuristic (word-boundary search), not
        a real result-set comparison - no dynamic SQL or cross-database context switch is
        attempted. It will not catch a column aliased under a different name, but it catches the
        actual failure mode seen in production: a column definition added with nothing in the
        query selecting it at all. Column names containing SQL LIKE wildcard characters
        (%, _, [, ]) are not expected in this codebase and are not specially escaped here.

        A query whose SELECT list is (optionally alias-/schema-qualified) "*" - e.g.
        "SELECT * FROM ..." or "SELECT root_hobt.* FROM ..." - projects every underlying column
        dynamically; no column name is ever spelled out in the query text at all, so the
        word-boundary search above can never find one and would otherwise flag every single
        active column of every select-star grid as missing, regardless of whether the grid
        actually works. Confirmed live in CymBuild_DEV: SUserInterface.GridViewDefinitions
        'ENGJOBSFINANCE' and 'WORKFLOWSTATUS' are real, working select-star grids, not evidence
        of a genuine query defect. Detect a bare '*' in the portion of the query before the first
        standalone FROM keyword (so a '*' used as multiplication in a later WHERE/JOIN condition
        is never mistaken for a projection) and skip the check entirely for that grid.
    */
    DECLARE @GridViewDefinitionsRegistryGuid UNIQUEIDENTIFIER;
    DECLARE @GridViewColumnDefinitionsRegistryGuid UNIQUEIDENTIFIER;

    SELECT @GridViewDefinitionsRegistryGuid = tr.Guid
    FROM SMigration.Metadata_TableRegistry AS tr
    WHERE tr.SchemaName = N'SUserInterface'
      AND tr.TableName = N'GridViewDefinitions'
      AND tr.RowStatus NOT IN (0,254);

    SELECT @GridViewColumnDefinitionsRegistryGuid = tr.Guid
    FROM SMigration.Metadata_TableRegistry AS tr
    WHERE tr.SchemaName = N'SUserInterface'
      AND tr.TableName = N'GridViewColumnDefinitions'
      AND tr.RowStatus NOT IN (0,254);

    IF @GridViewDefinitionsRegistryGuid IS NOT NULL AND @GridViewColumnDefinitionsRegistryGuid IS NOT NULL
    BEGIN
        CREATE TABLE #GridViewDefinitionSource
        (
            SourceRowGuid UNIQUEIDENTIFIER NOT NULL PRIMARY KEY,
            SourceRowId BIGINT NOT NULL,
            Code NVARCHAR(20) NOT NULL,
            SqlQuery NVARCHAR(MAX) NOT NULL
        );

        -- OPENJSON's WITH clause (unlike JSON_VALUE) does not truncate NVARCHAR(MAX) at 4000
        -- characters, which matters here since SqlQuery routinely exceeds that.
        INSERT INTO #GridViewDefinitionSource
        (
            SourceRowGuid,
            SourceRowId,
            Code,
            SqlQuery
        )
        SELECT
            sr.SourceRowGuid,
            sr.SourceRowId,
            j.Code,
            j.SqlQuery
        FROM SMigration.Metadata_StagedRows AS sr
        CROSS APPLY OPENJSON(sr.SourcePayloadJson)
            WITH
            (
                Code NVARCHAR(20) '$.Code',
                SqlQuery NVARCHAR(MAX) '$.SqlQuery'
            ) AS j
        WHERE sr.RunGuid = @RunGuid
          AND sr.RowStatus NOT IN (0,254)
          AND sr.RegistryGuid = @GridViewDefinitionsRegistryGuid
          AND sr.SourceRowId IS NOT NULL;

        CREATE TABLE #GridViewColumnSource
        (
            SourceRowGuid UNIQUEIDENTIFIER NOT NULL PRIMARY KEY,
            GridViewDefinitionId BIGINT NOT NULL,
            Name NVARCHAR(100) NOT NULL
        );

        INSERT INTO #GridViewColumnSource
        (
            SourceRowGuid,
            GridViewDefinitionId,
            Name
        )
        SELECT
            sr.SourceRowGuid,
            j.GridViewDefinitionId,
            j.Name
        FROM SMigration.Metadata_StagedRows AS sr
        CROSS APPLY OPENJSON(sr.SourcePayloadJson)
            WITH
            (
                GridViewDefinitionId BIGINT '$.GridViewDefinitionId',
                Name NVARCHAR(100) '$.Name'
            ) AS j
        WHERE sr.RunGuid = @RunGuid
          AND sr.RowStatus NOT IN (0,254)
          AND sr.RegistryGuid = @GridViewColumnDefinitionsRegistryGuid
          AND NULLIF(j.Name, N'') IS NOT NULL;

        -- Anchor each issue to whichever side of the pair is actually part of this run's
        -- selection, so it is picked up by the FailCount/summary filter below regardless of
        -- whether the grid's query or the column's definition is what changed in this run.
        INSERT INTO SMigration.Metadata_ValidationIssues
        (
            Guid,
            RowStatus,
            RunGuid,
            RegistryGuid,
            SourceRowGuid,
            Severity,
            IssueCode,
            IssueMessage,
            DetailsJson,
            CreatedOnUtc
        )
        SELECT
            NEWID(),
            1,
            @RunGuid,
            CASE WHEN colSelected.SourceRowGuid IS NOT NULL THEN @GridViewColumnDefinitionsRegistryGuid ELSE @GridViewDefinitionsRegistryGuid END,
            CASE WHEN colSelected.SourceRowGuid IS NOT NULL THEN col.SourceRowGuid ELSE grid.SourceRowGuid END,
            N'Fail',
            N'GridViewColumnMissingFromQuery',
            CONCAT
            (
                N'GridViewColumnDefinitions.Name ''', col.Name,
                N''' has no matching column in GridViewDefinitions ''', grid.Code,
                N''' SqlQuery. The grid will fail at render time (reader.GetOrdinal) unless the query is updated to project a same-named column.'
            ),
            CONCAT
            (
                N'{"GridViewDefinitionCode":"', STRING_ESCAPE(grid.Code, 'json'),
                N'","ColumnName":"', STRING_ESCAPE(col.Name, 'json'), N'"}'
            ),
            SYSUTCDATETIME()
        FROM #GridViewColumnSource AS col
        INNER JOIN #GridViewDefinitionSource AS grid
            ON grid.SourceRowId = col.GridViewDefinitionId
        LEFT JOIN #MetadataSelectedValidationRows AS colSelected
            ON colSelected.RegistryGuid = @GridViewColumnDefinitionsRegistryGuid
           AND colSelected.SourceRowGuid = col.SourceRowGuid
        LEFT JOIN #MetadataSelectedValidationRows AS gridSelected
            ON gridSelected.RegistryGuid = @GridViewDefinitionsRegistryGuid
           AND gridSelected.SourceRowGuid = grid.SourceRowGuid
        CROSS APPLY
        (
            SELECT UpperQuery = N' ' + UPPER(grid.SqlQuery) + N' '
        ) AS uq
        CROSS APPLY
        (
            SELECT FromPosition = PATINDEX(N'%[^A-Za-z0-9_]FROM[^A-Za-z0-9_]%', uq.UpperQuery)
        ) AS fp
        CROSS APPLY
        (
            SELECT SelectListText = LEFT(uq.UpperQuery, CASE WHEN fp.FromPosition = 0 THEN LEN(uq.UpperQuery) ELSE fp.FromPosition END)
        ) AS sl
        WHERE
        (
            colSelected.SourceRowGuid IS NOT NULL
            OR gridSelected.SourceRowGuid IS NOT NULL
        )
        AND PATINDEX
        (
            N'%[^A-Za-z0-9_]' + col.Name + N'[^A-Za-z0-9_]%',
            N' ' + grid.SqlQuery + N' '
        ) = 0
        AND PATINDEX(N'%[^A-Za-z0-9_]*[^A-Za-z0-9_]%', sl.SelectListText) = 0;

        DROP TABLE #GridViewColumnSource;
        DROP TABLE #GridViewDefinitionSource;
    END;

    /*
        CYB-574: Apply only writes selected rows. On QA2 every Insert was selected but almost no
        Updates, so changed queries (Fee Amendment Validate, Grid View Definitions Read,
        QuotesUpsert...) were staged correctly, validated clean and silently never applied.
        Warn once per table for staged Insert/Update rows that are neither selected nor ignored.
    */
    INSERT INTO SMigration.Metadata_ValidationIssues
    (
        Guid,
        RowStatus,
        RunGuid,
        RegistryGuid,
        SourceRowGuid,
        Severity,
        IssueCode,
        IssueMessage,
        DetailsJson,
        CreatedOnUtc
    )
    SELECT
        NEWID(),
        1,
        @RunGuid,
        unselected.RegistryGuid,
        NULL,
        N'Warn',
        N'UnselectedActionableRows',
        CONCAT
        (
            unselected.SchemaName, N'.', unselected.TableName, N' has ',
            unselected.InsertCount, N' Insert and ', unselected.UpdateCount,
            N' Update row(s) staged but not selected. They will not be applied. Select or ignore them.'
        ),
        CONCAT(N'{"insertCount":', unselected.InsertCount, N',"updateCount":', unselected.UpdateCount, N'}'),
        SYSUTCDATETIME()
    FROM
    (
        SELECT
            sr.RegistryGuid,
            tr.SchemaName,
            tr.TableName,
            SUM(CASE WHEN sr.DifferenceType = N'Insert' THEN 1 ELSE 0 END) AS InsertCount,
            SUM(CASE WHEN sr.DifferenceType = N'Update' THEN 1 ELSE 0 END) AS UpdateCount
        FROM SMigration.Metadata_StagedRows AS sr
        INNER JOIN SMigration.Metadata_TableRegistry AS tr
            ON tr.Guid = sr.RegistryGuid
           AND tr.RowStatus NOT IN (0,254)
        WHERE sr.RunGuid = @RunGuid
          AND sr.RowStatus NOT IN (0,254)
          AND sr.DifferenceType IN (N'Insert', N'Update')
          AND NOT EXISTS
          (
              SELECT 1
              FROM SMigration.Metadata_RunSelections AS selection
              WHERE selection.RunGuid = sr.RunGuid
                AND selection.RegistryGuid = sr.RegistryGuid
                AND selection.SourceRowGuid = sr.SourceRowGuid
                AND selection.RowStatus NOT IN (0,254)
          )
          AND NOT EXISTS
          (
              SELECT 1
              FROM SMigration.Metadata_IgnoredRecords AS ignored
              WHERE ignored.DatabaseName = @TargetDatabaseName
                AND ignored.RegistryGuid = sr.RegistryGuid
                AND ignored.SourceRowGuid = sr.SourceRowGuid
                AND ignored.RowStatus NOT IN (0,254)
          )
        GROUP BY
            sr.RegistryGuid,
            tr.SchemaName,
            tr.TableName
    ) AS unselected;

    /*
        CYB-574: a selected query whose function, procedure, table or view does not exist in the
        target is applied anyway and only fails when used (seen on QA2: 'Invoice Requests
        Validate' became the default validation for Invoice Requests while
        SFin.tvf_InvoiceRequestsValidate existed only in DEV, so every save failed). Schema
        must reach the target before the metadata that calls it. Names may be bracketed,
        and a name with a stray tab or line break (seen in DEV: EntityQueries 'WIP Notes Upsert'
        with SchemaName 'SFin' + CHAR(10)) must not fail the lookup, so tab/CR/LF are removed
        before the trim in all three existence checks below.
    */
    INSERT INTO SMigration.Metadata_ValidationIssues
    (
        Guid,
        RowStatus,
        RunGuid,
        RegistryGuid,
        SourceRowGuid,
        Severity,
        IssueCode,
        IssueMessage,
        DetailsJson,
        CreatedOnUtc
    )
    SELECT
        NEWID(),
        1,
        @RunGuid,
        sr.RegistryGuid,
        sr.SourceRowGuid,
        N'Fail',
        N'QueryObjectMissingInTarget',
        LEFT(CONCAT
        (
            N'Selected query ''', JSON_VALUE(sr.SourcePayloadJson, N'$.Name'), N''' uses ',
            obj.SchemaName, N'.', obj.ObjectName,
            N', which does not exist in the target. Deploy the schema change first, or deselect or ignore this row.'
        ), 4000),
        CONCAT(N'{"schemaName":"', STRING_ESCAPE(obj.SchemaName, 'json'), N'","objectName":"', STRING_ESCAPE(obj.ObjectName, 'json'), N'"}'),
        SYSUTCDATETIME()
    FROM SMigration.Metadata_StagedRows AS sr
    INNER JOIN #MetadataSelectedValidationRows AS selected
        ON selected.RegistryGuid = sr.RegistryGuid
       AND selected.SourceRowGuid = sr.SourceRowGuid
    INNER JOIN SMigration.Metadata_TableRegistry AS tr
        ON tr.Guid = sr.RegistryGuid
       AND tr.RowStatus NOT IN (0,254)
    CROSS APPLY
    (
        SELECT
            SchemaName = REPLACE(REPLACE(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(ISNULL(JSON_VALUE(sr.SourcePayloadJson, N'$.SchemaName'), N''), NCHAR(9), N''), NCHAR(10), N''), NCHAR(13), N''))), N'[', N''), N']', N''),
            ObjectName = REPLACE(REPLACE(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(ISNULL(JSON_VALUE(sr.SourcePayloadJson, N'$.ObjectName'), N''), NCHAR(9), N''), NCHAR(10), N''), NCHAR(13), N''))), N'[', N''), N']', N'')
    ) AS obj
    WHERE sr.RunGuid = @RunGuid
      AND sr.RowStatus NOT IN (0,254)
      AND sr.DifferenceType IN (N'Insert', N'Update')
      AND tr.SchemaName = N'SCore'
      AND tr.TableName = N'EntityQueries'
      AND ISNULL(TRY_CONVERT(TINYINT, JSON_VALUE(sr.SourcePayloadJson, N'$.RowStatus')), 1) NOT IN (0,254)
      AND obj.SchemaName <> N''
      AND obj.ObjectName <> N''
      AND OBJECT_ID(QUOTENAME(obj.SchemaName) + N'.' + QUOTENAME(obj.ObjectName)) IS NULL;

    /*
        CYB-574: same gap for the data shape. QA2 run 4 brought DEV-only Invoice Request WIP
        metadata - a HoBT on SFin.InvoiceRequestWIPNotes and IsWIP/WIPReason properties on
        SFin.InvoiceRequests - with no table or columns in the target, which broke the Invoice
        Request screens. Fail a selected HoBT whose object is missing. Warn (not Fail) for a
        selected non-virtual property whose column is missing from its HoBT's object: some
        properties are supplied by the read query instead (SSop.Quotes JobTypeGuid, PropertyId).
    */
    INSERT INTO SMigration.Metadata_ValidationIssues
    (
        Guid,
        RowStatus,
        RunGuid,
        RegistryGuid,
        SourceRowGuid,
        Severity,
        IssueCode,
        IssueMessage,
        DetailsJson,
        CreatedOnUtc
    )
    SELECT
        NEWID(),
        1,
        @RunGuid,
        sr.RegistryGuid,
        sr.SourceRowGuid,
        N'Fail',
        N'HobtObjectMissingInTarget',
        LEFT(CONCAT
        (
            N'Selected HoBT ', obj.SchemaName, N'.', obj.ObjectName,
            N' does not exist in the target. Deploy the schema change first, or deselect or ignore this row.'
        ), 4000),
        CONCAT(N'{"schemaName":"', STRING_ESCAPE(obj.SchemaName, 'json'), N'","objectName":"', STRING_ESCAPE(obj.ObjectName, 'json'), N'"}'),
        SYSUTCDATETIME()
    FROM SMigration.Metadata_StagedRows AS sr
    INNER JOIN #MetadataSelectedValidationRows AS selected
        ON selected.RegistryGuid = sr.RegistryGuid
       AND selected.SourceRowGuid = sr.SourceRowGuid
    INNER JOIN SMigration.Metadata_TableRegistry AS tr
        ON tr.Guid = sr.RegistryGuid
       AND tr.RowStatus NOT IN (0,254)
    CROSS APPLY
    (
        SELECT
            SchemaName = REPLACE(REPLACE(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(ISNULL(JSON_VALUE(sr.SourcePayloadJson, N'$.SchemaName'), N''), NCHAR(9), N''), NCHAR(10), N''), NCHAR(13), N''))), N'[', N''), N']', N''),
            ObjectName = REPLACE(REPLACE(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(ISNULL(JSON_VALUE(sr.SourcePayloadJson, N'$.ObjectName'), N''), NCHAR(9), N''), NCHAR(10), N''), NCHAR(13), N''))), N'[', N''), N']', N'')
    ) AS obj
    WHERE sr.RunGuid = @RunGuid
      AND sr.RowStatus NOT IN (0,254)
      AND sr.DifferenceType IN (N'Insert', N'Update')
      AND tr.SchemaName = N'SCore'
      AND tr.TableName = N'EntityHobts'
      AND ISNULL(TRY_CONVERT(TINYINT, JSON_VALUE(sr.SourcePayloadJson, N'$.RowStatus')), 1) NOT IN (0,254)
      AND obj.SchemaName <> N''
      AND obj.ObjectName <> N''
      AND OBJECT_ID(QUOTENAME(obj.SchemaName) + N'.' + QUOTENAME(obj.ObjectName)) IS NULL;

    INSERT INTO SMigration.Metadata_ValidationIssues
    (
        Guid,
        RowStatus,
        RunGuid,
        RegistryGuid,
        SourceRowGuid,
        Severity,
        IssueCode,
        IssueMessage,
        DetailsJson,
        CreatedOnUtc
    )
    SELECT
        NEWID(),
        1,
        @RunGuid,
        sr.RegistryGuid,
        sr.SourceRowGuid,
        N'Warn',
        N'PropertyColumnMissingInTarget',
        LEFT(CONCAT
        (
            N'Selected property ', prop.PropertyName, N' has no column in ', obj.SchemaName, N'.', obj.ObjectName,
            N' in the target. Deploy the schema change first, unless the read query supplies it.'
        ), 4000),
        CONCAT(N'{"schemaName":"', STRING_ESCAPE(obj.SchemaName, 'json'), N'","objectName":"', STRING_ESCAPE(obj.ObjectName, 'json'), N'","columnName":"', STRING_ESCAPE(prop.PropertyName, 'json'), N'"}'),
        SYSUTCDATETIME()
    FROM SMigration.Metadata_StagedRows AS sr
    INNER JOIN #MetadataSelectedValidationRows AS selected
        ON selected.RegistryGuid = sr.RegistryGuid
       AND selected.SourceRowGuid = sr.SourceRowGuid
    INNER JOIN SMigration.Metadata_TableRegistry AS tr
        ON tr.Guid = sr.RegistryGuid
       AND tr.RowStatus NOT IN (0,254)
    CROSS APPLY
    (
        SELECT
            PropertyName = JSON_VALUE(sr.SourcePayloadJson, N'$.Name'),
            -- JSON_VALUE returns at most 4000 characters, so this cannot raise 8152.
            SourceHobtId = TRY_CONVERT(BIGINT, COALESCE
            (
                JSON_VALUE(sr.SourcePayloadJson, N'$.EntityHoBTID'),
                JSON_VALUE(sr.SourcePayloadJson, N'$.EntityHoBTId'),
                JSON_VALUE(sr.SourcePayloadJson, N'$.EntityHobtID'),
                JSON_VALUE(sr.SourcePayloadJson, N'$.EntityHobtId')
            ))
    ) AS prop
    INNER JOIN SMigration.Metadata_TableRegistry AS hobtTr
        ON hobtTr.SchemaName = N'SCore'
       AND hobtTr.TableName = N'EntityHobts'
       AND hobtTr.RowStatus NOT IN (0,254)
    INNER JOIN SMigration.Metadata_StagedRows AS hobtRow
        ON hobtRow.RunGuid = sr.RunGuid
       AND hobtRow.RegistryGuid = hobtTr.Guid
       AND hobtRow.SourceRowId = prop.SourceHobtId
       AND hobtRow.RowStatus NOT IN (0,254)
    CROSS APPLY
    (
        SELECT
            SchemaName = REPLACE(REPLACE(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(ISNULL(JSON_VALUE(hobtRow.SourcePayloadJson, N'$.SchemaName'), N''), NCHAR(9), N''), NCHAR(10), N''), NCHAR(13), N''))), N'[', N''), N']', N''),
            ObjectName = REPLACE(REPLACE(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(ISNULL(JSON_VALUE(hobtRow.SourcePayloadJson, N'$.ObjectName'), N''), NCHAR(9), N''), NCHAR(10), N''), NCHAR(13), N''))), N'[', N''), N']', N'')
    ) AS obj
    WHERE sr.RunGuid = @RunGuid
      AND sr.RowStatus NOT IN (0,254)
      AND sr.DifferenceType IN (N'Insert', N'Update')
      AND tr.SchemaName = N'SCore'
      AND tr.TableName = N'EntityProperties'
      AND ISNULL(TRY_CONVERT(TINYINT, JSON_VALUE(sr.SourcePayloadJson, N'$.RowStatus')), 1) NOT IN (0,254)
      AND ISNULL(TRY_CONVERT(BIT, JSON_VALUE(sr.SourcePayloadJson, N'$.IsVirtual')), 0) = 0
      AND ISNULL(prop.PropertyName, N'') <> N''
      AND obj.SchemaName <> N''
      AND obj.ObjectName <> N''
      AND NOT EXISTS
      (
          SELECT 1
          FROM sys.columns AS c
          WHERE c.object_id = OBJECT_ID(QUOTENAME(obj.SchemaName) + N'.' + QUOTENAME(obj.ObjectName))
            AND c.name = prop.PropertyName
      );

    /*
        CYB-574: two active parameters with the same name on one query make the generated
        statement declare that variable twice and every call fails ("The variable name '@Guid'
        has already been declared"). This is target state, so it is checked whatever is
        selected; MetadataApply_Run no longer creates it, but existing duplicates need cleaning.
    */
    DECLARE @EntityQueryParametersRegistryGuid UNIQUEIDENTIFIER =
    (
        SELECT TOP (1) tr.Guid
        FROM SMigration.Metadata_TableRegistry AS tr
        WHERE tr.SchemaName = N'SCore'
          AND tr.TableName = N'EntityQueryParameters'
          AND tr.RowStatus NOT IN (0,254)
    );

    IF @EntityQueryParametersRegistryGuid IS NOT NULL
    BEGIN
        INSERT INTO SMigration.Metadata_ValidationIssues
        (
            Guid,
            RowStatus,
            RunGuid,
            RegistryGuid,
            SourceRowGuid,
            Severity,
            IssueCode,
            IssueMessage,
            DetailsJson,
            CreatedOnUtc
        )
        SELECT
            NEWID(),
            1,
            @RunGuid,
            @EntityQueryParametersRegistryGuid,
            duplicate.QueryGuid,
            N'Fail',
            N'DuplicateQueryParameterName',
            LEFT(CONCAT
            (
                N'Target query ''', duplicate.QueryName, N''' has ', duplicate.ParameterCount,
                N' active parameters named ', duplicate.ParameterName,
                N'. Remove the extra row(s) in the target before applying.'
            ), 4000),
            CONCAT(N'{"entityQueryGuid":"', CONVERT(NVARCHAR(36), duplicate.QueryGuid), N'","parameterName":"', STRING_ESCAPE(duplicate.ParameterName, 'json'), N'"}'),
            SYSUTCDATETIME()
        FROM
        (
            SELECT
                q.Guid AS QueryGuid,
                q.Name AS QueryName,
                p.Name AS ParameterName,
                COUNT(1) AS ParameterCount
            FROM SCore.EntityQueryParameters AS p
            INNER JOIN SCore.EntityQueries AS q
                ON q.ID = p.EntityQueryID
               AND q.RowStatus NOT IN (0,254)
            WHERE p.RowStatus NOT IN (0,254)
            GROUP BY
                q.Guid,
                q.Name,
                p.Name
            HAVING COUNT(1) > 1
        ) AS duplicate;

        /*
            CYB-574: a parameter whose mapped property belongs to a different entity type than
            its query AND whose name does not match that property was mapped by a raw ID copied
            from another environment (legacy data-compare scripts), so it points at an unrelated
            property. Both conditions are needed: either alone has legitimate cases.
        */
        INSERT INTO SMigration.Metadata_ValidationIssues
        (
            Guid,
            RowStatus,
            RunGuid,
            RegistryGuid,
            SourceRowGuid,
            Severity,
            IssueCode,
            IssueMessage,
            DetailsJson,
            CreatedOnUtc
        )
        SELECT
            NEWID(),
            1,
            @RunGuid,
            @EntityQueryParametersRegistryGuid,
            p.Guid,
            N'Warn',
            N'QueryParameterMappingMismatch',
            LEFT(CONCAT
            (
                N'Target parameter ', p.Name, N' on query ''', q.Name, N''' maps to property ',
                ep.Name, N' of entity type ''', propertyEntity.Name, N''', not the query''s entity type ''',
                queryEntity.Name, N'''. It was probably mapped by a raw ID from another environment.'
            ), 4000),
            CONCAT(N'{"entityQueryGuid":"', CONVERT(NVARCHAR(36), q.Guid), N'","mappedEntityPropertyGuid":"', CONVERT(NVARCHAR(36), ep.Guid), N'"}'),
            SYSUTCDATETIME()
        FROM SCore.EntityQueryParameters AS p
        INNER JOIN SCore.EntityQueries AS q
            ON q.ID = p.EntityQueryID
           AND q.RowStatus NOT IN (0,254)
        INNER JOIN SCore.EntityProperties AS ep
            ON ep.ID = p.MappedEntityPropertyID
        INNER JOIN SCore.EntityHobts AS h
            ON h.ID = ep.EntityHoBTID
        INNER JOIN SCore.EntityTypes AS propertyEntity
            ON propertyEntity.ID = h.EntityTypeID
        INNER JOIN SCore.EntityTypes AS queryEntity
            ON queryEntity.ID = q.EntityTypeID
        WHERE p.RowStatus NOT IN (0,254)
          AND p.MappedEntityPropertyID > 0
          AND h.EntityTypeID <> q.EntityTypeID
          AND p.Name NOT IN (N'@' + ep.Name, N'@' + ep.Name + N'Guid')
          AND N'@' + ep.Name NOT IN (REPLACE(p.Name, N'Guid', N'ID'), REPLACE(p.Name, N'Guid', N'Id'));
    END;

    UPDATE ignored
    SET
        ignored.LastSeenRunGuid = @RunGuid,
        ignored.LastSeenOnUtc = SYSUTCDATETIME()
    FROM SMigration.Metadata_ValidationIssueIgnores AS ignored
    INNER JOIN SMigration.Metadata_ValidationIssues AS issue
        ON issue.RunGuid = @RunGuid
       AND issue.RegistryGuid = ignored.RegistryGuid
       AND issue.SourceRowGuid = ignored.SourceRowGuid
       AND issue.IssueCode = ignored.IssueCode
       AND issue.RowStatus NOT IN (0,254)
    WHERE ignored.DatabaseName = @TargetDatabaseName
      AND ignored.RowStatus NOT IN (0,254);

    SELECT
        @FailCount = SUM(CASE WHEN vi.Severity = N'Fail' THEN 1 ELSE 0 END),
        @WarnCount = SUM(CASE WHEN vi.Severity = N'Warn' THEN 1 ELSE 0 END),
        @InfoCount = SUM(CASE WHEN vi.Severity = N'Info' THEN 1 ELSE 0 END)
    FROM SMigration.Metadata_ValidationIssues AS vi
    WHERE vi.RunGuid = @RunGuid
      AND vi.RowStatus NOT IN (0,254)
      AND NOT EXISTS
      (
          SELECT 1
          FROM SMigration.Metadata_ValidationIssueIgnores AS ignoredIssue
          WHERE ignoredIssue.DatabaseName = @TargetDatabaseName
            AND ignoredIssue.RegistryGuid = vi.RegistryGuid
            AND ignoredIssue.SourceRowGuid = vi.SourceRowGuid
            AND ignoredIssue.IssueCode = vi.IssueCode
            AND ignoredIssue.RowStatus NOT IN (0,254)
      )
      AND
      (
          vi.IssueCode IN (N'RunNotFound', N'NoSelectedRows', N'DuplicateSourceGuid', N'DuplicateTargetGuid', N'DuplicateTargetKey', N'UnresolvedReference', N'SelectedRowParentNotSelected', N'UnselectedActionableRows', N'DuplicateQueryParameterName', N'QueryParameterMappingMismatch')
          OR EXISTS
          (
              SELECT 1
              FROM #MetadataSelectedValidationRows AS selected
              WHERE selected.RegistryGuid = vi.RegistryGuid
                AND
                (
                    vi.SourceRowGuid IS NULL
                    OR selected.SourceRowGuid = vi.SourceRowGuid
                )
          )
      );

    SET @FailCount = ISNULL(@FailCount, 0);
    SET @WarnCount = ISNULL(@WarnCount, 0);
    SET @InfoCount = ISNULL(@InfoCount, 0);

    UPDATE SMigration.Metadata_Run
    SET
        RunStatus = CASE WHEN @FailCount > 0 THEN N'ValidationFailed' ELSE N'Validated' END,
        ValidatedOnUtc = SYSUTCDATETIME(),
        SummaryJson = CONCAT
        (
            N'{"failCount":',
            CONVERT(NVARCHAR(30), @FailCount),
            N',"warnCount":',
            CONVERT(NVARCHAR(30), @WarnCount),
            N',"infoCount":',
            CONVERT(NVARCHAR(30), @InfoCount),
            N'}'
        )
    WHERE Guid = @RunGuid
      AND RowStatus NOT IN (0,254);
    DECLARE @_StepStatus AS NVARCHAR(15) = (CASE WHEN @FailCount > 0 THEN N'Failed' ELSE N'Succeeded' END)
    EXEC SMigration.MetadataExecutionLog_Add
        @RunGuid = @RunGuid,
        @StepName = N'ValidateRun',
        @StepStatus = @_StepStatus,
        @Message = N'Metadata migration validation completed.',
        @DetailsJson = N'{}';

    COMMIT TRANSACTION;

    SELECT
        @FailCount AS FailCount,
        @WarnCount AS WarnCount,
        @InfoCount AS InfoCount;
END;
GO

