        LEFT JOIN SCrm.Contacts AS officialContact
            ON officialContact.ID = t.OfficialContactId
        LEFT JOIN SCore.Groups AS g
            ON g.ID = t.DefaultSecurityGroupId
        WHERE s.RunGuid = @RunGuid
        ORDER BY s.OrgLevel, s.Name;
        RETURN;
    END;

