/* =========================================================
   Retirement pass (CYB-564)
   A staged Update whose source RowStatus is 254 exists only when the run opted in to
   retirements (MetadataStage_Run @IncludeRetirements) and its same-Guid target row was
   still active. Several handlers above never write RowStatus (LanguageLabelUpsert,
   LanguageLabelTranslationUpsert, EntityHoBTUpsert, DropDownListDefinitionUpsert), so the
   retirement is enforced here, once, for every handled table. It is idempotent: a handler
   that already wrote 254 leaves nothing for this pass to match. An Identity Map override
   retires its mapped target row, and a column selection that keeps the target's RowStatus
   is honoured.
   ========================================================= */

DECLARE
    @RET_SchemaName SYSNAME,
    @RET_TableName SYSNAME,
    @RET_GuidColumnName SYSNAME,
    @RET_RegistryGuid UNIQUEIDENTIFIER,
    @RET_Sql NVARCHAR(MAX),
    @RET_RowCount INT,
    @RET_TotalRowCount INT = 0,
    @RET_DetailsJson NVARCHAR(MAX);

DECLARE Retirement_Cursor CURSOR LOCAL FAST_FORWARD FOR
    SELECT DISTINCT
        tr.Guid,
        tr.SchemaName,
        tr.TableName,
        tr.GuidColumnName
    FROM SMigration.Metadata_StagedRows AS sr
    INNER JOIN #MetadataRowsToApply AS applyRows
        ON applyRows.StagedRowId = sr.ID
    INNER JOIN SMigration.Metadata_TableRegistry AS tr
        ON tr.Guid = sr.RegistryGuid
       AND tr.RowStatus NOT IN (0,254)
    INNER JOIN sys.columns AS c
        ON c.object_id = OBJECT_ID(QUOTENAME(tr.SchemaName) + N'.' + QUOTENAME(tr.TableName))
       AND c.name = N'RowStatus'
    WHERE sr.RunGuid = @RunGuid
      AND sr.RowStatus NOT IN (0,254)
      AND sr.DifferenceType = N'Update'
      AND sr.SourceRowStatus = 254;

OPEN Retirement_Cursor;

FETCH NEXT FROM Retirement_Cursor
INTO @RET_RegistryGuid, @RET_SchemaName, @RET_TableName, @RET_GuidColumnName;

WHILE @@FETCH_STATUS = 0
BEGIN
    SET @RET_Sql = N'
UPDATE t
SET t.RowStatus = 254
FROM ' + QUOTENAME(@RET_SchemaName) + N'.' + QUOTENAME(@RET_TableName) + N' AS t
INNER JOIN SMigration.Metadata_StagedRows AS sr
    ON sr.RunGuid = @RunGuid
   AND sr.RegistryGuid = @RegistryGuid
   AND sr.RowStatus NOT IN (0,254)
   AND sr.DifferenceType = N''Update''
   AND sr.SourceRowStatus = 254
INNER JOIN #MetadataRowsToApply AS applyRows
    ON applyRows.StagedRowId = sr.ID
LEFT JOIN SMigration.Metadata_IdentityMapOverrides AS ov
    ON ov.DatabaseName = @TargetDatabaseName
   AND ov.RegistryGuid = sr.RegistryGuid
   AND ov.SourceRowGuid = sr.SourceRowGuid
   AND ov.RowStatus NOT IN (0,254)
WHERE t.' + QUOTENAME(@RET_GuidColumnName) + N' = ISNULL(ov.TargetRowGuid, sr.SourceRowGuid)
  AND t.RowStatus NOT IN (0,254)
  AND
  (
      ov.ColumnSourceSelectionJson IS NULL
      OR EXISTS (SELECT 1 FROM OPENJSON(ov.ColumnSourceSelectionJson) WHERE [value] = N''RowStatus'')
  );

SET @RowCount = @@ROWCOUNT;';

    EXEC sys.sp_executesql
        @RET_Sql,
        N'@RunGuid UNIQUEIDENTIFIER, @RegistryGuid UNIQUEIDENTIFIER, @TargetDatabaseName SYSNAME, @RowCount INT OUTPUT',
        @RunGuid = @RunGuid,
        @RegistryGuid = @RET_RegistryGuid,
        @TargetDatabaseName = @TargetDatabaseName,
        @RowCount = @RET_RowCount OUTPUT;

    SET @RET_TotalRowCount += ISNULL(@RET_RowCount, 0);

    FETCH NEXT FROM Retirement_Cursor
    INTO @RET_RegistryGuid, @RET_SchemaName, @RET_TableName, @RET_GuidColumnName;
END;

CLOSE Retirement_Cursor;
DEALLOCATE Retirement_Cursor;

SET @RET_DetailsJson = CONCAT(N'{"retiredRowCount":', CONVERT(NVARCHAR(30), @RET_TotalRowCount), N'}');

EXEC SMigration.MetadataExecutionLog_Add
    @RunGuid = @RunGuid,
    @StepName = N'ApplyRetirements',
    @StepStatus = N'Succeeded',
    @Message = N'Source retirements applied.',
    @DetailsJson = @RET_DetailsJson;

UPDATE SMigration.Metadata_Run
SET
    RunStatus = N'AppliedUiMetadata',
    AppliedOnUtc = SYSUTCDATETIME()
WHERE Guid = @RunGuid
  AND RowStatus NOT IN (0,254);

EXEC SMigration.MetadataExecutionLog_Add
    @RunGuid = @RunGuid,
    @StepName = N'ApplyMetadataComplete',
    @StepStatus = N'Succeeded',
    @Message = N'Core and UI metadata apply handlers completed.',
    @DetailsJson = N'{"AppliedTables":["SCore.LanguageLabels","SCore.LanguageLabelTranslations","SCore.EntityDataTypes","SUserInterface.Icons","SCore.EntityTypes","SCore.EntityHobts","SUserInterface.DropDownListDefinitions","SCore.EntityPropertyGroups","SCore.EntityQueries","SCore.EntityProperties","SCore.EntityQueryParameters","SCore.EntityPropertyDependants","SUserInterface.GridDefinitions","SUserInterface.GridViewDefinitions","SUserInterface.GridViewColumnDefinitions","SJob.MilestoneTypes"]}';

COMMIT TRANSACTION;
END;
