    Source schema hash : 870B82A57F886EDE21DC67BF6A898AE26100D07BEF2DD60D93E0C0FD7CB91D0F
    Definition SHA-256 : DEA42EC78861748159223A5BCC01478C32242012CDA5F51D74FE26ABA8BEF101

    This deterministic file was synchronized from an explicitly selected, validated and accepted
    CymBuild_Dev source-definition snapshot. Review and commit the source-control diff before using
    it for promotion.
*/
SET ANSI_NULLS ON
GO
SET QUOTED_IDENTIFIER ON
GO
/* ---------------------------------------------------------------------------------------
   Trigger: SSop.QuoteItems AFTER UPDATE
   Fires when CreatedJobId changes from (<0 or NULL) to (>0)
   DEDUPES so you get 1 enqueue per JobId, even if multiple quoteitems consolidated.
--------------------------------------------------------------------------------------- */
CREATE OR ALTER TRIGGER [SSop].[tr_QuoteItems_EnqueueJobCreatedFromProposal]
ON [SSop].[QuoteItems]
AFTER UPDATE
AS
BEGIN
    SET NOCOUNT ON;

    IF NOT (UPDATE(CreatedJobId))
        RETURN;

    BEGIN TRY
        ;WITH Changed AS
        (
            SELECT
                  i.QuoteId
                , i.CreatedJobId
            FROM inserted i
            JOIN deleted d
              ON d.ID = i.ID
            WHERE ISNULL(d.CreatedJobId, -1) < 0
              AND ISNULL(i.CreatedJobId, -1) > 0
              AND i.RowStatus NOT IN (0,254)
        ),
        Dedup AS
        (
            SELECT DISTINCT
                  c.QuoteId
                , c.CreatedJobId
            FROM Changed c
            WHERE c.CreatedJobId > 0
              AND c.QuoteId > 0
        )
        SELECT *
        INTO #ToEnqueue
        FROM Dedup;

        DECLARE @JobId INT, @QuoteId INT;

        WHILE EXISTS (SELECT 1 FROM #ToEnqueue)
        BEGIN
            SELECT TOP (1)
                  @JobId = CreatedJobId
                , @QuoteId = QuoteId
            FROM #ToEnqueue
            ORDER BY CreatedJobId, QuoteId;

            EXEC SCore.IntegrationOutbox_EnqueueJobCreatedFromProposal
                 @JobId   = @JobId,
                 @QuoteId = @QuoteId;

            DELETE TOP (1)
            FROM #ToEnqueue;
        END
    END TRY
    BEGIN CATCH
        -- best-effort: never block quote/job pipeline
        RETURN;
    END CATCH
END;
GO

